  <noscript>
    <div class="curtain on">
      <div class="curtain-inner">
        <h1 class="wordmark">ALPEN</h1>
        <p class="tagline">This one needs JavaScript and WebGL — it is a 3D game.</p>
      </div>
    </div>
  </noscript>

  <!-- The only inline script on the page, and it is inline because of what it
       has to be in front of.

       Everything else here is a module, and a module cannot report on its own
       arrival: by the time a line of `main.js` runs, the engine, the game and
       the whole import graph have already been fetched and parsed, which on a
