       wall clock: the engine dominates a cold load, the horizon cache
       dominates a warm one. Nothing here animates on a timer. If a stage takes
       four seconds the bar sits still for four seconds, which is the honest
       thing for a progress bar to do and the reason the label says what is
       being waited for. -->
  <script>
    window.__alpenBoot = (function () {
      var stages = [
        { id: 'engine', weight: 0.42, label: 'Fetching the engine' },
        { id: 'mountain', weight: 0.30, label: 'Marching the horizon' },
        { id: 'snow', weight: 0.10, label: 'Decoding the snow' },
        { id: 'shaders', weight: 0.18, label: 'Compiling shaders' },
      ];
      var done = {};
      var root = document.querySelector('[data-loading]');
      var bar = document.querySelector('[data-loading-bar]');
      var fill = document.querySelector('[data-loading-fill]');
      var label = document.querySelector('[data-loading-label]');
      var curtain = document.querySelector('.curtain');
      var handled = false;   // a failure that has put its own message on screen
      var broken = false;    // …and one that has not
      if (curtain) curtain.setAttribute('aria-busy', 'true');

      function paint() {
        var value = 0;
        var waiting = null;
        for (var i = 0; i < stages.length; i++) {
          if (done[stages[i].id]) value += stages[i].weight;
          else if (!waiting) waiting = stages[i];
        }
        var pct = Math.round(value * 100);
        if (fill) fill.style.width = pct + '%';
        if (bar) bar.setAttribute('aria-valuenow', String(pct));
        if (curtain && (broken || !waiting)) curtain.setAttribute('aria-busy', 'false');
        /* A boot that died is not a boot that finished, and the difference
           has to reach the screen. Marking every stage done would hide the bar
           and put up "press any key to drop in" over a game that cannot start
           — an invitation to press a key that does nothing, which is worse
           than any error message. So a broken load keeps the bar where it
           stopped, says so, and never adds `loaded`. */
        if (broken) {
          if (root) root.classList.add('failed');
          if (label) label.textContent = 'Could not start · try reloading';
          return;
        }
        if (label) label.textContent = waiting ? waiting.label + ' · ' + pct + '%' : 'Ready';
        if (!waiting) {
          document.body.classList.add('loaded');
          // Left in the tree it would keep announcing a finished progress bar
          // every time the pause screen came back.
          if (root) root.hidden = true;
        }
      }

      paint();
      return {
        step: function (id) {
          if (done[id] || broken) return;
          done[id] = true;
          paint();
        },
        /* A load that cannot finish, by a route that has already put its own
           explanation on the page — the WebGL branch in `main.js` is the only
           one. Anything unresolved is reported as done, because the message
           beside it is now the page and a bar still counting under it would be
           contradicting it. */
        giveUp: function () {
          handled = true;
          for (var i = 0; i < stages.length; i++) done[stages[i].id] = true;
          paint();
        },
        // …and one that has not, which is every unexpected exception during
        // initialisation. See `paint`.
        fail: function () {
          if (handled || broken) return;
          broken = true;
          paint();
        },
      };
    }());
    /* A boot that died means there is no game behind the title card, and the
       card must stop pretending otherwise.

       IT IS REGISTERED IN THE CAPTURE PHASE, and that is not tidiness. Two
       completely different things arrive here. A script that *threw* fires a
       bubbling ErrorEvent at the window, which the default phase sees. A
       resource that failed to *load* — the engine 404ing, or any module in
       the graph — fires a plain event at the element that asked for it and
       does not bubble at all, so a window listener in the bubble phase never
       hears it. That second one is precisely the case with no other backstop:
       nothing in `main.js` runs, so nothing ever closes the first stage, and
       the card sits on "Fetching the engine" for as long as the tab is open.

       Everything else here is about not crying wolf. `ready` is set once the
       mountain has drawn a frame, and an exception after that belongs to the
       running game rather than to the loader — a wipeout that throws must not
       put a failure notice over a working run. And the source has to be ours,
       by whichever of the two names the event carries: extensions and injected
       scripts throw into this handler constantly, and a stylesheet or an icon
       that fails to load is not the game either. */
    window.addEventListener('error', function (e) {
      if (!window.__alpenBoot) return;
      if (document.body.classList.contains('ready')) return;
      var target = e && e.target;
      if (target && target !== window && target.nodeType === 1) {
        if (target.tagName !== 'SCRIPT') return;
        if (target.src && target.src.indexOf(location.origin) !== 0) return;
      } else if (e && e.filename && e.filename.indexOf(location.origin) !== 0) {
        return;
      }
      window.__alpenBoot.fail();
    }, true);
  </script>
  <script type="module" src="./js/main.js"></script>
</body>

</html>

