1	/* Seeded deterministic noise and deterministic randomness.
2	
3	   Both matter for the same reason: the mountain is generated on demand and
4	   thrown away behind the rider, so anything the world says about a patch of
5	   hill has to be a pure function of where that patch is. Nothing is stored,
6	   and looking at the same coordinate twice always answers the same. A run
7	   seed is mixed into every hash, so the mountain changes between runs while
8	   a shared seed recreates the same terrain, props, weather and skyline. That
9	   is what lets props be forgotten and re-spawned without the hill appearing
10	   to shuffle itself. */
11	
12	let worldSeed = 0;
13	
14	/* Accept the short base-36 codes used in the URL, arbitrary text for hand-
15	   named mountains, or a raw integer from crypto. */
16	function seedValue(value) {
17	  if (typeof value === 'number' && Number.isFinite(value)) return value >>> 0;
18	  const text = String(value ?? '').trim();
19	  if (/^[0-9a-z]{1,7}$/i.test(text)) return parseInt(text, 36) >>> 0;
20	
21	  // FNV-1a: small, stable, and sufficient for turning a label into a key.
22	  let h = 0x811c9dc5;
23	  for (let i = 0; i < text.length; i++) {
24	    h ^= text.charCodeAt(i);
25	    h = Math.imul(h, 0x01000193);
26	  }
27	  return h >>> 0;
28	}
29	
30	export function setWorldSeed(value) {
31	  worldSeed = seedValue(value);
32	  return worldSeed;
33	}
34	
35	export function getWorldSeed() {
36	  return worldSeed >>> 0;
37	}
38	
39	export function worldSeedCode(value = worldSeed) {
40	  return seedValue(value).toString(36).toUpperCase().padStart(7, '0');
41	}
42	
43	export function randomWorldSeed() {
44	  const values = new Uint32Array(1);
45	  if (globalThis.crypto?.getRandomValues) {
46	    globalThis.crypto.getRandomValues(values);
47	    return values[0] >>> 0;
48	  }
49	  return (Date.now() ^ Math.floor((globalThis.performance?.now?.() || 0) * 1000)) >>> 0;
50	}
51	
52	const INV_2_32 = 1 / 4294967296;
53	
54	/* One round of xxhash-shaped mixing over two integers. Returns [0, 1). */
55	export function hash2(x, y, seed = 0) {
56	  const runSeed = (seed | 0) ^ (worldSeed | 0);
57	  let h = Math.imul(x | 0, 0x27d4eb2d) ^ Math.imul(y | 0, 0x165667b1)
58	    ^ Math.imul(runSeed, 0x9e3779b1);
59	  h = Math.imul(h ^ (h >>> 15), 0x85ebca6b);
60	  h = Math.imul(h ^ (h >>> 13), 0xc2b2ae35);
61	  return ((h ^ (h >>> 16)) >>> 0) * INV_2_32;
62	}
63	
64	/* Value noise: smoothstep between four hashed lattice corners. Cheaper than
65	   gradient noise and, at these amplitudes, indistinguishable — the hill is
66	   read at 240 pixels tall through fog. Returns [0, 1). */
67	export function noise2(x, y, seed = 0) {
68	  const x0 = Math.floor(x);
69	  const y0 = Math.floor(y);
70	  const fx = x - x0;
71	  const fy = y - y0;
72	  const ux = fx * fx * (3 - 2 * fx);
73	  const uy = fy * fy * (3 - 2 * fy);
74	
75	  const runSeed = (seed | 0) ^ (worldSeed | 0);
76	  const seedTerm = Math.imul(runSeed, 0x9e3779b1);
77	  const base0 = Math.imul(y0 | 0, 0x165667b1) ^ seedTerm;
78	  const base1 = Math.imul((y0 + 1) | 0, 0x165667b1) ^ seedTerm;
79	  const hx0 = Math.imul(x0 | 0, 0x27d4eb2d);
80	  const hx1 = Math.imul((x0 + 1) | 0, 0x27d4eb2d);
81	
82	  let hA = hx0 ^ base0;
83	  hA = Math.imul(hA ^ (hA >>> 15), 0x85ebca6b);
84	  hA = Math.imul(hA ^ (hA >>> 13), 0xc2b2ae35);
85	  const a = ((hA ^ (hA >>> 16)) >>> 0) * INV_2_32;
86	
87	  let hB = hx1 ^ base0;
88	  hB = Math.imul(hB ^ (hB >>> 15), 0x85ebca6b);
89	  hB = Math.imul(hB ^ (hB >>> 13), 0xc2b2ae35);
90	  const b = ((hB ^ (hB >>> 16)) >>> 0) * INV_2_32;
91	
92	  let hC = hx0 ^ base1;
93	  hC = Math.imul(hC ^ (hC >>> 15), 0x85ebca6b);
94	  hC = Math.imul(hC ^ (hC >>> 13), 0xc2b2ae35);
95	  const c = ((hC ^ (hC >>> 16)) >>> 0) * INV_2_32;
96	
97	  let hD = hx1 ^ base1;
98	  hD = Math.imul(hD ^ (hD >>> 15), 0x85ebca6b);
99	  hD = Math.imul(hD ^ (hD >>> 13), 0xc2b2ae35);
100	  const d = ((hD ^ (hD >>> 16)) >>> 0) * INV_2_32;
101	
102	  const top = a + (b - a) * ux;
103	  const bottom = c + (d - c) * ux;
104	  return top + (bottom - top) * uy;
105	}
106	
107	/* The same, centred: [-1, 1). */
108	export function snoise2(x, y, seed = 0) {
109	  return noise2(x, y, seed) * 2 - 1;
110	}
111	
112	/* A tiny stream of numbers from one integer key — for a band of hill that
113	   wants a dozen decisions made about it and nothing kept. mulberry32. */
114	export function stream(key) {
115	  let a = ((key | 0) ^ (worldSeed | 0)) + 0x6d2b79f5;
116	  return () => {
117	    a = (a + 0x6d2b79f5) | 0;
118	    let t = a;
119	    t = Math.imul(t ^ (t >>> 15), t | 1);
120	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
121	    return ((t ^ (t >>> 14)) >>> 0) * INV_2_32;
122	  };
123	}
