1	/* ==========================================================================
2	   Alpen — the frame around the game
3	
4	   There are two canvases covering the visual viewport. The world renders at
5	   native display resolution and the read-out is a separate high-DPI bitmap
6	   surface, so both stay crisp while the 5×7 type keeps the console character.
7	
8	   What is left below is the furniture around the game rather than the game
9	   frame itself: the start and pause curtain, and the touch pad. Those stay
10	   DOM on purpose. They are not part of the picture — they are the page the
11	   picture is sitting on, and holding them to a 5×7 grid would mean a
12	   paragraph of explanation nobody could read.
13	
14	   The palette is the company's, used the company's way: mint marks
15	   structure and anything you can act on, yellow marks emphasis.
16	   ========================================================================== */
17	
18	:root {
19	  --gold: #ffab00;
20	  --ice: #00d4ff;
21	  --mint: #00d4ff;
22	  --yellow: #ffab00;
23	  --ink: #0d1420;
24	  --paper: #fafafa;
25	  --fg-muted: rgba(250, 250, 250, 0.66);
26	  --fg-faint: rgba(250, 250, 250, 0.46);
27	  --label: 0.72rem;
28	  --label-track: 0.16em;
29	  --ease: cubic-bezier(0.22, 1, 0.36, 1);
30	  --gutter: clamp(0.9rem, 2.4vw, 2rem);
31	}
32	
33	*,
34	*::before,
35	*::after {
36	  box-sizing: border-box;
37	  margin: 0;
38	  padding: 0;
39	}
40	
41	html,
42	body {
43	  height: 100%;
44	  overflow: hidden;
45	  overscroll-behavior: none;
46	}
47	
48	body {
49	  position: fixed;
50	  inset: 0;
51	  background: var(--ink);
52	  color: var(--paper);
53	  font-family: 'Courier New', Courier, monospace;
54	  -webkit-font-smoothing: antialiased;
55	  touch-action: none;
56	  -webkit-tap-highlight-color: transparent;
57	}
58	
59	/* The playfield is the window. Its backing store is managed by retro.js. */
60	#stage {
61	  position: absolute;
62	  inset: 0;
63	  width: 100%;
64	  height: 100%;
65	  display: block;
66	  image-rendering: auto;
67	}
68	
69	body:not(.ready) #stage {
70	  visibility: hidden;
71	}
72	
73	/* HUD
74	   ==========================================================================
75	   The readout canvas handles all game HUD elements and bitmap menu screens. */
76	.hud {
77	  position: absolute;
78	  inset: 0;
79	  pointer-events: none;
80	  opacity: 0;
81	  transition: opacity 0.6s var(--ease);
82	}
83	
84	body.ready .hud {
85	  opacity: 1;
86	}
87	
88	.readout {
89	  position: absolute;
90	  left: 0;
91	  top: 0;
92	  width: 100%;
93	  height: 100%;
94	  display: block;
95	  image-rendering: auto;
96	}
97	
98	/* A canvas hands a screen reader nothing at all, so hud.js keeps a paragraph
99	   of numbers fed behind it. Clipped rather than hidden: `display: none` and
100	   `visibility: hidden` would take it out of the accessibility tree too,
101	   which is the one thing it is for. */
102	.sr-only {
103	  position: absolute;
104	  width: 1px;
105	  height: 1px;
106	  margin: -1px;
107	  overflow: hidden;
108	  clip-path: inset(50%);
109	  white-space: nowrap;
110	}
111	
112	/* Curtain — start, and pause
113	   ========================================================================== */
114	.curtain {
115	  position: absolute;
116	  inset: 0;
117	  display: grid;
118	  place-items: center;
119	  padding: calc(var(--gutter) * 1.5);
120	  background: radial-gradient(120% 90% at 50% 40%, rgba(9, 15, 26, 0.55), rgba(9, 15, 26, 0.92));
121	  opacity: 0;
122	  visibility: hidden;
123	  transition: opacity 0.35s var(--ease), visibility 0.35s;
124	  cursor: pointer;
125	}
126	
127	.curtain.on {
128	  opacity: 1;
129	  visibility: visible;
130	}
131	
132	/* Once the canvas menus own the picture, the curtain is only a click-catcher
133	   and must not shade them: the bitmap card carries its own backdrop, and this
134	   gradient stacked on top of it dimmed the menu text by up to ninety per cent
135	   at the edges of the frame — and blacked out the attract run behind it. */
136	body.ready .curtain {
137	  background: transparent;
138	}
139	
140	.curtain-inner {
141	  width: 100%;
142	  max-width: 620px;
143	  max-height: 100%;
144	  overflow-y: auto;
145	  text-align: left;
146	}
147	
148	/* The loading screen is the DOM's one remaining visual job. The canvas
149	   read-out draws every menu once the game runs, but it cannot draw a pixel
150	   until the engine has been fetched and the first frame rendered — which is
151	   precisely the period the loading card covers. So until the body is
152	   `.ready`, the curtain's inner column comes out of its screen-reader
153	   clipping and is the boot screen: wordmark, controls, and the stage-by-
154	   stage progress bar the inline script feeds. (It is also what shows the
155	   WebGL failure notice, which the clipping used to hide entirely.) The
156	   first rendered frame collapses it back to sr-only and the bitmap title
157	   card takes over. */
158	body:not(.ready) .curtain-inner.sr-only {
159	  position: static;
160	  width: 100%;
161	  height: auto;
162	  margin: 0;
163	  overflow: hidden auto;
164	  clip-path: none;
165	  white-space: normal;
166	}
167	
168	.eyebrow {
