/* ==========================================================================
   Alpen — the frame around the game

   There are two canvases covering the visual viewport. The world renders at
   native display resolution and the read-out is a separate high-DPI bitmap
   surface, so both stay crisp while the 5×7 type keeps the console character.

   What is left below is the furniture around the game rather than the game
   frame itself: the start and pause curtain, and the touch pad. Those stay
   DOM on purpose. They are not part of the picture — they are the page the
   picture is sitting on, and holding them to a 5×7 grid would mean a
   paragraph of explanation nobody could read.

   The palette is the company's, used the company's way: mint marks
   structure and anything you can act on, yellow marks emphasis.
   ========================================================================== */

:root {
  --gold: #ffab00;
  --ice: #00d4ff;
  --mint: #00d4ff;
  --yellow: #ffab00;
  --ink: #0d1420;
  --paper: #fafafa;
  --fg-muted: rgba(250, 250, 250, 0.66);
  --fg-faint: rgba(250, 250, 250, 0.46);
  --label: 0.72rem;
  --label-track: 0.16em;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
  --gutter: clamp(0.9rem, 2.4vw, 2rem);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  background: var(--ink);
  color: var(--paper);
  font-family: 'Courier New', Courier, monospace;
  -webkit-font-smoothing: antialiased;
  touch-action: none;
  -webkit-tap-highlight-color: transparent;
}

/* The playfield is the window. Its backing store is managed by retro.js. */
#stage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: auto;
}

body:not(.ready) #stage {
  visibility: hidden;
}

/* HUD
   ==========================================================================
   The readout canvas handles all game HUD elements and bitmap menu screens. */
.hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.6s var(--ease);
}

body.ready .hud {
  opacity: 1;
}

.readout {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: auto;
}

/* A canvas hands a screen reader nothing at all, so hud.js keeps a paragraph
   of numbers fed behind it. Clipped rather than hidden: `display: none` and
   `visibility: hidden` would take it out of the accessibility tree too,
   which is the one thing it is for. */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* Curtain — start, and pause
   ========================================================================== */
.curtain {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: calc(var(--gutter) * 1.5);
  background: radial-gradient(120% 90% at 50% 40%, rgba(9, 15, 26, 0.55), rgba(9, 15, 26, 0.92));
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.35s var(--ease), visibility 0.35s;
  cursor: pointer;
}

.curtain.on {
  opacity: 1;
  visibility: visible;
}

/* Once the canvas menus own the picture, the curtain is only a click-catcher
   and must not shade them: the bitmap card carries its own backdrop, and this
   gradient stacked on top of it dimmed the menu text by up to ninety per cent
   at the edges of the frame — and blacked out the attract run behind it. */
body.ready .curtain {
  background: transparent;
}

.curtain-inner {
  width: 100%;
  max-width: 620px;
  max-height: 100%;
  overflow-y: auto;
  text-align: left;
}

/* The loading screen is the DOM's one remaining visual job. The canvas
   read-out draws every menu once the game runs, but it cannot draw a pixel
   until the engine has been fetched and the first frame rendered — which is
   precisely the period the loading card covers. So until the body is
   `.ready`, the curtain's inner column comes out of its screen-reader
   clipping and is the boot screen: wordmark, controls, and the stage-by-
   stage progress bar the inline script feeds. (It is also what shows the
   WebGL failure notice, which the clipping used to hide entirely.) The
   first rendered frame collapses it back to sr-only and the bitmap title
   card takes over. */
body:not(.ready) .curtain-inner.sr-only {
  position: static;
  width: 100%;
  height: auto;
  margin: 0;
  overflow: hidden auto;
  clip-path: none;
  white-space: normal;
}

.eyebrow {
  font-size: var(--label);
  font-weight: 600;
  letter-spacing: var(--label-track);
  text-transform: uppercase;
  color: var(--mint);
}

.wordmark {
  margin-top: 0.4rem;
  font-size: clamp(3.2rem, 13vw, 6.5rem);
  font-weight: 700;
  line-height: 0.92;
  letter-spacing: -0.05em;
}

.spark {
  display: inline-block;
  margin-left: 0.06em;
  font-size: 0.26em;
  font-style: normal;
  color: var(--yellow);
  vertical-align: 0.55em;
}

.tagline {
  margin-top: 1rem;
  max-width: 48ch;
  color: var(--fg-muted);
  font-size: clamp(0.95rem, 2.2vw, 1.05rem);
  line-height: 1.6;
  text-wrap: pretty;
}

.keys {
  margin-top: 1.8rem;
  display: grid;
  gap: 0.55rem;
  border-top: 1px solid rgba(250, 250, 250, 0.14);
  padding-top: 1.2rem;
}

.keys > div {
  display: flex;
  align-items: baseline;
  gap: 0.4rem;
  flex-wrap: wrap;
}

.keys dt {
  flex: 0 0 auto;
  min-width: 1.9rem;
  padding: 0.22rem 0.45rem;
  text-align: center;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mint);
  border: 1px solid rgba(0, 255, 195, 0.4);
}

.keys dd {
  margin-left: 0.5rem;
  color: var(--fg-muted);
  font-size: 0.9rem;
}

.touch-guide {
  display: none;
}

body.touch .keys {
  display: none;
}

body.touch .touch-guide {
  margin-top: 1.6rem;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.9rem 1.1rem;
  border-top: 1px solid rgba(250, 250, 250, 0.14);
  padding-top: 1.15rem;
}

.touch-guide > div {
  min-width: 0;
}

.touch-guide dt {
  color: var(--mint);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.touch-guide dd {
  margin-top: 0.26rem;
  color: var(--fg-muted);
  font-size: 0.86rem;
  line-height: 1.35;
}

.go {
  margin-top: 1.8rem;
  font-size: var(--label);
  font-weight: 600;
  letter-spacing: var(--label-track);
  text-transform: uppercase;
  color: var(--yellow);
  animation: pulse 2.4s var(--ease) infinite;
}

.go-key,
.go-tap {
  margin-right: 0.35em;
}

body.touch .go-key,
.go-tap {
  display: none;
}

body.touch .go-tap {
  display: inline;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}

.back {
  display: inline-block;
  margin-top: 1.6rem;
  color: var(--fg-faint);
  font-size: 0.82rem;
  letter-spacing: 0.04em;
  text-decoration: none;
  transition: color 0.25s var(--ease);
  pointer-events: auto;
}

.back:hover,
.back:focus-visible {
  color: var(--mint);
}

.curtain[data-screen='paused'] .start-only { display: none; }
.curtain[data-screen='start'] .pause-only { display: none; }

/* Loading
   ==========================================================================
   The bar occupies exactly the space the invitation is about to, so the
   title card does not jump when the mountain finishes arriving. Mint,
   because mint is the colour of structure and of anything you can act on,
   and this is the thing standing between the player and acting. */
.loading {
  margin-top: 1.8rem;
}

.loading-track {
  width: min(20rem, 100%);
  height: 3px;
  background: rgba(250, 250, 250, 0.14);
  overflow: hidden;
}

.loading-fill {
  display: block;
  width: 0;
  height: 100%;
  background: var(--mint);
  /* Stages land at their own pace and the bar should not pretend otherwise —
     this eases the step rather than filling on a clock of its own. */
  transition: width 0.35s var(--ease);
}

.loading-label {
  margin-top: 0.6rem;
  font-size: var(--label);
  font-weight: 600;
  letter-spacing: var(--label-track);
  text-transform: uppercase;
  color: var(--fg-faint);
}

/* A boot that died keeps the bar exactly where it stopped and stops being
   mint, because mint is the colour of things you can act on and this is not
   one. Yellow is the palette's emphasis, and there is nothing else on this
   screen for it to compete with. */
.loading.failed .loading-fill { background: var(--yellow); }
.loading.failed .loading-label { color: var(--yellow); }

/* The invitation waits for the mountain. Both are `.go`'s own margin apart,
   so exactly one of them is on screen at any moment and neither moves. */
body:not(.loaded) .curtain[data-screen='start'] .go { display: none; }

@media (prefers-reduced-motion: reduce) {
  .loading-fill { transition: none; }
}

/* Touch pad
   ========================================================================== */
.pad {
  position: absolute;
  inset: auto 0 0 0;
  display: none;
  align-items: flex-end;
  justify-content: space-between;
  gap: 0.6rem;
  padding-top: var(--gutter);
  padding-right: max(var(--gutter), env(safe-area-inset-right));
  padding-bottom: max(var(--gutter), env(safe-area-inset-bottom));
  padding-left: max(var(--gutter), env(safe-area-inset-left));
  pointer-events: none;
  opacity: 1;
  visibility: visible;
  transition: opacity 0.22s var(--ease), visibility 0.22s;
}

body.touch .pad {
  display: flex;
}

/* The curtain is a modal surface. Its touch controls describe how to enter
   the run; the live pad belongs to the run and appears when the curtain goes. */
body.touch:has(.curtain.on) .pad {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.pad-tools {
  position: fixed;
  top: max(var(--gutter), env(safe-area-inset-top));
  left: 50%;
  display: flex;
  gap: 0.5rem;
  transform: translateX(-50%);
  pointer-events: auto;
}

.pad-tool {
  min-width: 2.8rem;
  min-height: 2.5rem;
  padding: 0 0.55rem;
  opacity: 0.72;
}

.pad-tool[aria-pressed='true'] {
  color: var(--yellow);
  border-color: var(--yellow);
}

.pad-stack {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.pad-row {
  display: flex;
  gap: 0.5rem;
}

.pad-btn {
  pointer-events: auto;
  min-width: 3.2rem;
  min-height: 3.2rem;
  padding: 0 0.7rem;
  font-family: inherit;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--paper);
  background: rgba(13, 20, 32, 0.5);
  border: 1px solid rgba(250, 250, 250, 0.28);
  backdrop-filter: blur(3px);
  transition: background-color 0.12s linear, border-color 0.12s linear;
  touch-action: none;
  user-select: none;
}

.pad-btn.on {
  background: rgba(0, 255, 195, 0.28);
  border-color: var(--mint);
}

.pad-jump {
  min-height: 4.2rem;
  color: var(--ink);
  background: rgba(255, 196, 0, 0.85);
  border-color: var(--yellow);
}

.pad-left,
.pad-right {
  min-width: 4.2rem;
  min-height: 4.2rem;
  font-size: 1rem;
}

@media (max-width: 560px) {
  .pad-wide { min-height: 2.6rem; }
  .keys dd { font-size: 0.84rem; }
  .curtain { padding: max(var(--gutter), env(safe-area-inset-top)) var(--gutter); }
  .curtain-inner { max-width: 28rem; }
  .wordmark { font-size: clamp(3rem, 16vw, 4.6rem); }
  .tagline { line-height: 1.48; }
}

/* A phone turned sideways has ample width and almost no vertical budget.
   Keep the four touch verbs and the actual drop-in action in the first frame
   instead of making the player discover that the title card scrolls. */
@media (max-height: 500px) and (orientation: landscape) {
  body.touch .curtain {
    padding: max(0.65rem, env(safe-area-inset-top))
      max(var(--gutter), env(safe-area-inset-right))
      max(0.65rem, env(safe-area-inset-bottom))
      max(var(--gutter), env(safe-area-inset-left));
  }

  body.touch .curtain-inner { max-width: 48rem; }
  body.touch .eyebrow { font-size: 0.62rem; }
  body.touch .wordmark { margin-top: 0.1rem; font-size: 2.8rem; }
  body.touch .tagline {
    margin-top: 0.45rem;
    max-width: 66ch;
    font-size: 0.78rem;
    line-height: 1.35;
  }

  body.touch .touch-guide {
    margin-top: 0.65rem;
    gap: 0.35rem 1rem;
    padding-top: 0.55rem;
  }

  body.touch .touch-guide dt { font-size: 0.64rem; }
  body.touch .touch-guide dd {
    margin-top: 0.08rem;
    font-size: 0.75rem;
    line-height: 1.2;
  }

  body.touch .go { margin-top: 0.65rem; }
  body.touch .back { margin-top: 0.55rem; }
}

@media (prefers-reduced-motion: reduce) {
  .go { animation: none; }
  * { transition-duration: 0.01ms !important; }
}

