/* ==========================================================================
   Sommer — the frame around the game

   Same shape as Alpen's frame: the world canvas below, a high-DPI readout
   canvas above it, and DOM only for the curtain and the touch pad. The
   palette turns to summer — leaf green marks structure and anything you can
   act on, sun amber marks emphasis.
   ========================================================================== */

:root {
  --sun: #ffb300;
  --leaf: #6ee86e;
  --mint: #6ee86e;
  --yellow: #ffb300;
  --ink: #0d1a10;
  --paper: #fbfaf6;
  --fg-muted: rgba(251, 250, 246, 0.66);
  --fg-faint: rgba(251, 250, 246, 0.46);
  --label: 0.72rem;
  --label-track: 0.16em;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
  --gutter: clamp(0.9rem, 2.4vw, 2rem);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  background: var(--ink);
  color: var(--paper);
  font-family: 'Courier New', Courier, monospace;
  -webkit-font-smoothing: antialiased;
  touch-action: none;
  -webkit-tap-highlight-color: transparent;
}

#stage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: auto;
}

body:not(.ready) #stage {
  visibility: hidden;
}

/* HUD
   ========================================================================== */
.hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.6s var(--ease);
}

body.ready .hud {
  opacity: 1;
}

.readout {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: auto;
}

/* Clipped rather than hidden so it stays in the accessibility tree. */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* Curtain — start, and pause
   ========================================================================== */
.curtain {
  position: absolute;
  inset: 0;
  display: grid;
