.go-key,
.go-tap {
  margin-right: 0.35em;
}

body.touch .go-key,
.go-tap {
  display: none;
}

body.touch .go-tap {
  display: inline;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}

.curtain[data-screen='paused'] .start-only { display: none; }
.curtain[data-screen='start'] .pause-only { display: none; }

