1	/* Input.
2	
3	   Six commands the rider can be given, and the game never asks about keys:
4	
5	     turn        -1 … 1, and it ramps rather than switching, so a tap is a
6	                 nudge and a hold is a full-lock carve
7	     tuck        powered tuck; accelerate up to the current flow speed cap
8	     brake       heel-side speed check; pivot across travel and sideslip
9	     jump        held to charge, released to pop
10	     trickGrab   Q — reach down and hold the board
11	     trickFlip   E — rotate
12	
13	   The ramp on `turn` is the only clever part, and it is worth it: a digital
14	   key held against an analogue steering model feels like a switch unless
15	   something in between gives it a rise time. */
16	
17	const BINDINGS = {
18	  left: ['KeyA', 'ArrowLeft'],
19	  right: ['KeyD', 'ArrowRight'],
20	  tuck: ['KeyW', 'ArrowUp'],
21	  brake: ['KeyS', 'ArrowDown'],
22	  jump: ['Space'],
23	  grab: ['KeyQ'],
24	  flip: ['KeyE'],
25	};
26	
27	/* How fast `turn` reaches the key that is held, and how fast it comes back.
28	
29	   These are the rise time of the steering, and the rise time is most of what
30	   "sensitive" means to a player. At 9 the axis went from nothing to full lock
31	   in about a fifth of a second, which on a model where the board's edge angle
32	   *is* the input meant a tap put the board most of the way over — and since
33	   the grip a given edge angle asks for goes as the square of the speed, a tap
34	   at speed was an instant demand for grip that did not exist. Rolling a board
35	   onto its edge is a deliberate movement of the whole body and it takes about
36	   twice this long in life. Slower in than out, because letting an edge go is
37	   the one thing a rider does quickly. */
38	const RAMP = 7.5;
39	const RELEASE = 12;
40	
41	/* The latched tap is measured in physics steps, not in rendered frames.
42	
43	   `jumpPulse` is 0 when there is none, 1 while the sampled press is being
44	   shown, and 2 while the sampled release is. It only advances once a physics
45	   step has actually looked at it, which `stepped()` reports — and that is the
46	   whole of the fix for an ollie that silently never happened.
47	
48	   The rider reads `state` from inside the fixed 120 Hz loop, and a display
49	   faster than 120 Hz runs frames that step the physics zero times. A pulse
50	   retired on frame boundaries therefore had a chance of living and dying
51	   entirely inside one of those frames, having been seen by nothing. Measured
52	   against the real loop with ten tapped ollies: one lost at 144 Hz, three at
53	   165 Hz, and at 240 Hz the tap never worked at all. */
54	const PULSE_NONE = 0;
55	const PULSE_PRESS = 1;
56	const PULSE_RELEASE = 2;
57	
58	/* Where a stick starts being a steering input. Real thumbsticks rest off
59	   centre — a worn one sits at 0.15 all day — so the zone is generous, and
60	   what leaves it is rescaled to start from zero rather than stepping
61	   straight to the zone's edge. */
62	const GP_DEADZONE = 0.18;
63	
64	export function createInput(target, hooks = {}) {
65	  const down = new Set();
66	  let jumpPressedSinceUpdate = false;
67	  let jumpTapPending = false;
68	  let jumpPulse = PULSE_NONE;
69	  let jumpPulseSeen = false;
70	  // Gamepad edge state — see the pad block in `update`.
71	  let gamepadSuppressed = false;
72	  let gpJumpHeld = false;
73	  let gpJumpStepSeen = false;
74	  const state = {
75	    turn: 0, tuck: false, brake: false, jump: false,
76	    trickGrab: false, trickFlip: false,
77	    anyPressed: false, touch: false,
78	  };
79	
80	  // Touch overrides live alongside the keys rather than replacing them, so
81	  // a laptop with a touchscreen can use either without a mode switch
82	  const touch = { left: false, right: false, tuck: false, brake: false, jump: false, grab: false, flip: false };
83	
84	  const held = (name) => BINDINGS[name].some((c) => down.has(c)) || touch[name];
85	
86	  const CODES = new Set(Object.values(BINDINGS).flat());
87	
88	  function onKey(e, isDown) {
89	    const bound = CODES.has(e.code);
90	    const jumpKey = BINDINGS.jump.includes(e.code);
91	    // Space and the arrows scroll the page otherwise, which on a game that
92	    // fills the viewport is a bug rather than a preference. Repeats included:
93	    // the key is still down, so the page would still scroll.
94	    if (bound) e.preventDefault();
95	
96	    // Auto-repeat is the browser saying the key is still held, which we
97	    // already know. Forwarding it turned "hold M" into a mute toggle running
98	    // at the repeat rate, and "hold Escape" into pause flapping whose final
99	    // state depended on exactly when you let go.
100	    if (isDown && e.repeat) return;
101	
102	    if (bound) {
103	      if (isDown) {
104	        if (!down.has(e.code)) {
105	          state.anyPressed = true;
106	          if (jumpKey) jumpPressedSinceUpdate = true;
107	        }
108	        down.add(e.code);
109	      } else {
110	        if (jumpKey && jumpPressedSinceUpdate && down.has(e.code)) jumpTapPending = true;
111	        down.delete(e.code);
112	      }
113	    }
114	    if (isDown && hooks.key) hooks.key(e);
115	  }
116	
117	  const keydown = (e) => onKey(e, true);
118	  const keyup = (e) => onKey(e, false);
119	  const blur = () => clear();
120	
121	  target.addEventListener('keydown', keydown);
122	  target.addEventListener('keyup', keyup);
123	  window.addEventListener('blur', blur);
124	  let hasGamepads = false;
125	  window.addEventListener('gamepadconnected', () => hasGamepads = true);
126	  window.addEventListener('gamepaddisconnected', () => {
127	    hasGamepads = (navigator.getGamepads ? navigator.getGamepads() : []).filter(g => g).length > 0;
128	  });
129	
130	  function update(dt) {
131	    /* The pad, folded in beside the keys rather than over them.
132	
133	       Reading it is necessarily a poll — the Gamepad API has no stick
134	       events — and the fold used to be a straight override: any non-zero
135	       stick beat the keyboard, so a controller with ordinary rest drift
136	       plugged in anywhere on the machine permanently killed A and D with
137	       nothing on screen to say why. Axes now pass a real dead zone and are
138	       rescaled from its edge, several pads OR together instead of the last
139	       in the array silencing the rest, and steering takes whichever of pad
140	       and keys is asking harder. */
141	    let gpTurn = 0, gpTuck = false, gpBrake = false, gpJump = false, gpGrab = false, gpFlip = false;
142	    if (hasGamepads) {
143	      const gamepads = navigator.getGamepads ? navigator.getGamepads() : [];
144	      for (let i = 0; i < gamepads.length; i++) {
145	        const gp = gamepads[i];
146	        if (!gp) continue;
147	        const raw = gp.axes[0] || 0;   // left stick X
148	        const mag = Math.abs(raw);
149	        if (mag > GP_DEADZONE) {
150	          const scaled = Math.sign(raw)
151	            * Math.min(1, (mag - GP_DEADZONE) / (1 - GP_DEADZONE));
152	          if (Math.abs(scaled) > Math.abs(gpTurn)) gpTurn = scaled;
153	        }
154	        // The d-pad is a pair, not two overrides: right used to silently win
155	        // over a held left, and either over a stick deflected the other way.
156	        const dpad = (gp.buttons[15]?.pressed ? 1 : 0) - (gp.buttons[14]?.pressed ? 1 : 0);
157	        if (Math.abs(dpad) > Math.abs(gpTurn)) gpTurn = dpad;
158	        gpTuck = gpTuck || !!gp.buttons[7]?.pressed || !!gp.buttons[12]?.pressed;   // RT · d-up
