      if (jumpPulseSeen) {
        jumpPulse = PULSE_RELEASE;
        jumpPulseSeen = false;
        state.jump = false;
      } else {
        state.jump = true;
      }
    } else if (jumpPulse === PULSE_RELEASE) {
      if (jumpPulseSeen) {
        jumpPulse = PULSE_NONE;
        jumpPulseSeen = false;
        state.jump = held('jump') || gpJump;
      } else {
        state.jump = false;
      }
    } else if (jumpTapPending) {
      state.jump = true;
      jumpTapPending = false;
      jumpPulse = PULSE_PRESS;
      jumpPulseSeen = false;
    } else {
      state.jump = held('jump') || gpJump;
    }
    jumpPressedSinceUpdate = false;
  }

  /* Called once per physics step by whoever owns the fixed-step loop. */
  function stepped() {
    if (jumpPulse !== PULSE_NONE) jumpPulseSeen = true;
    if (gpJumpHeld && state.jump) gpJumpStepSeen = true;
  }

  function bindTouch(root) {
    state.touch = true;
    root.querySelectorAll('[data-key]').forEach((el) => {
      const name = el.dataset.key;
      let keyboardPulse = 0;
      const set = (v, e) => {
        e.preventDefault();
        touch[name] = v;
        if (v) state.anyPressed = true;
        el.classList.toggle('on', v);
      };
      el.addEventListener('pointerdown', (e) => {
        el.setPointerCapture?.(e.pointerId);
        set(true, e);
      });
      el.addEventListener('pointerup', (e) => {
        if (el.hasPointerCapture?.(e.pointerId)) el.releasePointerCapture(e.pointerId);
        set(false, e);
      });
      el.addEventListener('pointercancel', (e) => set(false, e));
      el.addEventListener('lostpointercapture', (e) => set(false, e));
      el.addEventListener('click', (e) => {
        if (e.detail !== 0) return;
        set(true, e);
        window.clearTimeout(keyboardPulse);
        keyboardPulse = window.setTimeout(() => {
          touch[name] = false;
          el.classList.remove('on');
        }, 160);
      });
    });
  }

  function dispose() {
    target.removeEventListener('keydown', keydown);
    target.removeEventListener('keyup', keyup);
    window.removeEventListener('blur', blur);
  }

  /* Pause reset: drop what the game inferred, keep what the hands are doing.
     See alpen's input.js for why emptying `down` here would eat held keys. */
  function calm() {
    state.turn = 0;
    state.jump = false;
    jumpPressedSinceUpdate = false;
    jumpTapPending = false;
    jumpPulse = PULSE_NONE;
    jumpPulseSeen = false;
  }

  /* Hard reset, for when the key states can no longer be trusted. */
  function clear() {
    down.clear();
    for (const k of Object.keys(touch)) touch[k] = false;
    gamepadSuppressed = true;
    gpJumpHeld = false;
    gpJumpStepSeen = false;
    calm();
  }

  return { state, update, stepped, bindTouch, dispose, clear, calm };
}

