   commentary on every decision here). Four commands the rider can be given,
   and the game never asks about keys:

     turn    -1 … 1, ramped rather than switched, so a tap is a nudge and a
             hold is a full-lean turn
     pedal   sprint; accelerate up to the speed the legs allow
     brake   both levers; scrub speed, lock the rear if held hard
     jump    held to preload, released to bunny-hop */

const BINDINGS = {
  left: ['KeyA', 'ArrowLeft'],
  right: ['KeyD', 'ArrowRight'],
  pedal: ['KeyW', 'ArrowUp'],
  brake: ['KeyS', 'ArrowDown'],
  jump: ['Space'],
};

/* Rise time of the steering — most of what "sensitive" means to a player.
   Slower in than out, because letting the bars go straight is the one thing
   a rider does quickly. */
const RAMP = 7.5;
const RELEASE = 12;

/* The latched tap is measured in physics steps, not rendered frames — a
   display faster than 120 Hz runs frames that step the physics zero times,
   and a tap retired on frame boundaries can live and die inside one of
   those, seen by nothing. */
const PULSE_NONE = 0;
const PULSE_PRESS = 1;
const PULSE_RELEASE = 2;

const GP_DEADZONE = 0.18;

export function createInput(target, hooks = {}) {
  const down = new Set();
  let jumpPressedSinceUpdate = false;
  let jumpTapPending = false;
  let jumpPulse = PULSE_NONE;
  let jumpPulseSeen = false;
  let gamepadSuppressed = false;
  let gpJumpHeld = false;
  let gpJumpStepSeen = false;
  const state = {
    turn: 0, pedal: false, brake: false, jump: false,
    anyPressed: false, touch: false,
  };

  // Touch overrides live alongside the keys rather than replacing them.
  const touch = { left: false, right: false, pedal: false, brake: false, jump: false };

  const held = (name) => BINDINGS[name].some((c) => down.has(c)) || touch[name];

  const CODES = new Set(Object.values(BINDINGS).flat());

  function onKey(e, isDown) {
    const bound = CODES.has(e.code);
    const jumpKey = BINDINGS.jump.includes(e.code);
    if (bound) e.preventDefault();
    if (isDown && e.repeat) return;

    if (bound) {
      if (isDown) {
        if (!down.has(e.code)) {
          state.anyPressed = true;
          if (jumpKey) jumpPressedSinceUpdate = true;
        }
        down.add(e.code);
      } else {
        if (jumpKey && jumpPressedSinceUpdate && down.has(e.code)) jumpTapPending = true;
        down.delete(e.code);
      }
    }
    if (isDown && hooks.key) hooks.key(e);
  }

  const keydown = (e) => onKey(e, true);
  const keyup = (e) => onKey(e, false);
  const blur = () => clear();

  target.addEventListener('keydown', keydown);
  target.addEventListener('keyup', keyup);
  window.addEventListener('blur', blur);
  let hasGamepads = false;
  window.addEventListener('gamepadconnected', () => hasGamepads = true);
  window.addEventListener('gamepaddisconnected', () => {
    hasGamepads = (navigator.getGamepads ? navigator.getGamepads() : []).filter(g => g).length > 0;
  });

  function update(dt) {
    let gpTurn = 0, gpPedal = false, gpBrake = false, gpJump = false;
    if (hasGamepads) {
      const gamepads = navigator.getGamepads ? navigator.getGamepads() : [];
      for (let i = 0; i < gamepads.length; i++) {
        const gp = gamepads[i];
        if (!gp) continue;
        const raw = gp.axes[0] || 0;
        const mag = Math.abs(raw);
        if (mag > GP_DEADZONE) {
          const scaled = Math.sign(raw)
            * Math.min(1, (mag - GP_DEADZONE) / (1 - GP_DEADZONE));
          if (Math.abs(scaled) > Math.abs(gpTurn)) gpTurn = scaled;
        }
        const dpad = (gp.buttons[15]?.pressed ? 1 : 0) - (gp.buttons[14]?.pressed ? 1 : 0);
        if (Math.abs(dpad) > Math.abs(gpTurn)) gpTurn = dpad;
        gpPedal = gpPedal || !!gp.buttons[7]?.pressed || !!gp.buttons[12]?.pressed;
        gpBrake = gpBrake || !!gp.buttons[6]?.pressed || !!gp.buttons[13]?.pressed;
        gpJump = gpJump || !!gp.buttons[0]?.pressed;
      }

      // A cleared pad is ignored until every control passes through neutral.
      if (gamepadSuppressed) {
        if (gpTurn === 0 && !gpPedal && !gpBrake && !gpJump) {
          gamepadSuppressed = false;
        } else {
          gpTurn = 0;
          gpPedal = gpBrake = gpJump = false;
        }
      }

      if (gpJump && !gpJumpHeld) {
        state.anyPressed = true;
        gpJumpStepSeen = false;
      }
      if (!gpJump && gpJumpHeld && !gpJumpStepSeen) jumpTapPending = true;
      gpJumpHeld = gpJump;
    }

    const keyTurn = (held('right') ? 1 : 0) - (held('left') ? 1 : 0);
    const want = Math.abs(gpTurn) > Math.abs(keyTurn) ? gpTurn : keyTurn;
    const rate = want === 0 ? RELEASE : RAMP;
    state.turn += (want - state.turn) * (1 - Math.exp(-rate * dt));
    if (Math.abs(state.turn) < 0.004) state.turn = 0;

    state.pedal = held('pedal') || gpPedal;
    state.brake = held('brake') || gpBrake;
    if (jumpPulse === PULSE_PRESS) {
      if (jumpPulseSeen) {
        jumpPulse = PULSE_RELEASE;
        jumpPulseSeen = false;
        state.jump = false;
      } else {
        state.jump = true;
      }
    } else if (jumpPulse === PULSE_RELEASE) {
      if (jumpPulseSeen) {
        jumpPulse = PULSE_NONE;
        jumpPulseSeen = false;
        state.jump = held('jump') || gpJump;
      } else {
        state.jump = false;
      }
    } else if (jumpTapPending) {
      state.jump = true;
      jumpTapPending = false;
      jumpPulse = PULSE_PRESS;
      jumpPulseSeen = false;
    } else {
      state.jump = held('jump') || gpJump;
    }
    jumpPressedSinceUpdate = false;
  }

  /* Called once per physics step by whoever owns the fixed-step loop. */
  function stepped() {
    if (jumpPulse !== PULSE_NONE) jumpPulseSeen = true;
    if (gpJumpHeld && state.jump) gpJumpStepSeen = true;
  }

  function bindTouch(root) {
    state.touch = true;
    root.querySelectorAll('[data-key]').forEach((el) => {
      const name = el.dataset.key;
      let keyboardPulse = 0;
      const set = (v, e) => {
        e.preventDefault();
        touch[name] = v;
        if (v) state.anyPressed = true;
        el.classList.toggle('on', v);
      };
      el.addEventListener('pointerdown', (e) => {
        el.setPointerCapture?.(e.pointerId);
        set(true, e);
      });
      el.addEventListener('pointerup', (e) => {
        if (el.hasPointerCapture?.(e.pointerId)) el.releasePointerCapture(e.pointerId);
        set(false, e);
      });
      el.addEventListener('pointercancel', (e) => set(false, e));
      el.addEventListener('lostpointercapture', (e) => set(false, e));
      el.addEventListener('click', (e) => {
        if (e.detail !== 0) return;
        set(true, e);
        window.clearTimeout(keyboardPulse);
        keyboardPulse = window.setTimeout(() => {
          touch[name] = false;
          el.classList.remove('on');
        }, 160);
      });
    });
  }

  function dispose() {
    target.removeEventListener('keydown', keydown);
    target.removeEventListener('keyup', keyup);
    window.removeEventListener('blur', blur);
  }

  /* Pause reset: drop what the game inferred, keep what the hands are doing.
     See alpen's input.js for why emptying `down` here would eat held keys. */
  function calm() {
    state.turn = 0;
    state.jump = false;
    jumpPressedSinceUpdate = false;
    jumpTapPending = false;
    jumpPulse = PULSE_NONE;
    jumpPulseSeen = false;
  }

  /* Hard reset, for when the key states can no longer be trusted. */
  function clear() {
    down.clear();
    for (const k of Object.keys(touch)) touch[k] = false;
    gamepadSuppressed = true;
    gpJumpHeld = false;
    gpJumpStepSeen = false;
    calm();
  }

  return { state, update, stepped, bindTouch, dispose, clear, calm };
}

