/* Procedural summer audio. Zero audio files, like Alpen: everything is an
   oscillator or two seconds of looped noise filtered per job.

   Continuous voices, gains driven straight from the physics:
     rush     wind body — the only voice that survives a jump
     whistle  high wind past ~half speed
     roll     tyres over ground, filtered darker on dirt, brighter on gravel
     scrub    braking / drifting wash
     chain    drivetrain buzz while pedalling
     birds    distant songbirds, fade with speed and altitude of the forest

   One-shots: hop, land, crash, brush, click. */

const MASTER = 0.55;

export function createAudio() {
  let ctx = null;
  let master = null;
  let muted = false;
  let parked = true;
  const voices = {};
  let birdTimer = 0;
  let brown = null;
  let white = null;

  function noiseBuffer(kind) {
    const len = Math.floor(ctx.sampleRate * 2);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const n = Math.random() * 2 - 1;
      if (kind === 'brown') {
        last = (last + 0.024 * n) / 1.024;
        data[i] = last * 6;
      } else {
        data[i] = n;
      }
    }
    return buf;
  }

  function voice(buffer, type, freq, q) {
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    src.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    filter.Q.value = q;
    const gain = ctx.createGain();
    gain.gain.value = 0;
    src.connect(filter).connect(gain).connect(master);
    src.start();
    return { src, filter, gain };
  }

  function build() {
    master = ctx.createGain();
    master.gain.value = muted ? 0 : MASTER;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -10;
    comp.knee.value = 24;
    comp.ratio.value = 12;
    comp.attack.value = 0.003;
    comp.release.value = 0.25;
    master.connect(comp).connect(ctx.destination);

    brown = noiseBuffer('brown');
    white = noiseBuffer('white');

    voices.rush = voice(brown, 'lowpass', 700, 0.7);
    voices.whistle = voice(white, 'bandpass', 1100, 2.6);
    voices.roll = voice(brown, 'lowpass', 220, 1.0);
    voices.scrub = voice(brown, 'bandpass', 900, 0.8);
    voices.chain = voice(white, 'bandpass', 3400, 5.5);
  }

  /* Runs on every resume, not just the first — browsers suspend the context
     in a background tab. */
  function start() {
    parked = false;
    if (!ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      ctx = new AC();
      build();
    }
    if (ctx.state === 'suspended') ctx.resume().catch(() => {});
  }

  function quiet() {
    parked = true;
    for (const v of Object.values(voices)) {
      if (v.gain) v.gain.gain.setTargetAtTime(0, ctx ? ctx.currentTime : 0, 0.08);
    }
  }

  function setGain(v, value) {
    if (!v) return;
    v.gain.gain.setTargetAtTime(value, ctx.currentTime, 0.06);
  }

  /* speed m/s, slide 0..1, grounded, pedal 0..1, surf {grass,dirt,gravel,rock} */
  function ambience(speed, slide, grounded, pedaling, surf, dt) {
    if (!ctx || parked) return;
    const sp = Math.min(1, speed / 24);
    setGain(voices.rush, 0.05 + sp * 0.30);
    setGain(voices.whistle, Math.max(0, sp - 0.5) * 0.16);

    const rough = surf ? (surf.gravel * 1.0 + surf.rock * 0.9 + surf.dirt * 0.55 + surf.grass * 0.35) : 0.5;
    setGain(voices.roll, grounded ? sp * 0.30 * (0.4 + 0.6 * rough) : 0);
    if (grounded && voices.roll) {
      voices.roll.filter.frequency.setTargetAtTime(160 + rough * 340 + sp * 240, ctx.currentTime, 0.1);
    }
    setGain(voices.scrub, grounded ? Math.min(1, slide) * 0.30 : 0);
    setGain(voices.chain, grounded && pedaling ? 0.020 + sp * 0.030 : 0);

    // Birdsong: sparse chirps, thinning as speed rises.
    birdTimer -= dt;
    if (birdTimer <= 0) {
      birdTimer = 1.2 + Math.random() * 3.5;
      if (!muted && Math.random() > sp * 0.9) chirp();
    }
  }

  function tone(freq, endFreq, dur, gain, type = 'sine', delay = 0) {
    if (!ctx || muted) return;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (endFreq && endFreq !== freq) osc.frequency.exponentialRampToValueAtTime(Math.max(1, endFreq), t0 + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g).connect(master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.05);
  }

  function burst(dur, freq, gain, filterType = 'bandpass', sweepTo = 0, delay = 0, buffer = null) {
    if (!ctx || muted) return;
    const t0 = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = buffer || white;
    src.playbackRate.value = 0.85 + Math.random() * 0.3;
    src.loop = true;
    src.loopStart = Math.random();
    const filter = ctx.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.setValueAtTime(freq, t0);
    if (sweepTo) filter.frequency.exponentialRampToValueAtTime(sweepTo, t0 + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.015);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter).connect(g).connect(master);
    src.start(t0);
    src.stop(t0 + dur + 0.05);
  }

  function chirp() {
    if (!ctx || parked) return;
    const base = 2400 + Math.random() * 2200;
    const n = 2 + Math.floor(Math.random() * 3);
    for (let i = 0; i < n; i++) {
      tone(base * (0.9 + Math.random() * 0.25), base * (1.1 + Math.random() * 0.4),
        0.05 + Math.random() * 0.05, 0.012 + Math.random() * 0.01, 'sine', i * (0.07 + Math.random() * 0.05));
    }
  }

  const api = {
    start,
    quiet,
    ambience,
    hop() { burst(0.12, 900, 0.10, 'bandpass', 1600); },
    land(impact) {
      const s = Math.min(1, impact / 14);
      burst(0.14 + s * 0.12, 300, 0.10 + s * 0.22, 'lowpass', 120, 0, brown);
      if (s > 0.4) burst(0.2, 1200, s * 0.08, 'bandpass', 700, 0.02);
    },
    crash() {
      burst(0.5, 500, 0.30, 'lowpass', 90, 0, brown);
      burst(0.35, 1800, 0.14, 'bandpass', 500, 0.05);
    },
    brush() { burst(0.18, 2400, 0.05, 'bandpass', 1400); },
    click() { tone(1900, 1400, 0.05, 0.05, 'square'); },
    chime() { tone(880, 1320, 0.30, 0.05); tone(1320, 1760, 0.4, 0.035, 'sine', 0.1); },
    toggleMute() {
      muted = !muted;
      if (master) master.gain.setTargetAtTime(muted ? 0 : MASTER, ctx.currentTime, 0.05);
      return muted;
    },
    get muted() { return muted; },
  };
  return api;
}

