    if (!ctx || parked) return;
    const sp = Math.min(1, speed / 24);
    setGain(voices.rush, 0.05 + sp * 0.30);
    setGain(voices.whistle, Math.max(0, sp - 0.5) * 0.16);

    const rough = surf ? (surf.gravel * 1.0 + surf.rock * 0.9 + surf.dirt * 0.55 + surf.grass * 0.35) : 0.5;
    setGain(voices.roll, grounded ? sp * 0.30 * (0.4 + 0.6 * rough) : 0);
    if (grounded && voices.roll) {
      voices.roll.filter.frequency.setTargetAtTime(160 + rough * 340 + sp * 240, ctx.currentTime, 0.1);
    }
    setGain(voices.scrub, grounded ? Math.min(1, slide) * 0.30 : 0);
    setGain(voices.chain, grounded && pedaling ? 0.020 + sp * 0.030 : 0);

    // Birdsong: sparse chirps, thinning as speed rises.
    birdTimer -= dt;
    if (birdTimer <= 0) {
      birdTimer = 1.2 + Math.random() * 3.5;
      if (!muted && Math.random() > sp * 0.9) chirp();
    }
  }

  function tone(freq, endFreq, dur, gain, type = 'sine', delay = 0) {
    if (!ctx || muted) return;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (endFreq && endFreq !== freq) osc.frequency.exponentialRampToValueAtTime(Math.max(1, endFreq), t0 + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g).connect(master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.05);
  }

  function burst(dur, freq, gain, filterType = 'bandpass', sweepTo = 0, delay = 0, buffer = null) {
    if (!ctx || muted) return;
    const t0 = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = buffer || white;
    src.playbackRate.value = 0.85 + Math.random() * 0.3;
    src.loop = true;
    src.loopStart = Math.random();
    const filter = ctx.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.setValueAtTime(freq, t0);
    if (sweepTo) filter.frequency.exponentialRampToValueAtTime(sweepTo, t0 + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.015);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter).connect(g).connect(master);
    src.start(t0);
    src.stop(t0 + dur + 0.05);
  }

  function chirp() {
    if (!ctx || parked) return;
    const base = 2400 + Math.random() * 2200;
    const n = 2 + Math.floor(Math.random() * 3);
    for (let i = 0; i < n; i++) {
      tone(base * (0.9 + Math.random() * 0.25), base * (1.1 + Math.random() * 0.4),
        0.05 + Math.random() * 0.05, 0.012 + Math.random() * 0.01, 'sine', i * (0.07 + Math.random() * 0.05));
    }
  }

  const api = {
    start,
    quiet,
    ambience,
    hop() { burst(0.12, 900, 0.10, 'bandpass', 1600); },
    land(impact) {
      const s = Math.min(1, impact / 14);
      burst(0.14 + s * 0.12, 300, 0.10 + s * 0.22, 'lowpass', 120, 0, brown);
      if (s > 0.4) burst(0.2, 1200, s * 0.08, 'bandpass', 700, 0.02);
    },
    crash() {
      burst(0.5, 500, 0.30, 'lowpass', 90, 0, brown);
      burst(0.35, 1800, 0.14, 'bandpass', 500, 0.05);
    },
    brush() { burst(0.18, 2400, 0.05, 'bandpass', 1400); },
    click() { tone(1900, 1400, 0.05, 0.05, 'square'); },
    chime() { tone(880, 1320, 0.30, 0.05); tone(1320, 1760, 0.4, 0.035, 'sine', 0.1); },
    toggleMute() {
      muted = !muted;
      if (master) master.gain.setTargetAtTime(muted ? 0 : MASTER, ctx.currentTime, 0.05);
      return muted;
    },
    get muted() { return muted; },
  };
  return api;
}

