960	      let bump = snoise2(x * 0.083, z * 0.083, 57) * zones.rockBump[0] * coarseDetail;
961	      if (fineDetail > 0.001) {
962	        bump += snoise2(x * 0.21, z * 0.21, 91) * zones.rockBump[1] * fineDetail;
963	      }
964	      h += bump * rockZone;
965	    }
966	  }
967	  const over = past - ctx.bandW;
968	  if (over > 0) {
969	    /* The launchable bank remains a smooth quarterpipe across its width, but
970	       its shoulder now follows the same slow left/right geology as the wall
971	       behind it. That creates broad folds down the valley without putting a
972	       metre-scale bump under a board or mirroring both mountain sides. */
973	    const bankDetail = x < branchCentre
974	      ? ctx.wallDetailLeft : ctx.wallDetailRight;
975	    const bankHeight = ctx.lipH * (0.82 + 0.30 * bankDetail);
976	    h += bankHeight * smooth01(Math.min(1, over / ctx.lipW));
977	    const w = over - ctx.lipW;
978	    if (w > 0) {
979	      /* The walls are mountain flanks now, not one extrusion copied to both
980	         sides. Two low-frequency, side-specific fields are sampled only once
981	         the rideable lip is behind us. The first varies the breadth of the
982	         whole flank; the other raises two long geological shoulders. Every
983	         added term is monotonic across the wall, and each joins with a flat
984	         derivative, so the original containment guarantee and the smooth
985	         collision normal both survive. Because this is real height rather
986	         than shader displacement, trees, tracks and the precomputed horizon
987	         cache agree with the structure automatically. */
