989	      const left = x < branchCentre;
990	      const broad = left ? ctx.wallBroadLeft : ctx.wallBroadRight;
991	      const detail = left ? ctx.wallDetailLeft : ctx.wallDetailRight;
992	      const localScale = wall.scale * (1 - S.scaleVary + 2 * S.scaleVary * broad);
993	      const u = w / localScale;
994	      /* Ease the permanent creep in with zero value and zero derivative. The
995	         lip and exponential wall both arrive flat, so introducing a 17-degree
996	         crease precisely at their join defeated the otherwise smooth profile. */
997	      const creepShape = w - wall.creepEase * (1 - Math.exp(-w / wall.creepEase));
998	      const eu = Math.exp(-u * u);
999	      h += wall.height * (1 - eu) + wall.creep * creepShape;
1000	
1001	      /* Alpine mountain flank geology: jagged ribs, rocky spines, stepped terraces,
1002	         and sculpted couloirs that give the side mountains dramatic 3D relief. */
1003	      const flankArrival = smoothstep(4.0, 26.0, w);
1004	      const ridgeNoise = snoise2(w * 0.038, z * 0.024, left ? 101 : 203);
1005	      const spineDetail = snoise2(w * 0.082, z * 0.054, left ? 307 : 409);
1006	      const jaggedTerrace = Math.abs(snoise2(w * 0.14, z * 0.11, left ? 521 : 619));
1007	      h += (Math.abs(ridgeNoise) * 16.0 + spineDetail * 6.5 + jaggedTerrace * 3.8) * flankArrival;
1008	
1009	      /* THE FLUTING, and it is the only term on this whole profile that
1010	         varies across the flank rather than along it.
1011	
1012	         Everything else out here — the breadth, the two shoulders, the
1013	         buttress — is a function of z, which is exactly why the walls still
1014	         read as two poured ramps from a rider looking down the hill: a term
1015	         that only changes over hundreds of metres of descent does not change
1016	         at all in the frame. What covers a real flank above a piste runs the
1017	         other way, straight down the fall line, cut by every sluff and point
1018	         release that has come off it since November.
1019	
1020	         `steep` is the flank's own outward gradient normalised to its peak,
1021	         so the channels are exactly as deep as the wall is steep: nothing at
1022	         the lip, nothing out on the plateau, deepest across the face in
1023	         between. That is both what a slide actually does and what keeps the
1024	         containment guarantee intact — the ratio between a channel's steepest
1025	         wall and the mountain's is a constant chosen in the config rather
1026	         than an amplitude that has to be re-checked whenever the flank lies
1027	         back. `wall.scale / localScale` holds the same ratio against the
1028	         breadth variation: a broader flank is a shallower one, and its
1029	         channels shallow with it.
1030	
1031	         The phase wanders on one slow noise per side, so the channels lean
1032	         and braid down the hill instead of standing as a comb, and the two
1033	         sides of the valley never mirror each other. */
1034	      if (flankDetail > 0.001) {
1035	        const steep = (2 * u * eu) / WALL_STEEP_PEAK;
1036	        if (steep > 0.004) {
1037	          const R = wall.runnels;
1038	          const drift = R.meander * snoise2(
1039	            z * R.meanderFreq, left ? -5.7 : 5.7, R.seed,
1040	          );
1041	          /* SQUARED, and that is the whole of the containment argument near
1042	             the lip rather than a shaping choice.
1043	
1044	             The ratio below bounds the *carrier's* slope against the wall's,
1045	             and it is a complete argument only for a term whose amplitude is
1046	             constant. It is not: the amplitude has to arrive from zero
1047	             somewhere, and an arrival ramp contributes its own slope of about
1048	             depth over its length — a constant — while the wall's own
1049	             gradient near the lip is going to zero linearly. So there is
1050	             always a band just past the lip where a linear arrival out-climbs
1051	             the mountain, and it was measurable: an ordinary stretch of flank
1052	             seven metres out went from +0.11 to −0.02, which is a pocket in
1053	             ground that is supposed to be monotonically uphill everywhere.
1054	
1055	             `steep` is already linear in w near the lip, so squaring it makes
1056	             the amplitude quadratic and its derivative linear — the same
1057	             order as the wall's, with a constant ratio between them, which is
1058	             the property the rest of this block is built on. It costs nothing
1059	             anybody will miss: the channels simply concentrate on the steepest
1060	             third of the face, which is where a slide actually cuts them. */
1061	          const amp = flankDetail * steep * steep * (wall.scale / localScale);
1062	          const lambda = R.wave * (1 - R.waveVary + 2 * R.waveVary * broad);
1063	          // Squared, so the channel floors are narrow and the ribs between
1064	          // them broad — which is the section a slide leaves, and not the
1065	          // symmetrical corrugation a bare cosine draws.
1066	          const t = 0.5 - 0.5 * Math.cos((w + drift) * (TAU / lambda));
1067	          h -= R.depth * amp * t * t;
1068	          h -= R.fineDepth * amp
1069	            * (0.5 - 0.5 * Math.cos((w + drift * 0.4) * (TAU / R.fineWave)));
1070	        }
1071	      }
1072	
1073	      /* THE BULK — gullies and buttresses at the scale of the face itself,
1074	         plus a broken surface over them, both proportional to how steep the
1075	         flank is here. The reasoning is in `wall.bulk`; what matters at the
1076	         call site is that it shares the runnels' `steep²` amplitude for the
1077	         same containment reason, and that both terms are pure cuts: the
1078	         noise is mapped into 0…1 and subtracted, so nothing here can build a
1079	         bump with a downhill face on it.
1080	
1081	         It has its own detail mask because it survives a far coarser mesh
1082	         than the fluting does — which is the point of it. The far wall is
1083	         several hundred metres of screen and the fluting has faded out of it
1084	         long before the eye stops asking what shape the mountain is. */
1085	      if (bulkDetail > 0.001) {
1086	        const steepB = (2 * u * eu) / WALL_STEEP_PEAK;
1087	        if (steepB > 0.004) {
1088	          const B = wall.bulk;
1089	          const ampB = bulkDetail * steepB * steepB * (wall.scale / localScale);
1090	          h -= B.depth * ampB * (0.5 - 0.5 * snoise2(
1091	            w / B.wave, z / B.waveZ, left ? B.seed : B.seed + 41,
1092	          ));
1093	          h -= B.grain * ampB * (0.5 - 0.5 * snoise2(
1094	            w / B.grainWave, z / B.grainWave, left ? B.seed + 7 : B.seed + 53,
1095	          ));
1096	        }
1097	      }
1098	
1099	      const lowerStart = S.lowerStart[0]
1100	        + (S.lowerStart[1] - S.lowerStart[0]) * broad;
1101	      const lowerHeight = S.lowerHeight[0]
1102	        + (S.lowerHeight[1] - S.lowerHeight[0]) * detail;
1103	      const upperStart = S.upperStart[0]
1104	        + (S.upperStart[1] - S.upperStart[0]) * detail;
1105	      const upperHeight = S.upperHeight[0]
1106	        + (S.upperHeight[1] - S.upperHeight[0]) * broad;
1107	      h += lowerHeight * smoothstep(lowerStart, lowerStart + S.lowerWidth, w);
1108	      h += upperHeight * smoothstep(upperStart, upperStart + S.upperWidth, w);
1109	      /* Sharpen the high half of the already precomputed detail field into a
1110	         buttress. The ramp is monotonic across the flank, preserving the
1111	         containment guarantee, while variation down the run gives the side
1112	         mountain real ridges and gullies instead of one triangular plane. */
1113	      const rib = smoothstep(0.38, 0.78, detail);
1114	      const ribStart = S.ribStart[0]
1115	        + (S.ribStart[1] - S.ribStart[0]) * (1 - broad);
1116	      h += S.ribHeight * rib
1117	        * smoothstep(ribStart, ribStart + S.ribWidth, w);
1118	    }
1119	  }
1120	
1121	  /* Knolls and cliffs live outside the corridor entirely — a rideable run
1122	     with a hidden three-metre ledge on it is an ambush, not terrain. They
1123	     fade in with the powder band and are at full strength by the talus. */
1124	  const beyondF = 1 - corridorF;
1125	  if (beyondF > 0.001) {
1126	    for (let i = 0; i < ctx.nKnolls; i++) {
1127	      const dx = (x - ctx.kx[i]) / ctx.krx[i];
1128	      if (dx <= -1 || dx >= 1) continue;
1129	      const dz = ctx.kdz[i];
1130	      const r2 = dx * dx + dz * dz;
1131	      if (r2 >= 1) continue;
1132	      const f = 1 - r2;
1133	      h += ctx.kh[i] * f * f * beyondF;
1134	    }
1135	
1136	    for (let i = 0; i < ctx.nCliffs; i++) {
1137	      const ax = Math.abs(x - ctx.cliffX[i]);
1138	      if (ax >= cliffs.halfWidth + cliffs.shoulder) continue;
1139	      h -= ctx.cliffA[i]
1140	        * (1 - smoothstep(cliffs.halfWidth, cliffs.halfWidth + cliffs.shoulder, ax))
1141	        * beyondF;
1142	    }
1143	  }
