1148	/* The pure form, for everyone who is asking about one point rather than a
1149	   row of them. It is the row path with a row of one. */
1150	const scratch = makeContext();
1151	
1152	export function heightAt(x, z) {
1153	  return heightIn(rowContext(z, scratch), x);
1154	}
1155	
1156	/* THE SNOW AS IT IS DRAWN, which is not the snow the physics stands on.
1157	
1158	   `heightAt` is exact at any coordinate. The mesh is only its linear
1159	   interpolation across a `TERRAIN.spacing` lattice, and a straight line
1160	   between two samples of a hollow stands *above* the hollow. Measured over
1161	   the groomed corridor that gap averages a millimetre and reaches eight
1162	   centimetres in the sharper compressions — nothing to a rider, and
1163	   everything to anything printed flat onto the snow, because the board's
1164	   trail spends a total of two centimetres on clearance. Six per cent of the
1165	   piste is enough to bury the mark's packed floor and about one per cent
1166	   buries the berms with it, and a buried mark does not vanish cleanly: the
1167	   depth test drops whichever fragments the drawn surface happens to be over
1168	   and keeps the rest, so bright snow tears through the trench in slivers that
1169	   change with every metre the camera moves. That is the flicker, and it is
1170	   worst in the air, where the frame lifts, looks down, and hands the whole
1171	   strip of fresh mark to the bottom of the screen while nothing is redrawing
1172	   it.
1173	
1174	   THE CELL IS CUT ONE PARTICULAR WAY and this answers with that triangle, not
1175	   with the higher of the two. Taking the maximum was the first version and it
1176	   is wrong by more than it sounds: on a saddle the unused split runs as much
1177	   as twelve centimetres above the one the renderer draws, and a clearance
1178	   built on it would hold the trench that far off the snow — trading a mark
1179	   that tears for a mark that hovers. `CELL_PARITY` carries the index buffer's
1180	   own alternation, which the anchor cannot disturb, so the right triangle is
1181	   one compare away.
1182	
1183	   Only meaningful within `TERRAIN.uniformNear` of the rider. That is exactly
1184	   where the mesh samples this function at these corners — the anchor snaps by
1185	   whole cells, so the near field lands on this world lattice every time — and
1186	   it is also the only place anything prints itself on the snow. */
1187	const cell = { seed: -1, gx: NaN, gz: NaN, h00: 0, h10: 0, h01: 0, h11: 0 };
1188	
1189	export function drawnHeightAt(x, z) {
1190	  const s = TERRAIN.spacing;
1191	  const gx = Math.floor(x / s) * s;
1192	  const gz = Math.floor(z / s) * s;
1193	  /* One cell, remembered. The caller is a cross-section of a board:
1194	     twenty-five lanes strung along a line shorter than three cells, walked in
1195	     order, so nearly every lane after the first lands on the cell its
1196	     predecessor already paid four height samples for. The seed is in the key
1197	     because `heightAt` is a function of it and a worker re-seeds this module
1198	     per message. */
1199	  const seed = getWorldSeed();
1200	  if (cell.gx !== gx || cell.gz !== gz || cell.seed !== seed) {
1201	    // Two rows, two samples each, and `rowContext` caches on z — so the pair
1202	    // that shares a row costs one context between them.
1203	    const back = rowContext(gz, scratch);
1204	    cell.h00 = heightIn(back, gx);
1205	    cell.h10 = heightIn(back, gx + s);
1206	    const front = rowContext(gz + s, scratch);
1207	    cell.h01 = heightIn(front, gx);
1208	    cell.h11 = heightIn(front, gx + s);
1209	    cell.gx = gx;
1210	    cell.gz = gz;
1211	    cell.seed = seed;
1212	  }
1213	  const { h00, h10, h01, h11 } = cell;
1214	  const fx = (x - gx) / s;
1215	  const fz = (z - gz) / s;
1216	  /* Parity one is the diagonal from the low-x/high-z corner to its opposite,
1217	     which in this frame is the split along `fx + fz = 1`; parity zero is the
1218	     other one. See `CELL_PARITY`. */
1219	  if ((CELL_PARITY + Math.round(gx / s) + Math.round(gz / s)) & 1) {
1220	    return fx + fz <= 1
