1222	      : h11 + (h01 - h11) * (1 - fx) + (h10 - h11) * (1 - fz);
1223	  }
1224	  return fx >= fz
1225	    ? h00 + (h10 - h00) * fx + (h11 - h10) * fz
1226	    : h00 + (h11 - h01) * fx + (h01 - h00) * fz;
1227	}
1228	
1229	/* Surface normal by central difference. `fn` is passed in so the rider can
1230	   ask about the hill *plus* whatever kickers are sitting on it, while the
1231	   mesh asks about the bare hill. */
1232	const EPS = 0.35;
1233	
1234	export function normalFrom(fn, x, z, out) {
1235	  const dx = (fn(x + EPS, z) - fn(x - EPS, z)) / (2 * EPS);
1236	  const dz = (fn(x, z + EPS) - fn(x, z - EPS)) / (2 * EPS);
1237	  return out.set(-dx, 1, -dz).normalize();
1238	}
1239	
1240	/* The pitch of the bare hill down the fall line, which is what the rider's
1241	   climb scrub and the attract-mode steering both want to know. */
1242	export function gradeAt(z) {
1243	  let g = GRADE.base;
1244	  for (let i = 0; i < GRADE.waves.length; i++) {
1245	    const w = GRADE.waves[i];
1246	    g += w.amp * Math.sin(w.freq * z + w.phase);
1247	  }
1248	  return g;
1249	}
1250	
1251	/* ==========================================================================
1252	   The grid
1253	   ========================================================================== */
1254	
1255	/* Offsets that start at `step` and grow by `growth` each one, until they
1256	   have covered `reach`. Returns the list of positions, not the steps. */
1257	function graded(step, growth, reach, uniformReach = 0) {
1258	  const out = [0];
1259	  let d = 0;
1260	  let s = step;
1261	  while (d < reach) {
1262	    d += s;
1263	    out.push(d);
1264	    if (d >= uniformReach) s *= growth;
1265	  }
1266	  return out;
1267	}
1268	
1269	/* Columns mirrored about the rider, rows graded in both directions from them.
1270	   All four fans share the same uniform near field, which is what lets the
1271	   anchor snap: inside `uniformNear` every offset is a whole number of cells,
1272	   so those vertices land on the same world lattice every time the mesh
1273	   re-anchors and the facets under the board stay welded to the hill. Only past
1274	   it do the rings widen, and only there does anything morph.
1275	
1276	   It is built out here rather than inside `createTerrain` because it depends
1277	   on nothing but `TERRAIN`, and because `drawnHeightAt` above has to agree with
1278	   it exactly — down to which way each quad is cut. Two copies of this
1279	   arithmetic would be two chances to disagree about that. */
1280	const half = graded(TERRAIN.spacing, TERRAIN.sideGrowth, TERRAIN.side,
1281	  TERRAIN.uniformNear);
1282	const xs = [];
1283	for (let i = half.length - 1; i >= 1; i--) xs.push(-half[i]);
1284	for (let i = 0; i < half.length; i++) xs.push(half[i]);
1285	
1286	const bwd = graded(TERRAIN.spacing, TERRAIN.behindGrowth, TERRAIN.behind,
1287	  TERRAIN.uniformNear);
1288	const fwd = graded(TERRAIN.spacing, TERRAIN.aheadGrowth, TERRAIN.ahead,
1289	  TERRAIN.uniformNear);
1290	const zs = [];
1291	for (let i = bwd.length - 1; i >= 1; i--) zs.push(bwd[i]);
1292	for (let i = 0; i < fwd.length; i++) zs.push(-fwd[i]);
1293	
1294	const vertsX = xs.length;
1295	const vertsZ = zs.length;
1296	
1297	/* Which way a given world cell is cut, as a parity.
1298	
1299	   The index build below alternates the diagonal on `(row + column) & 1`, and
1300	   both indices are fixed offsets from the lattice: column zero sits at
1301	   `half.length - 1`, row zero at `bwd.length - 1`, x runs with the column and
1302	   z runs *against* the row. The anchor moves in whole multiples of eight
1303	   cells, so it drops out of the parity entirely and a world cell is cut the
1304	   same way for the whole run. This constant is everything about the mesh's
1305	   index buffer that a point query needs to know. */
1306	const CELL_PARITY = ((half.length - 1) + (bwd.length - 1) + 1) & 1;
1307	
1308	export function createTerrain(THREE, shading, maxAnisotropy = 1) {
1309	  const {
1310	    spacing, morphNear, morphFar, morphRate, morphSettle,
1311	  } = TERRAIN;
1312	
1313	  const cols = vertsX - 1;
1314	  const rows = vertsZ - 1;
1315	  const count = vertsX * vertsZ;
1316	
1317	  const positions = new Float32Array(count * 3);
1318	  const normals = new Float32Array(count * 3);
1319	  const colors = new Float32Array(count * 3);
1320	  /* Four broad material facts consumed by the surface shader.
1321	
1322	     X is how far the pack has gone from powder towards névé, which sets the
1323	     sheen's roughness. Y is the machine-groomed share of the snow. Z is the
1324	     exact snow-to-rock transition and W is the stone family, from blue slate
1325	     to warmer iron rock. Keeping the actual material decisions on the
1326	     generated lattice avoids trying to recover geology from luminance after
1327	     lighting and colour grading have already changed it. */
1328	  const surface = new Float32Array(count * 4);
1329	  /* The local lateral phase origin and its dx/dz tangent. This is separate
1330	     from surface state because it has to morph with world position at every
1331	     re-anchor; ice and groom coverage can still take the cheaper snap path. */
1332	  const groomFrame = new Float32Array(count * 2);
1333	  /* Triple buffering: live attributes, the target currently being eased
1334	     towards, and a spare target filled in the background. Reusing the current
1335	     target used to freeze every active skyline morph until the next build was
1336	     complete. Swapping two references at commit lets motion continue while
1337	     the spare is prepared and changes its destination without stopping. */
1338	  let targetPositions = new Float32Array(count * 3);
1339	  let targetNormals = new Float32Array(count * 3);
1340	  let targetColors = new Float32Array(count * 3);
1341	  let targetSurface = new Float32Array(count * 4);
1342	  let targetGroomFrame = new Float32Array(count * 2);
1343	  let buildPositions = new Float32Array(count * 3);
1344	  let buildNormals = new Float32Array(count * 3);
1345	  let buildColors = new Float32Array(count * 3);
1346	  let buildSurface = new Float32Array(count * 4);
1347	  let buildGroomFrame = new Float32Array(count * 2);
1348	  const morphMask = new Float32Array(count);
1349	  const coarseDetailMask = new Float32Array(count);

