/* The bike.

   A velocity vector on a surface, stepped at a fixed 120 Hz — the same
   architecture as Alpen's rider, with a bicycle's handling in place of a
   snowboard's. Steering turns the heading; grip decides how much of the
   velocity follows it; whatever grip cannot hold becomes drift. Pedalling
   is a floor that rises, braking is a smoothed lever, and a bunny-hop is a
   preload released — with Alpen's look-ahead sweep deciding when the ground
   itself has fallen away.

   The module imports nothing from three: a Vector3 class is injected, so
   the whole physics runs headless in node for testing (see the Alpen debug
   memory — the same harness works here). */

import { RIDER } from './config.js';
import { normalFrom } from './terrain.js';

const EVENTS = ['launch', 'land', 'fall', 'rise', 'impact', 'brush', 'strike'];

const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const approach = (v, target, rate, dt) => v + (target - v) * (1 - Math.exp(-rate * dt));
const wrapPi = (a) => {
  while (a > Math.PI) a -= Math.PI * 2;
  while (a < -Math.PI) a += Math.PI * 2;
  return a;
};

export class Rider {
  constructor(THREE, world) {
    this.V = THREE.Vector3;
    this.world = world;

    this.pos = new this.V();
    this.vel = new this.V();
    this.yaw = 0;
    this.state = 'ride';        // ride | air | fall | rise
    this.grounded = true;

    this.normal = new this.V(0, 1, 0);
    this.lean = 0;              // signed roll, + leans right
    this.slide = 0;             // m/s of lateral scrub, for audio/feel
    this.brake = 0;
    this.charge = 0;
    this.charging = false;
    this.airTime = 0;
    this.pitchVis = 0;          // visual pitch in the air
    this.compression = 0;
    this.compressionVel = 0;
    this.grace = 0;
    this.fallElapsed = 0;
    this.fallTimer = 0;
    this.surf = { grass: 0, dirt: 1, gravel: 0, rock: 0 };
    this.pedaling = false;
    this.pedalPhase = 0;

    this._n = new this.V(0, 1, 0);
    this._fwd = new this.V();
    this._right = new this.V();
    this._tmp = new this.V();
    this._tmp2 = new this.V();
    this._listeners = {};
    for (const e of EVENTS) this._listeners[e] = [];
  }

  on(name, fn) {
    if (this._listeners[name]) this._listeners[name].push(fn);
  }

  emit(name, a, b) {
    const list = this._listeners[name];
    if (!list) return;
    for (const fn of list) fn(a, b);
  }

  get speed() { return this.vel.length(); }

  reset(x, z, yaw = 0) {
    const y = this.world.height(x, z);
    this.pos.set(x, y, z);
    this.vel.set(0, 0, -2);
    this.yaw = yaw;
    this.state = 'ride';
    this.grounded = true;
    this.lean = 0;
    this.slide = 0;
    this.brake = 0;
    this.charge = 0;
    this.airTime = 0;
    this.pitchVis = 0;
    this.compression = 0;
    this.compressionVel = 0;
    this.grace = 1.0;
    normalFrom(this.world.height, x, z, this.normal);
  }

  step(dt, input) {
    if (this.grace > 0) this.grace -= dt;
    if (this.state === 'fall' || this.state === 'rise') this.fallStep(dt);
    else if (this.grounded) this.groundStep(dt, input);
    else this.airStep(dt, input);
    this.springStep(dt, input);
  }

  /* ======================= on the ground ======================= */

  groundStep(dt, input) {
    const { world } = this;
    const R = RIDER;
    const n = this._n;
    normalFrom(world.height, this.pos.x, this.pos.z, n);
    this.normal.lerp(n, 1 - Math.exp(-dt / 0.05)).normalize();

    // Brake lever, smoothed.
    this.brake = approach(this.brake, input.brake ? 1 : 0,
      input.brake ? R.brakeEngage : R.brakeRelease, dt);
    const braking = this.brake;

    // Absorb the into-slope component; big hits ring the fork.
    const into = this.vel.dot(n);
    if (into < 0) {
      this.vel.addScaledVector(n, -into);
      if (into < -2) {
        this.emit('impact', -into);
        this.compressionVel += Math.min(-into, 20) * 0.5;
      }
    }

    // Gravity, tangential part only.
    const gn = -R.gravity * n.y;
    this.vel.x -= (0 - n.x * gn) * dt * 0;   // (expanded below — kept explicit)
    // g = (0,-G,0); tangential = g - n*(g·n); g·n = -G*n.y
    const gDotN = -R.gravity * n.y;
    this.vel.x -= n.x * gDotN * dt * -1;
    this.vel.y += (-R.gravity - n.y * gDotN * -1) * dt;
    this.vel.z -= n.z * gDotN * dt * -1;

    // The bike frame on the slope.
    const fwd = this._fwd.set(Math.sin(this.yaw), 0, -Math.cos(this.yaw));
    const fDotN = fwd.dot(n);
    fwd.addScaledVector(n, -fDotN).normalize();
    const right = this._right.crossVectors(fwd, n).multiplyScalar(-1).normalize();

    let vFwd = this.vel.dot(fwd);
    let vLat = this.vel.dot(right);
    const speed = this.vel.length();

    // What the tyres have to offer here.
    const m = world.surfaceAt(this.pos.x, this.pos.z);
    this.surf = m;
    const surfGrip = m.dirt * 1.0 + m.grass * 0.78 + m.gravel * 0.85 + m.rock * 0.95;
    const gripNow = R.grip * surfGrip * (1 - braking * 0.45);

    // Steering: authority falls with speed; grip decides what follows.
    const spdT = clamp(speed / R.maxSpeed, 0, 1);
    const authority = R.steerRate * (1 - (1 - R.steerAtSpeed) * spdT);
    let yawRate = clamp(input.turn, -1, 1) * authority;
    this.yaw += yawRate * dt;

    // Self-centre on the slip angle — measured in the bike's own frame.
    if (speed > 2.5 && Math.abs(input.turn) < 0.05) {
      const slip = Math.atan2(vLat, Math.abs(vFwd) + 0.001);
      this.yaw += slip * (1 - Math.exp(-R.selfCentre * dt));
    }

    // The turn asks the ground to move the velocity; grip caps the answer.
    const bite = gripNow * dt;
    const held = clamp(vLat, -bite, bite);
    vLat -= held;
    this.slide = Math.abs(vLat);

    // Scrub: drifting bleeds lateral speed and a little forward speed.
    vLat *= Math.exp(-(2.4 + braking * 1.6) * dt);
    const fwdLoss = Math.abs(held) * 0.04 + this.slide * R.driftSlip * 0.09 * dt;

    // Rolling resistance and brakes.
    const mu = (m.grass * 0.028 + m.dirt * 0.012 + m.gravel * 0.02 + m.rock * 0.010)
      + R.brakeFriction * braking;
    const dec = mu * R.gravity * Math.max(0.25, n.y);
    const fSign = vFwd >= 0 ? 1 : -1;
    vFwd = fSign * Math.max(0, Math.abs(vFwd) - dec * dt - fwdLoss);

    // Rebuild the velocity in the frame.
    this.vel.copy(fwd).multiplyScalar(vFwd).addScaledVector(right, vLat);

    // Aerodynamic drag.
    const sp = this.vel.length();
    if (sp > 0.01) {
      const d = 1 / (1 + R.drag * sp * dt);
      this.vel.multiplyScalar(d);
    }

    // Pedalling: a floor that rises, never a shove that steers.
    this.pedaling = !!input.pedal && !input.brake;
    if (this.pedaling) {
      this.pedalPhase += dt * (1.4 + sp * 0.12);
      const floor = Math.min(Math.max(R.pedalCap, sp), sp + R.pedalAccel * dt);
      const now = this.vel.length();
      if (now < floor && now > 0.01) this.vel.multiplyScalar(floor / now);
      else if (now <= 0.01) this.vel.copy(fwd).multiplyScalar(R.pedalAccel * dt * 3);
    }

    // Terminal velocity, softly.
    const v2 = this.vel.length();
    if (v2 > R.maxSpeed) this.vel.multiplyScalar(1 - Math.min(1, (v2 - R.maxSpeed) / v2) * 0.5);

    // Preload and hop.
    if (input.jump) {
      this.charging = true;
      this.charge = Math.min(1, this.charge + dt / R.chargeTime);
    }

    // The launch sweep: is the ground about to leave us — or are we leaving it?
    const launch = this.launchSweep(dt);
    let pop = 0;
    if (this.charging && !input.jump) {
      pop = R.popMin + (R.popMax - R.popMin) * this.charge;
      if (launch.nearLip) pop *= R.lipBonus;
      this.charging = false;
      this.charge = 0;
      this.compressionVel = -10;
    }

    if (pop > 0 || launch.leaving) {
      this.takeOff(pop, n);
      // Position integrates in the air step from here.
      return;
    }

    // Integrate and clamp to the ground.
    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;
    this.pos.y = world.height(this.pos.x, this.pos.z);
    // The tangent's real vertical, so the launch sweep sees honest vy.
    const hAhead = world.height(this.pos.x + this.vel.x * 0.05, this.pos.z + this.vel.z * 0.05);
    this.vel.y = (hAhead - this.pos.y) / 0.05;

    // Lean: what the turn demands, shown at a credible angle.
    const latAccel = Math.abs(held) / dt;
    const leanTarget = -Math.sign(input.turn || -vLat) *
      Math.min(0.6, Math.atan2(Math.min(latAccel, gripNow), R.gravity))
      * Math.min(1, speed / 6) * Math.min(1, Math.abs(input.turn) + this.slide * 0.3);
    this.lean = approach(this.lean, leanTarget, 6.5, dt);
    this.pitchVis = approach(this.pitchVis, 0, 8, dt);
  }

  /* Alpen's launch predictor, shortened: sweep the ballistic arc against
     the ground over the next few metres. `leaving` — the ground drops away
     faster than gravity takes us; `nearLip` — a convex edge is right here,
     worth a better pop. */
  launchSweep(dt) {
    const R = RIDER;
    const { world } = this;
    const sp = Math.hypot(this.vel.x, this.vel.z);
    if (sp < 3) return { leaving: false, nearLip: false };
    const HZ = R.launchHorizon;
    const fx = this.vel.x / sp;
    const fz = this.vel.z / sp;
    // Trailing derivative — it cannot peek over the lip.
    const back = world.height(this.pos.x - fx * 0.35, this.pos.z - fz * 0.35);
    const vy = ((this.pos.y - back) / 0.35) * sp;
    const sweepLen = sp * HZ;
    const segs = clamp(Math.ceil(sweepLen / R.launchSampleSpacing), 3, R.launchSampleMax);
    let maxGap = 0;
    let blocked = false;
    for (let i = 1; i <= segs; i++) {
      const t = (i / segs) * HZ;
      const gx = this.pos.x + this.vel.x * t;
      const gz = this.pos.z + this.vel.z * t;
      const ground = world.height(gx, gz);
      const ballistic = this.pos.y + vy * t - 0.5 * R.gravity * t * t;
      const gap = ballistic - ground;
      if (gap > maxGap) maxGap = gap;
      if (gap < -0.02) { blocked = true; break; }
    }
    return {
      leaving: !blocked && maxGap > R.launchGap,
      nearLip: !blocked && maxGap > R.launchGap * 0.5,
    };
  }

  takeOff(pop, n) {
    this.state = 'air';
    this.grounded = false;
    this.airTime = 0;
    if (pop > 0) {
      const up = this._tmp.copy(n).add(this._tmp2.set(0, 1, 0)).normalize();
      this.vel.addScaledVector(up, pop);
      // Legs extending reinforce a player's hop.
      this.vel.y += Math.max(0, -this.compressionVel) * 0.4;
    }
    this.emit('launch', this.vel.y);
  }

  /* ======================= in the air ======================= */

  airStep(dt, input) {
    const R = RIDER;
    this.airTime += dt;
    const startVy = this.vel.y;
    this.vel.y -= R.gravity * dt;

    // A whisper of drift authority, perpendicular to travel.
    const sp = Math.hypot(this.vel.x, this.vel.z);
    if (sp > 0.5 && input.turn) {
      const px = -this.vel.z / sp;
      const pz = this.vel.x / sp;
      this.vel.x += px * input.turn * R.airSteer * dt;
      this.vel.z += pz * input.turn * R.airSteer * dt;
    }
    // The bars follow the travel line; a little yaw play from steering.
    this.yaw += input.turn * 1.6 * dt;
    this.pitchVis = approach(this.pitchVis,
      (input.pedal ? -0.28 : 0) + (input.brake ? 0.3 : 0) + 0.12, R.airPitch, dt);
    this.lean = approach(this.lean, input.turn * -0.3, 4, dt);

    this.pos.x += this.vel.x * dt;
    this.pos.y += (startVy + this.vel.y) * 0.5 * dt;
    this.pos.z += this.vel.z * dt;

    // Touchdown — only when genuinely descending onto the ground.
    if (this.airTime < 0.04) return;
    const ground = this.world.height(this.pos.x, this.pos.z);
    if (this.pos.y <= ground && this.vel.y <= 0.5) {
      this.pos.y = ground;
      this.land();
    }
  }

  land() {
    const R = RIDER;
    const n = this._n;
    normalFrom(this.world.height, this.pos.x, this.pos.z, n);
    this.normal.copy(n);
    const impact = Math.max(0, -this.vel.dot(n));

    // Land on the wheels: velocity keeps only its tangent.
    const vn = this.vel.dot(n);
    this.vel.addScaledVector(n, -vn);

    this.grounded = true;
    this.state = 'ride';
    this.compressionVel += Math.min(impact, 24) * 0.8;

    if (impact > R.hardImpact && this.grace <= 0) {
      this.fall('land', impact);
      return;
    }
    if (impact > R.softImpact) {
      const excess = impact - R.softImpact;
      this.vel.multiplyScalar(1 - Math.min(0.22, excess * 0.02));
    }
    // Straighten the bars onto the travel line — nobody lands a bike sideways.
    const sp = Math.hypot(this.vel.x, this.vel.z);
    if (sp > 1) {
      const travelYaw = Math.atan2(this.vel.x, -this.vel.z);
      const err = wrapPi(this.yaw - travelYaw);
      this.yaw = travelYaw + clamp(err, -0.3, 0.3);
    }
    this.emit('land', impact, this.airTime);
    this.airTime = 0;
  }

  /* ======================= crashing ======================= */

  fall(cause, into = 0) {
    if (this.state === 'fall') return;
    this.state = 'fall';
    this.grounded = true;
    this.fallElapsed = 0;
    this.charge = 0;
    this.charging = false;
    this.vel.multiplyScalar(0.5);
    this.vel.y = Math.min(4, Math.max(0, into) * 0.2);
    this.emit('fall', cause);
  }

  fallStep(dt) {
    const R = RIDER;
    if (this.state === 'rise') {
      this.fallTimer -= dt;
      if (this.fallTimer <= 0) {
        this.state = 'ride';
        this.grace = R.graceAfterRise;
        this.emit('rise');
      }
      return;
    }
    this.fallElapsed += dt;
    // Slither out along the ground, hard friction.
    const speed = this.vel.length();
    if (speed > 0.01) {
      const dec = 7.5 * dt;
      this.vel.multiplyScalar(Math.max(0, speed - dec) / speed);
    }
    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;
    this.pos.y = this.world.height(this.pos.x, this.pos.z);
    this.lean = approach(this.lean, 0.9, 3, dt);

    const stopped = this.vel.length() < R.fallRest;
    if ((stopped && this.fallElapsed > R.fallMin) || this.fallElapsed > R.fallMax) {
      // Back on: point down the fall line, walking pace.
      this.state = 'rise';
      this.fallTimer = R.riseTime;
      const sp = clamp(this.vel.length(), 2.5, 5);
      this.yaw = Math.atan2(this.vel.x, -this.vel.z) || 0;
      if (!Number.isFinite(this.yaw)) this.yaw = 0;
      this.vel.set(Math.sin(this.yaw), 0, -Math.cos(this.yaw)).multiplyScalar(sp);
      this.lean = 0;
    }
  }

  /* An obstacle in the line — called by the collision pass. */
  strike(nx, nz, closeness) {
    const R = RIDER;
    const push = this._tmp.set(nx, 0, nz);
    const into = Math.max(0, -(this.vel.dot(push)));
    const severity = clamp((into - R.brushSpeed) / (R.wipeoutSpeed - R.brushSpeed), 0, 1.6)
      * (0.45 + 0.55 * closeness);
    if (severity >= 1 && this.grace <= 0) {
      this.fall('hit', into);
      this.emit('strike', 'fall');
      return 'fall';
    }
    if (into < R.brushSpeed * 0.5) {
      this.vel.addScaledVector(push, Math.min(into, 1.5) + 0.6);
      this.compressionVel += 2.5;
      this.emit('brush');
      return 'brush';
    }
    this.vel.addScaledVector(push, Math.min(into, 2.5 + 7 * severity));
    this.vel.multiplyScalar(1 - 0.25 * severity);
    this.slide += 4 * severity;
    this.emit('strike', 'graze');
    return 'graze';
  }

  /* ======================= the fork ======================= */

  springStep(dt, input) {
    const R = RIDER;
    const w = R.springFreq * Math.PI * 2;
    let target;
    if (this.state === 'fall') {
      target = R.compressMax;
    } else if (!this.grounded) {
      target = -0.10 * Math.min(1, this.airTime * 3);
    } else {
      const lateralG = Math.min(1.4, this.slide * 0.2 + Math.abs(this.lean) * 1.2);
      target = Math.hypot(1, lateralG) * R.compressPerG * (R.gravity / 9.81);
      if (this.brake > 0.05) target = Math.max(target, 0.12 * this.brake);   // brake dive
      if (this.charging) target = R.compressMax * (0.35 + 0.65 * this.charge);
    }
    this.compressionVel += (target - this.compression) * w * w * dt;
    this.compressionVel *= Math.exp(-2 * R.springDamp * w * dt);
    this.compression += this.compressionVel * dt;
    this.compression = clamp(this.compression, -0.25, R.compressMax);
  }
}

