input.content:
/* First person. The camera IS the rider's head: no boom, no collision, no
   look-around — the head sits over the stem, settles onto the travel line a
   beat behind the bars, rolls with the lean, and takes every landing in the
   knees. All the drama Alpen's chase camera spends on its boom goes into
   FOV, bob and shake instead. */

import { RENDER, CAMERA, RIDER } from './config.js';

const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);

export function createHeadCamera(THREE, camera) {
  const look = new THREE.Vector3();
  const flat = new THREE.Vector3();
  const eye = new THREE.Vector3();
  let fov = RENDER.fov;
  let punch = 0;
  let shakeSeed = 0;
  let rollNow = 0;
  let headYaw = null;
  let bobPhase = 0;

  function update(rider, dt, world) {
    const speed = rider.speed;
    const ratio = clamp(speed / RIDER.maxSpeed, 0, 1);

    /* The head follows the travel line, lagging the bars: on a drift the
       bars point into the corner while the view still carries the slide. */
    let wantYaw = rider.yaw;
    const sp = Math.hypot(rider.vel.x, rider.vel.z);
    if (sp > 2) {
      const travelYaw = Math.atan2(rider.vel.x, -rider.vel.z);
      // Blend toward travel at speed; at a walking pace trust the bars.
      const trust = clamp((sp - 2) / 4, 0, 0.8);
      let d = travelYaw - wantYaw;
      while (d > Math.PI) d -= Math.PI * 2;
      while (d < -Math.PI) d += Math.PI * 2;
      wantYaw = wantYaw + d * trust;
    }
    if (headYaw === null) headYaw = wantYaw;
    let dy = wantYaw - headYaw;
    while (dy > Math.PI) dy -= Math.PI * 2;
    while (dy < -Math.PI) dy += Math.PI * 2;
    headYaw += dy * (1 - Math.exp(-CAMERA.headLag * dt));

    // The eye: over the bike, dropped by the fork's compression.
    eye.copy(rider.pos);
    eye.y += RIDER.eyeHeight - rider.compression * 0.5;

    // Pedalling bob and speed chatter.
    bobPhase = rider.pedalPhase;
    const rough = rider.surf
      ? (rider.surf.gravel * 1.0 + rider.surf.rock * 0.85 + rider.surf.dirt * 0.4 + rider.surf.grass * 0.55)
      : 0.5;
    const chatter = rider.grounded && rider.state === 'ride'
      ? ratio * ratio * CAMERA.shake * (0.4 + 0.6 * rough) : 0;
    shakeSeed += dt * 47;
    const amp = chatter * 0.045 + (rider.state === 'fall' ? 0.09 : 0);
    const sx = Math.sin(shakeSeed * 1.7) * Math.sin(shakeSeed * 0.53);
    const sy = Math.sin(shakeSeed * 2.3 + 1.3) * Math.sin(shakeSeed * 0.71);
    eye.x += sx * amp;
    eye.y += sy * amp + (rider.pedaling ? Math.sin(bobPhase * Math.PI * 2) * CAMERA.bobAmp : 0);

    camera.position.copy(eye);

    // Where the head is actually looking: down the line, onto the ground.
    flat.set(Math.sin(headYaw), 0, -Math.cos(headYaw));
    look.copy(eye).addScaledVector(flat, CAMERA.lookAhead * (0.7 + 0.5 * ratio));
    const groundAhead = world.height(look.x, look.z);
    // Between the horizon and the trail: mostly the trail.
    look.y = eye.y * 0.35 + (groundAhead + 1.2) * 0.65;
    if (rider.state === 'air') look.y += 0.8 - Math.min(2.2, rider.airTime * 1.8);
    camera.up.set(0, 1, 0);
    camera.lookAt(look);

    // Roll with the lean, plus crash chaos.
    const wantRoll = rider.lean * CAMERA.rollShare
      + (rider.state === 'fall' ? Math.sin(shakeSeed * 0.9) * 0.5 : 0)
      + sx * amp * 0.4;
    rollNow += (wantRoll - rollNow) * (1 - Math.exp(-6 * dt));
    camera.rotateZ(rollNow);

    // Pitch play in the air.
    if (rider.pitchVis) camera.rotateX(rider.pitchVis * 0.4);

    // FOV: speed opens it, landings punch it.
    const wantFov = RENDER.fov + (RENDER.fovAtSpeed - RENDER.fov) * ratio * ratio;
    fov += (wantFov - fov) * (1 - Math.exp(-3.5 * dt));
    punch *= Math.exp(-CAMERA.landPunchDecay * dt);
    const shown = Math.min(96, fov + punch);
    if (Math.abs(camera.fov - shown) > 0.01) {
      camera.fov = shown;
      camera.updateProjectionMatrix();
    }
  }

  function kick(impact) {
    punch = Math.min(CAMERA.landPunch * 1.4,
      punch + CAMERA.landPunch * clamp(impact / (RIDER.softImpact * 1.6), 0, 1));
  }

  function reset() {
    headYaw = null;
    punch = 0;
    rollNow = 0;
  }

  return { update, kick, reset };
}

