    // Grips.
    barParts.push({
      geo: cyl, color: glove,
      pos: [s * 0.335, 0.045, 0.038], rot: [0.12, s * -0.28, Math.PI / 2],
      scale: [0.021, 0.13, 0.021],
    });
    barParts.push({ geo: sph, color: dark, pos: [s * 0.40, 0.055, 0.052], scale: [0.022, 0.022, 0.022] });
    // Brake levers, reaching forward-down.
    barParts.push({
      geo: cyl, color: alu,
      pos: [s * 0.27, 0.015, -0.055], rot: [1.25, s * 0.35, 0],
      scale: [0.006, 0.11, 0.006],
    });
  }
  // Stem, sloping back toward the steerer.
  barParts.push({ geo: box, color: alu, pos: [0, -0.015, 0.045], rot: [0.5, 0, 0], scale: [0.036, 0.05, 0.10] });
  // Steerer + headset cap.
  barParts.push({ geo: cyl, color: paintHex, pos: [0, -0.09, 0.085], rot: [0.18, 0, 0], scale: [0.024, 0.12, 0.024] });

  const bars = new THREE.Mesh(compose(THREE, barParts), mat);

  /* ---------------- fork + wheel (steers and dips) ---------------- */
  const forkParts = [];
  // Crown.
  forkParts.push({ geo: box, color: paintHex, pos: [0, -0.16, 0.075], scale: [0.13, 0.045, 0.05] });
  for (const s of [-1, 1]) {
    // Stanchions and lowers, raked slightly forward.
    forkParts.push({
      geo: cyl, color: alu,
      pos: [s * 0.055, -0.32, 0.05], rot: [0.18, 0, 0], scale: [0.016, 0.30, 0.016],
    });
    forkParts.push({
      geo: cyl, color: paintHex,
      pos: [s * 0.058, -0.62, -0.01], rot: [0.18, 0, 0], scale: [0.020, 0.34, 0.020],
    });
  }
  const fork = new THREE.Mesh(compose(THREE, forkParts), mat);

  // The wheel proper — tire, rim, hub, spokes — spins on its own axis.
  const wheelParts = [];
  wheelParts.push({
    geo: new THREE.TorusGeometry(WHEEL_R, 0.032, 8, 22), color: 0x141416,
    rot: [0, Math.PI / 2, 0],
  });
  wheelParts.push({
    geo: new THREE.TorusGeometry(WHEEL_R - 0.035, 0.012, 6, 22), color: alu,
    rot: [0, Math.PI / 2, 0],
  });
  wheelParts.push({ geo: cyl, color: dark, pos: [0, 0, 0], rot: [0, 0, Math.PI / 2], scale: [0.03, 0.07, 0.03] });
  for (let i = 0; i < 9; i++) {
    const a = (i / 9) * Math.PI * 2;
    wheelParts.push({
      geo: cyl, color: 0xcfd4da,
      pos: [0, Math.cos(a) * WHEEL_R * 0.5, Math.sin(a) * WHEEL_R * 0.5],
      rot: [a + Math.PI / 2, 0, 0],
      scale: [0.0035, WHEEL_R - 0.04, 0.0035],
    });
  }
  const wheel = new THREE.Mesh(compose(THREE, wheelParts), mat);
  wheel.position.set(0, -0.78, -0.065);
  fork.add(wheel);

  /* ---------------- hands + forearms (with the bars) ---------------- */
  function handAssembly(s) {
    const parts = [];
    // Palm wrapped over the grip.
    parts.push({ geo: sph, color: glove, pos: [s * 0.335, 0.075, 0.045], scale: [0.045, 0.038, 0.055] });
    // Knuckle trim — the checkered-glove flash from the reference shots.
    parts.push({ geo: box, color: gloveTrim, pos: [s * 0.335, 0.098, 0.032], rot: [0.2, 0, 0], scale: [0.055, 0.012, 0.03] });
    // Fingers curling over the far side of the grip.
    for (let f = 0; f < 4; f++) {
      parts.push({
        geo: cyl, color: glove,
        pos: [s * (0.30 + f * 0.024), 0.052, -0.008], rot: [1.9, 0, 0],
        scale: [0.0095, 0.055, 0.0095],
      });
    }
    // Thumb under.
    parts.push({ geo: cyl, color: glove, pos: [s * 0.30, 0.035, 0.06], rot: [0.3, 0, s * 1.2], scale: [0.010, 0.05, 0.010] });
    // Wrist and forearm, reaching down-back out of frame.
    parts.push({ geo: cyl, color: glove, pos: [s * 0.35, 0.045, 0.115], rot: [1.15, 0, s * -0.12], scale: [0.035, 0.09, 0.035] });
    parts.push({
      geo: cone, color: 0x3a3f35,   // jersey sleeve
      pos: [s * 0.385, -0.01, 0.26], rot: [1.25, 0, s * -0.15],
      scale: [0.055, 0.24, 0.055],
    });
    return parts;
  }
  const hands = new THREE.Mesh(compose(THREE, [...handAssembly(-1), ...handAssembly(1)]), mat);

  /* ---------------- assembly ---------------- */
  const steering = new THREE.Group();   // rotates around the steering axis
  steering.add(bars);
  steering.add(hands);
  steering.add(fork);
  group.add(steering);

  // A hint of top tube dropping away under you.
  const frameHint = new THREE.Mesh(compose(THREE, [
    { geo: cyl, color: paintHex, pos: [0, -0.42, 0.42], rot: [1.35, 0, 0], scale: [0.024, 0.5, 0.024] },
  ]), mat);
  group.add(frameHint);

  // Hang it all off the camera, just below the eye.
  group.position.set(0, -0.44, -0.58);
  camera.add(group);

  let steerVis = 0;
  let bob = 0;

  function update(rider, input, dt) {
    // Bars answer the input a touch ahead of the physics — hands lead.
    const want = (input ? input.turn : 0) * 0.42;
    steerVis += (want - steerVis) * (1 - Math.exp(-10 * dt));
    steering.rotation.y = steerVis;

    // The whole cockpit leans a little further than the head does.
    group.rotation.z = rider.lean * 0.35;
    group.rotation.x = rider.pitchVis * 0.25;

    // Fork dip: crown-down assembly follows compression.
    fork.position.y = -rider.compression * 0.10;
    fork.position.z = -rider.compression * 0.03;

    // Pedal bob nudges the whole bike, not the head.
    bob = rider.pedaling ? Math.sin(rider.pedalPhase * Math.PI * 2) * 0.012 : bob * 0.9;
    group.position.y = -0.44 + bob - rider.compression * 0.06;

    // Wheel spin from ground speed.
    const sp = Math.hypot(rider.vel.x, rider.vel.z);
    wheel.rotation.x -= (sp / WHEEL_R) * dt;

    // Crashing throws the bars.
    group.visible = rider.state !== 'fall';
  }

  return { group, update };
}

