/* Everything standing on the hill: conifers, birches, bushes, boulders,
   grass tufts, wildflowers, fallen logs and trail markers.

   Alpen's scheme, whole: every prop is composed primitives baked into one
   geometry (geom.js), drawn as InstancedMesh pools, and placed per 40 m
   band purely from hashes of the band index — nothing is stored, bands
   behind are simply overwritten by bands ahead, and the same band always
   grows the same forest. Species and density follow the terrain's own zone
   weights, so the pine chapter is the dense dark one, the meadow keeps a
   scatter of bushes and a sea of flowers, and the ridge grows krummholz
   out of cracks. Nothing stands on the trail bed.

   Solids (trunks, boulders, logs) are published per rebuild for the
   collision pass. */

import { compose } from './geom.js';
import { stream, hash2, noise2 } from './noise.js';
import { PROPS, TERRAIN } from './config.js';
import { heightAt, guideAt, corridorHalfAt, zoneAt, normalFrom } from './terrain.js';

const { band: BAND, ahead: AHEAD, behind: BEHIND, verge: VERGE } = PROPS;
const BED = TERRAIN.trail.bed + TERRAIN.trail.shoulder;

/* ==========================================================================
   Growers
   ========================================================================== */

function growConifer(THREE, geos, rnd, kind) {
  // kind 0: spruce (narrow, dark), 1: pine (broader, warmer), 2: krummholz
  const parts = [];
  const height = kind === 2 ? 1.6 + rnd() * 1.4 : 5.5 + rnd() * 7.5;
  const trunkR = height * 0.022 + 0.05;
  const bark = kind === 1 ? 0x6b4f37 : 0x54402e;
  parts.push({
    geo: geos.cyl, color: bark,
    pos: [0, height * 0.28, 0], scale: [trunkR, height * 0.6, trunkR],
  });
  const tiers = kind === 2 ? 3 : 5 + Math.floor(rnd() * 3);
  const spread = kind === 1 ? 0.34 : 0.26;
  const g0 = kind === 1 ? [0.28, 0.42, 0.19] : [0.16, 0.33, 0.16];
  for (let t = 0; t < tiers; t++) {
    const f = t / tiers;
    const y = height * (0.22 + 0.78 * f);
    const r = height * spread * (1 - f * 0.78) * (0.9 + rnd() * 0.25);
    const tall = height * (0.30 - f * 0.10);
    const shade = 0.82 + rnd() * 0.4 - f * 0.1;
    const c = new THREE.Color(g0[0] * shade, g0[1] * shade, g0[2] * shade);
    parts.push({
      geo: geos.cone, color: c.getHex(),
      pos: [(rnd() - 0.5) * 0.2, y, (rnd() - 0.5) * 0.2],
      rot: [(rnd() - 0.5) * (kind === 2 ? 0.5 : 0.1), rnd() * Math.PI, 0],
      scale: [r, tall, r],
    });
  }
  return { geo: compose(THREE, parts), height, trunkR: trunkR * 1.6 };
}

function growBirch(THREE, geos, rnd) {
  const parts = [];
  const height = 5 + rnd() * 4.5;
  const trunkR = height * 0.016 + 0.04;
  parts.push({
    geo: geos.cyl, color: 0xdcd8ce,
    pos: [0, height * 0.35, 0], rot: [0, 0, (rnd() - 0.5) * 0.08],
    scale: [trunkR, height * 0.72, trunkR],
  });
  // Bark scores.
  for (let i = 0; i < 3; i++) {
    parts.push({
      geo: geos.box, color: 0x2e2c28,
      pos: [(rnd() - 0.5) * trunkR * 1.6, height * (0.15 + rnd() * 0.4), trunkR * 0.9],
      scale: [trunkR * 1.3, 0.05 + rnd() * 0.05, 0.02],
    });
  }
  const crowns = 3 + Math.floor(rnd() * 3);
  for (let i = 0; i < crowns; i++) {
    const s = 0.9 + rnd() * 0.8;
    const g = 0.75 + rnd() * 0.4;
    const c = new THREE.Color(0.42 * g, 0.55 * g, 0.24 * g);
    parts.push({
      geo: geos.sph, color: c.getHex(),
      pos: [(rnd() - 0.5) * height * 0.22, height * (0.62 + rnd() * 0.3), (rnd() - 0.5) * height * 0.22],
      scale: [height * 0.16 * s, height * 0.14 * s, height * 0.16 * s],
    });
  }
  return { geo: compose(THREE, parts), height, trunkR: trunkR * 1.6 };
}

function growBush(THREE, geos, rnd) {
  const parts = [];
  const size = 0.6 + rnd() * 0.9;
  const lobes = 2 + Math.floor(rnd() * 3);
  for (let i = 0; i < lobes; i++) {
    const g = 0.7 + rnd() * 0.5;
    const c = new THREE.Color(0.30 * g, 0.44 * g, 0.20 * g);
    parts.push({
      geo: geos.sph, color: c.getHex(),
      pos: [(rnd() - 0.5) * size, size * (0.3 + rnd() * 0.2), (rnd() - 0.5) * size],
      scale: [size * (0.6 + rnd() * 0.4), size * (0.45 + rnd() * 0.3), size * (0.6 + rnd() * 0.4)],
    });
  }
  return { geo: compose(THREE, parts), height: size, trunkR: size * 0.7 };
}

function growBoulder(THREE, geos, rnd) {
  const parts = [];
  const size = 1;
  const g = 0.8 + rnd() * 0.35;
  parts.push({
    geo: geos.rock, color: new THREE.Color(0.52 * g, 0.51 * g, 0.49 * g).getHex(),
    pos: [0, size * 0.32, 0],
    rot: [rnd() * 0.6, rnd() * Math.PI, rnd() * 0.6],
    scale: [size, size * (0.6 + rnd() * 0.5), size * (0.75 + rnd() * 0.4)],
  });
  if (rnd() < 0.7) {
    const g2 = g * 0.9;
    parts.push({
      geo: geos.rock, color: new THREE.Color(0.5 * g2, 0.5 * g2, 0.47 * g2).getHex(),
      pos: [size * (0.5 + rnd() * 0.3), size * 0.18, (rnd() - 0.5) * size * 0.5],
      rot: [rnd(), rnd() * Math.PI, rnd()],
      scale: [size * 0.45, size * 0.35, size * 0.4],
    });
  }
  return { geo: compose(THREE, parts), height: 1, trunkR: 0.9 };
}

function growLog(THREE, geos, rnd) {
  const len = 2.5 + rnd() * 2.5;
  const r = 0.14 + rnd() * 0.1;
  const parts = [{
    geo: geos.cyl, color: 0x5a4634,
    pos: [0, r * 0.9, 0], rot: [0, 0, Math.PI / 2],
    scale: [r, len, r],
  }, {
    geo: geos.cyl, color: 0x8a7a5c,   // cut face
    pos: [len * 0.5 + 0.01, r * 0.9, 0], rot: [0, 0, Math.PI / 2],
    scale: [r * 0.98, 0.03, r * 0.98],
  }];
  return { geo: compose(THREE, parts), height: r * 2, trunkR: len * 0.4 };
}

function growTuft(THREE, geos, rnd) {
  const parts = [];
  const blades = 5 + Math.floor(rnd() * 3);
  for (let i = 0; i < blades; i++) {
    const g = 0.8 + rnd() * 0.5;
    const c = new THREE.Color(0.38 * g, 0.52 * g, 0.20 * g);
    const h = 0.22 + rnd() * 0.28;
    parts.push({
      geo: geos.blade, color: c.getHex(),
      pos: [(rnd() - 0.5) * 0.24, h * 0.5, (rnd() - 0.5) * 0.24],
      rot: [(rnd() - 0.5) * 0.7, rnd() * Math.PI, (rnd() - 0.5) * 0.7],
      scale: [0.016, h, 0.016],
    });
  }
  return { geo: compose(THREE, parts) };
}

function growFlower(THREE, geos, rnd) {
  const h = 0.25 + rnd() * 0.2;
  const parts = [
    { geo: geos.cyl, color: 0x3f5a2a, pos: [0, h * 0.5, 0], scale: [0.008, h, 0.008] },
    { geo: geos.sph, color: 0xffffff, pos: [0, h, 0], scale: [0.045, 0.035, 0.045] },
  ];
  return { geo: compose(THREE, parts) };
}

function growMarker(THREE, geos) {
  const parts = [
    { geo: geos.cyl, color: 0x6b5844, pos: [0, 0.55, 0], scale: [0.045, 1.1, 0.045] },
    { geo: geos.box, color: 0xd8352a, pos: [0, 1.02, 0], scale: [0.11, 0.11, 0.06] },
    { geo: geos.box, color: 0xf5f0e6, pos: [0, 1.02, 0.005], scale: [0.11, 0.035, 0.062] },
  ];
  return { geo: compose(THREE, parts) };
}

/* ==========================================================================
   Pools
   ========================================================================== */

class Pool {
  constructor(THREE, geometry, material, capacity, { shadow = false } = {}) {
    this.THREE = THREE;
    this.mesh = new THREE.InstancedMesh(geometry, material, capacity);
    this.mesh.frustumCulled = false;
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.castShadow = shadow;
    this.mesh.receiveShadow = false;
    this.capacity = capacity;
    this.n = 0;
    this._m = new THREE.Matrix4();
    this._p = new THREE.Vector3();
    this._q = new THREE.Quaternion();
    this._s = new THREE.Vector3();
    this._up = new THREE.Vector3(0, 1, 0);
    this._c = new THREE.Color();
  }

  begin() { this.n = 0; }

  add(x, y, z, rotY, sx, sy, sz, tint = 1) {
    if (this.n >= this.capacity) return;
    this._p.set(x, y, z);
    this._q.setFromAxisAngle(this._up, rotY);
    this._s.set(sx, sy, sz);
    this._m.compose(this._p, this._q, this._s);
    this.mesh.setMatrixAt(this.n, this._m);
    if (this.mesh.instanceColor !== undefined || true) {
      this._c.setScalar(tint);
      this.mesh.setColorAt(this.n, this._c);
    }
    this.n += 1;
  }

  end() {
    this.mesh.count = this.n;
    this.mesh.instanceMatrix.needsUpdate = true;
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }
}

/* ==========================================================================
   The props system
   ========================================================================== */

export function createProps(THREE, textures = {}) {
  const group = new THREE.Group();
  const solids = [];

  const geos = {
    cyl: new THREE.CylinderGeometry(1, 1.15, 1, 7, 1),
    cone: new THREE.CylinderGeometry(0.03, 1, 1, 8, 1),
    sph: new THREE.SphereGeometry(1, 8, 6),
    box: new THREE.BoxGeometry(1, 1, 1),
    rock: new THREE.IcosahedronGeometry(1, 1),
    blade: new THREE.CylinderGeometry(0.35, 1, 1, 4, 1),
  };

  /* Materials. Trees get the needle/bark textures if they arrived — the
     green channel decides which map a fragment belongs to, Alpen's trick. */
  const plainMat = new THREE.MeshLambertMaterial({ vertexColors: true });
  const treeMat = new THREE.MeshLambertMaterial({ vertexColors: true });
  if (textures.needle && textures.bark) {
    treeMat.onBeforeCompile = (shader) => {
      shader.uniforms.tNeedle = textures.needle;
      shader.uniforms.tBark = textures.bark;
      shader.vertexShader = shader.vertexShader
        .replace('#include <common>', `#include <common>
          varying vec3 vWorldP;`)
        .replace('#include <worldpos_vertex>', `#include <worldpos_vertex>
          vWorldP = (modelMatrix * instanceMatrix * vec4(position, 1.0)).xyz;`);
      shader.fragmentShader = shader.fragmentShader
        .replace('#include <common>', `#include <common>
          varying vec3 vWorldP;
          uniform sampler2D tNeedle, tBark;`)
        .replace('#include <color_fragment>', `#include <color_fragment>
          {
            float leafy = step(diffuseColor.r * 1.15, diffuseColor.g);
            vec3 needle = texture2D(tNeedle, vWorldP.xz * 0.9).rgb;
            vec3 bark = texture2D(tBark, vec2(vWorldP.x + vWorldP.z, vWorldP.y) * 0.55).rgb;
            diffuseColor.rgb *= mix(bark, needle, leafy) * 2.1;
          }`);
    };
    treeMat.customProgramCacheKey = () => 'sommer-tree';
  }
  const rockMat = new THREE.MeshLambertMaterial({ vertexColors: true });
  if (textures.granite) {
    rockMat.onBeforeCompile = (shader) => {
      shader.uniforms.tRock = textures.granite;
      shader.vertexShader = shader.vertexShader
        .replace('#include <common>', `#include <common>
          varying vec3 vWorldP;`)
        .replace('#include <worldpos_vertex>', `#include <worldpos_vertex>
          vWorldP = (modelMatrix * instanceMatrix * vec4(position, 1.0)).xyz;`);
      shader.fragmentShader = shader.fragmentShader
        .replace('#include <common>', `#include <common>
          varying vec3 vWorldP;
          uniform sampler2D tRock;`)
        .replace('#include <color_fragment>', `#include <color_fragment>
          diffuseColor.rgb *= texture2D(tRock, vWorldP.xz * 0.45
            + vec2(vWorldP.y * 0.3, 0.0)).rgb * 2.0;`);
    };
    rockMat.customProgramCacheKey = () => 'sommer-rock';
  }

  /* Variants, grown once from fixed seeds. */
  function variants(n, grow, ...args) {
    const out = [];
    for (let i = 0; i < n; i++) {
      const rnd = stream(0x51ed27 + i * 7919);
      out.push(grow(THREE, geos, rnd, ...args));
    }
    return out;
  }
  const spruces = variants(6, growConifer, 0);
  const pines = variants(4, growConifer, 1);
  const krumm = variants(3, growConifer, 2);
  const birches = variants(4, growBirch);
  const bushes = variants(4, growBush);
  const boulders = variants(4, growBoulder);
  const logs = variants(2, growLog);
  const tufts = variants(3, growTuft);
  const flowers = variants(2, growFlower);
  const marker = growMarker(THREE, geos);

  /* One pool per variant family member — instance colour carries tint. */
  function pools(vars, mat, per, opts) {
    return vars.map((v) => {
      const p = new Pool(THREE, v.geo, mat, per, opts);
      p.meta = v;
      group.add(p.mesh);
      return p;
    });
  }
  const sprucePools = pools(spruces, treeMat, 260, { shadow: true });
  const pinePools = pools(pines, treeMat, 200, { shadow: true });
  const krummPools = pools(krumm, treeMat, 120, { shadow: true });
  const birchPools = pools(birches, treeMat, 160, { shadow: true });
  const bushPools = pools(bushes, plainMat, 200);
  const boulderPools = pools(boulders, rockMat, 90, { shadow: true });
  const logPools = pools(logs, plainMat, 40, { shadow: true });
  const tuftPools = pools(tufts, plainMat, 700);
  const flowerPools = pools(flowers, plainMat, 420);
  const markerPool = pools([marker], plainMat, 60)[0];

  const allPools = [
    ...sprucePools, ...pinePools, ...krummPools, ...birchPools,
    ...bushPools, ...boulderPools, ...logPools, ...tuftPools,
    ...flowerPools, markerPool,
  ];

  const zoneScratch = {};
  const nScratch = { set(x, y, z) { this.x = x; this.y = y; this.z = z; return this; }, normalize() { const l = Math.hypot(this.x, this.y, this.z); this.x /= l; this.y /= l; this.z /= l; return this; }, x: 0, y: 1, z: 0 };

  function placeBand(b) {
    const bandZ = -(b * BAND);   // top edge (least negative z) of the band
    const rnd = stream(Math.imul(b, 2654435761) | 0);
    const zn = zoneAt(bandZ - BAND * 0.5, zoneScratch);

    /* Trees. Density and species from the zone weights. */
    const woodDensity = zn.pine * 1.0 + zn.mixed * 0.9 + zn.meadow * 0.14
      + zn.rocky * 0.22 + zn.park * 0.08;
    for (let i = 0; i < PROPS.treesPerBand; i++) {
      const z = bandZ - rnd() * BAND;
      const roll = rnd();
      const side = rnd() < 0.5 ? -1 : 1;
      const spread = rnd();
      const stand = noise2(z * 0.005, side * 7.7, 61);   // clumps
      if (roll > woodDensity * (0.45 + 0.8 * stand)) continue;

      const gx = guideAt(z);
      const half = corridorHalfAt(z);
      const off = BED + VERGE + Math.pow(spread, 1.4) * (half + 26 - BED);
      const x = gx + side * off;
      const y = heightAt(x, z);
      normalFrom(heightAt, x, z, nScratch);
      if (nScratch.y < 0.72) continue;   // too steep even for a stubborn spruce

      // Species by chapter.
      const pick = rnd();
      let pool;
      if (zn.rocky > 0.5) pool = krummPools[Math.floor(rnd() * krummPools.length)];
      else if (zn.mixed > zn.pine && pick < 0.45) pool = birchPools[Math.floor(rnd() * birchPools.length)];
      else if (pick < 0.25) pool = pinePools[Math.floor(rnd() * pinePools.length)];
      else pool = sprucePools[Math.floor(rnd() * sprucePools.length)];

      const s = 0.7 + Math.pow(rnd(), 1.4) * 0.75;
      pool.add(x, y - 0.15, z, rnd() * Math.PI * 2, s, s * (0.9 + rnd() * 0.25), s, 0.85 + rnd() * 0.3);
      const r = pool.meta.trunkR * s + 0.12;
      solids.push({ x, z, r, hard: true });
    }

    /* Bushes — thickest where forest meets meadow. */
    const bushDensity = zn.mixed * 0.8 + zn.meadow * 0.5 + zn.pine * 0.35 + zn.park * 0.2;
    for (let i = 0; i < PROPS.bushesPerBand; i++) {
      const z = bandZ - rnd() * BAND;
      if (rnd() > bushDensity) continue;
      const gx = guideAt(z);
      const half = corridorHalfAt(z);
      const side = rnd() < 0.5 ? -1 : 1;
      const x = gx + side * (BED + 0.8 + Math.pow(rnd(), 1.3) * (half - BED));
      const y = heightAt(x, z);
      const pool = bushPools[Math.floor(rnd() * bushPools.length)];
      const s = 0.6 + rnd() * 0.9;
      pool.add(x, y - 0.05, z, rnd() * Math.PI * 2, s, s, s, 0.85 + rnd() * 0.3);
      solids.push({ x, z, r: pool.meta.trunkR * s, hard: false });
    }

    /* Boulders — the ridge's furniture, everyone else's accent. */
    const rockDensity = zn.rocky * 1.0 + zn.pine * 0.18 + zn.mixed * 0.15 + zn.meadow * 0.1;
    for (let i = 0; i < PROPS.rocksPerBand; i++) {
      const z = bandZ - rnd() * BAND;
      if (rnd() > rockDensity) continue;
      const gx = guideAt(z);
      const half = corridorHalfAt(z);
      const side = rnd() < 0.5 ? -1 : 1;
      const x = gx + side * (BED + VERGE + rnd() * (half + 12 - BED));
      const y = heightAt(x, z);
      const pool = boulderPools[Math.floor(rnd() * boulderPools.length)];
      const s = 0.5 + Math.pow(rnd(), 1.6) * 2.2;
      pool.add(x, y - s * 0.22, z, rnd() * Math.PI * 2, s, s, s, 0.9 + rnd() * 0.25);
      solids.push({ x, z, r: 0.85 * s, hard: true });
    }

    /* Logs, in the woods. */
    if (zn.pine + zn.mixed > 0.4 && rnd() < 0.5) {
      const z = bandZ - rnd() * BAND;
      const gx = guideAt(z);
      const side = rnd() < 0.5 ? -1 : 1;
      const x = gx + side * (BED + 2 + rnd() * 12);
      const y = heightAt(x, z);
      const pool = logPools[Math.floor(rnd() * logPools.length)];
      pool.add(x, y - 0.03, z, rnd() * Math.PI * 2, 1, 1, 1, 0.9 + rnd() * 0.2);
      solids.push({ x, z, r: pool.meta.trunkR, hard: false });
    }

    /* Grass tufts and flowers, framing the trail. */
    const floraDensity = zn.meadow * 1.0 + zn.mixed * 0.7 + zn.park * 0.7 + zn.pine * 0.25;
    for (let i = 0; i < PROPS.tuftsPerBand; i++) {
      const z = bandZ - rnd() * BAND;
      if (rnd() > floraDensity) continue;
      const gx = guideAt(z);
      const side = rnd() < 0.5 ? -1 : 1;
      const x = gx + side * (TERRAIN.trail.bed + 0.3 + Math.pow(rnd(), 1.8) * 14);
      const y = heightAt(x, z);
      const pool = tuftPools[Math.floor(rnd() * tuftPools.length)];
      const s = 0.7 + rnd() * 0.8;
      pool.add(x, y, z, rnd() * Math.PI * 2, s, s, s, 0.8 + rnd() * 0.45);
    }
    const flowerDensity = zn.meadow * 0.9 + zn.mixed * 0.4;
    for (let i = 0; i < PROPS.flowersPerBand; i++) {
      const z = bandZ - rnd() * BAND;
      if (rnd() > flowerDensity) continue;
      const gx = guideAt(z);
      const side = rnd() < 0.5 ? -1 : 1;
      const x = gx + side * (TERRAIN.trail.bed + 0.5 + Math.pow(rnd(), 1.5) * 11);
      const y = heightAt(x, z);
      const pool = flowerPools[Math.floor(rnd() * flowerPools.length)];
      // Meadow colours: white, yellow, violet, red.
      const tint = [1.0, 0.95, 0.7, 0.85][Math.floor(rnd() * 4)];
      pool.add(x, y, z, rnd() * Math.PI * 2, 1, 1, 1, tint);
    }

    /* A trail marker at the top of each band, alternating sides. */
    if (b % 2 === 0) {
      const z = bandZ - 2;
      const gx = guideAt(z);
      const side = (b % 4 === 0) ? 1 : -1;
      const x = gx + side * (TERRAIN.trail.bed + 1.2);
      markerPool.add(x, heightAt(x, z), z, side > 0 ? -0.4 : 0.4 + Math.PI, 1, 1, 1, 1);
    }
  }

  let currentBand = null;

  function rebuild(riderZ) {
    for (const p of allPools) p.begin();
    solids.length = 0;
    const bi = Math.max(0, Math.floor(-riderZ / BAND));
    // Nearest-first spiral, so capacity overflow drops the far scenery.
    placeBand(bi);
    for (let k = 1; k <= Math.max(AHEAD, BEHIND); k++) {
      if (k <= AHEAD) placeBand(bi + k);
      if (k <= BEHIND && bi - k >= 0) placeBand(bi - k);
    }
    for (const p of allPools) p.end();
  }

  function update(riderZ) {
    const bi = Math.max(0, Math.floor(-riderZ / BAND));
    if (bi !== currentBand) {
      currentBand = bi;
      rebuild(riderZ);
    }
  }

  function reset(riderZ) {
    currentBand = null;
    update(riderZ);
  }

  return { group, solids, update, reset };
}

