/* The read-out: Alpen's 5×7 bitmap language on a second high-DPI canvas.
   Speed hangs from the top-left corner, distance from the top-right, a
   charge bar breathes over the bottom edge while the hop is loading, and
   banners land in the empty band under the corners. Once the engine is
   ready the canvas also draws the title and pause cards.

   The HUD only ever states what the physics already did. */

import { drawText, measure, GLYPH_H, ADVANCE } from './font.js';

const q5 = (hex) => hex;   // the palette is already quiet; keep the hexes
const LEAF = '#6ee86e';
const SUN = '#ffb300';
const PAPER = '#f4f2ea';
const QUIET = 'rgba(244, 242, 234, 0.55)';
const INK = '#0a140c';

const CALM = typeof matchMedia !== 'undefined'
  ? matchMedia('(prefers-reduced-motion: reduce)') : { matches: false };

export function createHud(canvas, readoutEl, calloutEl) {
  const ctx = canvas.getContext('2d');
  let W = 0;
  let H = 0;
  let UI = 2;
  let lastSig = '';
  let bannerText = '';
  let bannerUntil = 0;
  let now = 0;
  let speakTimer = 0;

  function size() {
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = Math.round(canvas.clientWidth * dpr);
    const h = Math.round(canvas.clientHeight * dpr);
    if (w === W && h === H) return;
    W = canvas.width = w;
    H = canvas.height = h;
    UI = Math.max(2, Math.min(6, Math.round(h / 380)));
    ctx.imageSmoothingEnabled = false;
    lastSig = '';
  }

  function banner(text, seconds = 2.2) {
    bannerText = text;
    bannerUntil = now + seconds;
    lastSig = '';
    if (calloutEl) calloutEl.textContent = text;
  }

  function centre(text, y, color, sizeMul, halo) {
    const w = measure(text, UI * sizeMul);
    drawText(ctx, text, Math.round((W - w) / 2), y, color, UI * sizeMul, halo);
  }

  function drawCard(g, paused) {
    ctx.fillStyle = 'rgba(8, 18, 10, 0.55)';
    ctx.fillRect(0, 0, W, H);
    const cy = Math.round(H * 0.30);
    centre('SOMMER', cy, PAPER, 4, INK);
    centre(paused ? 'PAUSED' : 'ENDLESS SUMMER DOWNHILL', cy + GLYPH_H * UI * 4 + 8 * UI, LEAF, 1, INK);
    const seed = `TRAIL ${g.seedCode || '—'}`;
    centre(seed, cy + GLYPH_H * UI * 5 + 16 * UI, QUIET, 1, INK);
    if (!paused) {
      const keys = g.touch
        ? 'STEER · PEDAL · BRAKE · HOP'
        : 'A/D STEER · W PEDAL · S BRAKE · SPACE HOP';
      centre(keys, cy + GLYPH_H * UI * 6 + 26 * UI, QUIET, 1, INK);
    }
    const blink = CALM.matches || Math.floor(now * 1.6) % 2 === 0;
    if (blink) {
      centre(g.touch ? '[ TAP TO RIDE ]' : '[ PRESS ANY KEY TO RIDE ]',
        Math.round(H * 0.72), SUN, 1, INK);
    }
  }

  function draw(g) {
    ctx.clearRect(0, 0, W, H);
    const pad = 10 * UI;

    if (g.mode !== 'playing') {
      drawCard(g, g.mode === 'paused');
      return;
    }

    // Speed, top-left.
    const kmh = Math.round(g.speed * 3.6);
    drawText(ctx, String(kmh), pad, pad, PAPER, UI * 2, INK);
    drawText(ctx, 'KM/H', pad + measure(String(kmh), UI * 2) + 4 * UI,
      pad + GLYPH_H * UI, QUIET, UI, INK);

    // Distance, top-right.
    const dist = g.distance >= 1000
      ? `${(g.distance / 1000).toFixed(2)}KM`
      : `${Math.round(g.distance)}M`;
    drawText(ctx, dist, W - pad - measure(dist, UI * 2), pad, PAPER, UI * 2, INK);

    // Airtime, while it is happening.
    if (g.airTime > 0.25) {
      centre(`${g.airTime.toFixed(1)}S`, Math.round(H * 0.24), SUN, 2, INK);
    }

    // The banner band.
    if (bannerText && now < bannerUntil) {
      centre(bannerText, pad + GLYPH_H * UI * 2 + 8 * UI, LEAF, 1, INK);
    }

    // Charge bar, bottom centre.
    if (g.charge > 0.01) {
      const bw = Math.round(W * 0.22);
      const bh = 3 * UI;
      const bx = Math.round((W - bw) / 2);
      const by = H - pad * 2;
      ctx.fillStyle = 'rgba(244,242,234,0.25)';
      ctx.fillRect(bx, by, bw, bh);
      ctx.fillStyle = SUN;
      ctx.fillRect(bx, by, Math.round(bw * g.charge), bh);
    }

    // Muted marker.
    if (g.muted) {
      drawText(ctx, 'MUTED', W - pad - measure('MUTED', UI), H - pad - GLYPH_H * UI, QUIET, UI, INK);
    }
  }

  function update(g, dt) {
    now += dt;
    size();
    const sig = [g.mode, Math.round(g.speed * 3.6), Math.round(g.distance),
      g.airTime > 0.25 ? g.airTime.toFixed(1) : 0,
      bannerText && now < bannerUntil ? bannerText : '',
      g.charge > 0.01 ? Math.round(g.charge * 20) : 0,
      g.muted ? 1 : 0, Math.floor(now * 1.6) % 2, W, H].join('|');
    if (sig !== lastSig) {
      lastSig = sig;
      draw(g);
    }
    // The spoken mirror, once a second.
    speakTimer -= dt;
    if (speakTimer <= 0 && readoutEl) {
      speakTimer = 1;
      readoutEl.textContent = g.mode === 'playing'
        ? `${Math.round(g.speed * 3.6)} kilometres per hour, ${Math.round(g.distance)} metres`
        : g.mode;
    }
  }

  return { update, banner, canvas };
}

