input.content:
/* Assembly. The shape is Alpen's: modules built in dependency order around
   one `world` object, a fixed 120 Hz physics loop inside a render loop that
   interpolates between steps, and a game that is only ever 'attract',
   'playing' or 'paused'. */

import * as THREE from 'three';
import { RENDER, RIDER as RIDER_CFG } from './config.js';
import { setWorldSeed, worldSeedCode, randomWorldSeed } from './noise.js';
import {
  createTerrain, heightAt, surfaceAt, guideAt, zoneAt,
} from './terrain.js';
import { Rider } from './rider.js';
import { createInput } from './input.js';
import { createHeadCamera } from './camera.js';
import { createBikeModel } from './bikeModel.js';
import { createSky } from './sky.js';
import { createProps } from './props.js';
import { createHud } from './hud.js';
import { createAudio } from './audio.js';

const boot = window.__sommerBoot || { step() {}, giveUp() {}, fail() {} };
boot.step('engine');

/* ---------------- seed ---------------- */
const params = new URLSearchParams(location.search);
const seedParam = params.get('seed');
const seed = setWorldSeed(seedParam || randomWorldSeed());
const seedCode = worldSeedCode(seed);
if (!seedParam || seedParam !== seedCode) {
  params.set('seed', seedCode);
  history.replaceState(null, '', `${location.pathname}?${params}`);
}

/* ---------------- renderer ---------------- */
const stage = document.getElementById('stage');
let renderer;
try {
  renderer = new THREE.WebGLRenderer({ canvas: stage, antialias: true });
  const gl = renderer.getContext();
  if (!gl) throw new Error('no context');
} catch (err) {
  const tagline = document.querySelector('.curtain .tagline.start-only');
  if (tagline) tagline.textContent = 'This one needs WebGL, and the browser said no. Try another browser or device.';
  const go = document.querySelector('.curtain .go');
  if (go) go.hidden = true;
  boot.giveUp();
  throw err;
}
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.02;

const basePixelRatio = Math.min(RENDER.maxPixelRatio, window.devicePixelRatio || 1);
let renderScale = 1;
renderer.setPixelRatio(basePixelRatio);
renderer.setSize(window.innerWidth, window.innerHeight);

/* ---------------- scene ---------------- */
const scene = new THREE.Scene();
scene.fog = new THREE.Fog(RENDER.fogColor, RENDER.fogNear, RENDER.fogFar);

const camera = new THREE.PerspectiveCamera(
  RENDER.fov, window.innerWidth / window.innerHeight, RENDER.near, RENDER.far,
);
scene.add(camera);   // the cockpit hangs off it

const maxAniso = renderer.capabilities.getMaxAnisotropy();
const terrain = createTerrain(THREE, maxAniso);
scene.add(terrain.mesh);

const sky = createSky(THREE, renderer);
scene.add(sky.group);
scene.add(sky.sun);
scene.add(sky.sunTarget);
scene.add(sky.hemi);

/* Prop textures — neutral until they land, Alpen's uniform-record trick. */
const texLoader = new THREE.TextureLoader();
const neutralTex = new THREE.DataTexture(new Uint8Array([150, 150, 150, 255]), 1, 1, THREE.RGBAFormat);
neutralTex.needsUpdate = true;
function texRecord(file) {
  const record = { value: neutralTex };
  texLoader.load(new URL(`../assets/textures/${file}`, import.meta.url).href, (t) => {
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.colorSpace = THREE.SRGBColorSpace;
    t.anisotropy = maxAniso;
    record.value = t;
  });
  return record;
}
const props = createProps(THREE, {
  needle: texRecord('tree/pine-needles.jpg'),
  bark: texRecord('tree/tree-bark.jpg'),
  granite: texRecord('rock/rock-granite.jpg'),
});
scene.add(props.group);

/* ---------------- the world, the rider, the head ---------------- */
const world = { height: heightAt, surfaceAt };
const rider = new Rider(THREE, world);
const head = createHeadCamera(THREE, camera);
const bike = createBikeModel(THREE, camera);

/* ---------------- game state ---------------- */
const game = {
  mode: 'attract',
  seedCode,
  speed: 0,
  distance: 0,
  airTime: 0,
  charge: 0,
  muted: false,
  touch: false,
};
let startZ = -12;

const hud = createHud(
  document.querySelector('.readout'),
  document.querySelector('[data-readout]'),
  document.querySelector('[data-callout]'),
);
const audio = createAudio();
const curtain = document.querySelector('.curtain');

/* ---------------- events from the physics ---------------- */
rider.on('land', (impact, airTime) => {
  head.kick(impact);
  audio.land(impact);
  if (airTime > 0.8) hud.banner(`AIR ${airTime.toFixed(1)}S`);
});
rider.on('launch', (vy) => { if (vy > 1.5) audio.hop(); });
rider.on('fall', () => {
  audio.crash();
  hud.banner('CRASH', 1.6);
});
rider.on('brush', () => audio.brush());
rider.on('strike', (kind) => { if (kind === 'graze') audio.brush(); });

/* ---------------- collision with the standing world ---------------- */
function collide() {
  const solids = props.solids;
  const px = rider.pos.x;
  const pz = rider.pos.z;
  for (let i = 0; i < solids.length; i++) {
    const s = solids[i];
    const dz = pz - s.z;
    if (dz > 3 || dz < -3) continue;
    const dx = px - s.x;
    const reach = s.r + 0.35;
    const d2 = dx * dx + dz * dz;
    if (d2 >= reach * reach) continue;
    const d = Math.sqrt(d2) || 0.001;
    const closeness = 1 - d / reach;
    if (s.hard) {
      rider.strike(dx / d, dz / d, closeness);
    } else {
      // Soft brush: bushes and logs scrub speed and rustle.
      rider.vel.multiplyScalar(1 - 0.5 * closeness * 0.16);
      if (closeness > 0.4) rider.emit('brush');
    }
    // Push out so one bush is one brush, not sixty.
    rider.pos.x = s.x + (dx / d) * reach;
    rider.pos.z = s.z + (dz / d) * reach;
  }
}

/* ---------------- zone banners ---------------- */
const ZONE_NAMES = {
  pine: 'PINE FOREST', mixed: 'MIXED FOREST', meadow: 'HIGH MEADOW',
  rocky: 'ROCKY RIDGE', park: 'BIKE PARK',
};
let shownZone = '';
let zoneTimer = 0;
const zoneScratch = {};
function watchZones(dt) {
  zoneTimer -= dt;
  if (zoneTimer > 0) return;
  zoneTimer = 0.8;
  const zn = zoneAt(rider.pos.z - 30, zoneScratch);
  let best = '';
  let bestW = 0.62;
  for (const k of ['pine', 'mixed', 'meadow', 'rocky', 'park']) {
    if (zn[k] > bestW) { best = k; bestW = zn[k]; }
  }
  if (best && best !== shownZone) {
    shownZone = best;
    if (game.mode === 'playing') hud.banner(ZONE_NAMES[best]);
  }
}

/* ---------------- modes ---------------- */
function begin() {
  if (!bootReady) return;
  audio.start();
  if (game.mode === 'attract') restart(true);
  game.mode = 'playing';
  curtain.classList.remove('on');
  curtain.dataset.screen = 'paused';
}

function pause() {
  if (game.mode !== 'playing') return;
  game.mode = 'paused';
  curtain.dataset.screen = 'paused';
  curtain.classList.add('on');
  audio.quiet();
  input.calm();
}

function restart(fromTop = false) {
  const z = fromTop ? startZ : Math.min(startZ, rider.pos.z + 6);
  const x = guideAt(z);
  // Face down the guide line.
  const ahead = guideAt(z - 8);
  const yaw = Math.atan2(ahead - x, 8);
  rider.reset(x, z, yaw);
  head.reset();
  props.reset(rider.pos.z);
  terrain.reset(rider.pos.x, rider.pos.z);
  shownZone = '';
}

function newMountain() {
  const p = new URLSearchParams(location.search);
  p.set('seed', worldSeedCode(randomWorldSeed()));
  location.assign(`${location.pathname}?${p}`);
}

function toggleMute() {
  game.muted = audio.toggleMute();
  const btn = document.querySelector('[data-action="mute"]');
  if (btn) btn.setAttribute('aria-pressed', String(game.muted));
}

function onKey(e) {
  if (game.mode !== 'playing') {
    if (e.code === 'KeyM') { toggleMute(); return; }
    begin();
    return;
  }
  if (e.code === 'Escape') pause();
  else if (e.code === 'KeyR') restart();
  else if (e.code === 'KeyN') newMountain();
  else if (e.code === 'KeyM') toggleMute();
}

const input = createInput(window, { key: onKey });

/* Touch. */
const isTouch = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
if (isTouch) {
  document.body.classList.add('touch');
  game.touch = true;
  const pad = document.querySelector('.pad');
  if (pad) input.bindTouch(pad);
}
curtain.addEventListener('pointerdown', () => {
  if (game.mode !== 'playing') begin();
});
document.querySelector('[data-action="pause"]')?.addEventListener('click', () => {
  if (game.mode === 'playing') pause();
});
document.querySelector('[data-action="mute"]')?.addEventListener('click', toggleMute);

document.addEventListener('visibilitychange', () => {
  if (document.hidden) pause();
});
renderer.domElement.addEventListener('webglcontextlost', (e) => {
  e.preventDefault();
  pause();
});

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

/* ---------------- the loop ---------------- */
const STEP = 1 / 120;
let lastStep = 0;
let last = 0;
let bootReady = false;
const stepFrom = new THREE.Vector3();
const truePos = new THREE.Vector3();
let stepFromYaw = 0;
let trueYaw = 0;

// A small honest governor: when frames run long, render fewer pixels.
let perfAvg = 16;
let perfTimer = 0;

const neutralInput = { turn: 0, pedal: false, brake: false, jump: false };

function frame(now) {
  requestAnimationFrame(frame);
  const frameDt = last ? (now - last) / 1000 : 1 / 60;
  last = now;
  const dt = Math.min(0.05, frameDt);
  const running = game.mode === 'playing';

  if (running) {
    input.update(dt);
    const control = input.state;
    lastStep += dt;
    let steps = 0;
    stepFrom.copy(rider.pos);
    stepFromYaw = rider.yaw;
    while (lastStep >= STEP && steps < 8) {
      stepFrom.copy(rider.pos);
      stepFromYaw = rider.yaw;
      rider.step(STEP, control);
      input.stepped();
      collide();
      lastStep -= STEP;
      steps += 1;
    }
    if (steps >= 8) lastStep = 0;

    game.speed = rider.speed;
    game.distance = Math.max(game.distance, -(rider.pos.z - startZ));
    game.airTime = rider.state === 'air' ? rider.airTime : 0;
    game.charge = rider.charge;
    watchZones(dt);
    audio.ambience(rider.speed, rider.slide, rider.grounded && rider.state === 'ride',
      rider.pedaling, rider.surf, dt);
  }

  /* Draw at the interpolated position — physics never sees this. */
  const alpha = Math.min(1, lastStep / STEP);
  truePos.copy(rider.pos);
  trueYaw = rider.yaw;
  if (running) {
    rider.pos.lerpVectors(stepFrom, truePos, alpha);
    let dy = trueYaw - stepFromYaw;
    while (dy > Math.PI) dy -= Math.PI * 2;
    while (dy < -Math.PI) dy += Math.PI * 2;
    rider.yaw = stepFromYaw + dy * alpha;
  }

  terrain.update(rider.pos.x, rider.pos.z);
  props.update(rider.pos.z);
  sky.update(rider.pos, dt);
  head.update(rider, dt, world);
  bike.update(rider, running ? input.state : neutralInput, dt);

  rider.pos.copy(truePos);
  rider.yaw = trueYaw;

  hud.update(game, dt);

  // The resolution governor.
  perfAvg += (frameDt * 1000 - perfAvg) * 0.05;
  perfTimer -= dt;
  if (perfTimer <= 0) {
    perfTimer = 2;
    if (perfAvg > 26 && renderScale > 0.6) {
      renderScale = Math.max(0.6, renderScale - 0.12);
      renderer.setPixelRatio(basePixelRatio * renderScale);
    } else if (perfAvg < 15 && renderScale < 1) {
      renderScale = Math.min(1, renderScale + 0.1);
      renderer.setPixelRatio(basePixelRatio * renderScale);
    }
  }

  renderer.render(scene, camera);
}

/* ---------------- boot ---------------- */
restart(true);
boot.step('trail');

// Compile once off-screen, then declare ready on the first real frame.
renderer.compile(scene, camera);
Promise.race([
  terrain.surfacesReady,
  new Promise((r) => setTimeout(r, 5000)),
]).then(() => {
  requestAnimationFrame((now) => {
    frame(now);
    document.body.classList.add('ready');
    boot.step('shaders');
    bootReady = true;
  });
});

/* The debug hatch, in Alpen's shape. */
window.__sommer = {
  rider,
  game,
  scene,
  renderer,
  debug() {
    return {
      mode: game.mode,
      pos: { x: rider.pos.x, y: rider.pos.y, z: rider.pos.z },
      vel: { x: rider.vel.x, y: rider.vel.y, z: rider.vel.z },
      speed: rider.speed,
      yaw: rider.yaw,
      state: rider.state,
      grounded: rider.grounded,
      surf: rider.surf,
      distance: game.distance,
      solids: props.solids.length,
    };
  },
};

toolUseResult.content:
/* Assembly. The shape is Alpen's: modules built in dependency order around
   one `world` object, a fixed 120 Hz physics loop inside a render loop that
   interpolates between steps, and a game that is only ever 'attract',
   'playing' or 'paused'. */

import * as THREE from 'three';
import { RENDER, RIDER as RIDER_CFG } from './config.js';
import { setWorldSeed, worldSeedCode, randomWorldSeed } from './noise.js';
import {
  createTerrain, heightAt, surfaceAt, guideAt, zoneAt,
} from './terrain.js';
import { Rider } from './rider.js';
import { createInput } from './input.js';
import { createHeadCamera } from './camera.js';
import { createBikeModel } from './bikeModel.js';
import { createSky } from './sky.js';
import { createProps } from './props.js';
import { createHud } from './hud.js';
import { createAudio } from './audio.js';

const boot = window.__sommerBoot || { step() {}, giveUp() {}, fail() {} };
boot.step('engine');

/* ---------------- seed ---------------- */
const params = new URLSearchParams(location.search);
const seedParam = params.get('seed');
const seed = setWorldSeed(seedParam || randomWorldSeed());
const seedCode = worldSeedCode(seed);
if (!seedParam || seedParam !== seedCode) {
  params.set('seed', seedCode);
  history.replaceState(null, '', `${location.pathname}?${params}`);
}

/* ---------------- renderer ---------------- */
const stage = document.getElementById('stage');
let renderer;
try {
  renderer = new THREE.WebGLRenderer({ canvas: stage, antialias: true });
  const gl = renderer.getContext();
  if (!gl) throw new Error('no context');
} catch (err) {
  const tagline = document.querySelector('.curtain .tagline.start-only');
  if (tagline) tagline.textContent = 'This one needs WebGL, and the browser said no. Try another browser or device.';
  const go = document.querySelector('.curtain .go');
  if (go) go.hidden = true;
  boot.giveUp();
  throw err;
}
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.02;

const basePixelRatio = Math.min(RENDER.maxPixelRatio, window.devicePixelRatio || 1);
let renderScale = 1;
renderer.setPixelRatio(basePixelRatio);
renderer.setSize(window.innerWidth, window.innerHeight);

/* ---------------- scene ---------------- */
const scene = new THREE.Scene();
scene.fog = new THREE.Fog(RENDER.fogColor, RENDER.fogNear, RENDER.fogFar);

const camera = new THREE.PerspectiveCamera(
  RENDER.fov, window.innerWidth / window.innerHeight, RENDER.near, RENDER.far,
);
scene.add(camera);   // the cockpit hangs off it

const maxAniso = renderer.capabilities.getMaxAnisotropy();
const terrain = createTerrain(THREE, maxAniso);
scene.add(terrain.mesh);

const sky = createSky(THREE, renderer);
scene.add(sky.group);
scene.add(sky.sun);
scene.add(sky.sunTarget);
scene.add(sky.hemi);

/* Prop textures — neutral until they land, Alpen's uniform-record trick. */
const texLoader = new THREE.TextureLoader();
const neutralTex = new THREE.DataTexture(new Uint8Array([150, 150, 150, 255]), 1, 1, THREE.RGBAFormat);
neutralTex.needsUpdate = true;
function texRecord(file) {
  const record = { value: neutralTex };
  texLoader.load(new URL(`../assets/textures/${file}`, import.meta.url).href, (t) => {
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.colorSpace = THREE.SRGBColorSpace;
    t.anisotropy = maxAniso;
    record.value = t;
  });
  return record;
}
const props = createProps(THREE, {
  needle: texRecord('tree/pine-needles.jpg'),
  bark: texRecord('tree/tree-bark.jpg'),
  granite: texRecord('rock/rock-granite.jpg'),
});
scene.add(props.group);

/* ---------------- the world, the rider, the head ---------------- */
const world = { height: heightAt, surfaceAt };
const rider = new Rider(THREE, world);
const head = createHeadCamera(THREE, camera);
const bike = createBikeModel(THREE, camera);

/* ---------------- game state ---------------- */
const game = {
  mode: 'attract',
  seedCode,
  speed: 0,
  distance: 0,
  airTime: 0,
  charge: 0,
  muted: false,
  touch: false,
};
let startZ = -12;

const hud = createHud(
  document.querySelector('.readout'),
  document.querySelector('[data-readout]'),
  document.querySelector('[data-callout]'),
);
const audio = createAudio();
const curtain = document.querySelector('.curtain');

/* ---------------- events from the physics ---------------- */
rider.on('land', (impact, airTime) => {
  head.kick(impact);
  audio.land(impact);
  if (airTime > 0.8) hud.banner(`AIR ${airTime.toFixed(1)}S`);
});
rider.on('launch', (vy) => { if (vy > 1.5) audio.hop(); });
rider.on('fall', () => {
  audio.crash();
  hud.banner('CRASH', 1.6);
});
rider.on('brush', () => audio.brush());
rider.on('strike', (kind) => { if (kind === 'graze') audio.brush(); });

/* ---------------- collision with the standing world ---------------- */
function collide() {
  const solids = props.solids;
  const px = rider.pos.x;
  const pz = rider.pos.z;
  for (let i = 0; i < solids.length; i++) {
    const s = solids[i];
    const dz = pz - s.z;
    if (dz > 3 || dz < -3) continue;
    const dx = px - s.x;
    const reach = s.r + 0.35;
    const d2 = dx * dx + dz * dz;
    if (d2 >= reach * reach) continue;
    const d = Math.sqrt(d2) || 0.001;
    const closeness = 1 - d / reach;
    if (s.hard) {
      rider.strike(dx / d, dz / d, closeness);
    } else {
      // Soft brush: bushes and logs scrub speed and rustle.
      rider.vel.multiplyScalar(1 - 0.5 * closeness * 0.16);
      if (closeness > 0.4) rider.emit('brush');
    }
    // Push out so one bush is one brush, not sixty.
    rider.pos.x = s.x + (dx / d) * reach;
    rider.pos.z = s.z + (dz / d) * reach;
  }
}

/* ---------------- zone banners ---------------- */
const ZONE_NAMES = {
  pine: 'PINE FOREST', mixed: 'MIXED FOREST', meadow: 'HIGH MEADOW',
  rocky: 'ROCKY RIDGE', park: 'BIKE PARK',
};
let shownZone = '';
let zoneTimer = 0;
const zoneScratch = {};
function watchZones(dt) {
  zoneTimer -= dt;
  if (zoneTimer > 0) return;
  zoneTimer = 0.8;
  const zn = zoneAt(rider.pos.z - 30, zoneScratch);
  let best = '';
  let bestW = 0.62;
  for (const k of ['pine', 'mixed', 'meadow', 'rocky', 'park']) {
    if (zn[k] > bestW) { best = k; bestW = zn[k]; }
  }
  if (best && best !== shownZone) {
    shownZone = best;
    if (game.mode === 'playing') hud.banner(ZONE_NAMES[best]);
  }
}

/* ---------------- modes ---------------- */
function begin() {
  if (!bootReady) return;
  audio.start();
  if (game.mode === 'attract') restart(true);
  game.mode = 'playing';
  curtain.classList.remove('on');
  curtain.dataset.screen = 'paused';
}

function pause() {
  if (game.mode !== 'playing') return;
  game.mode = 'paused';
  curtain.dataset.screen = 'paused';
  curtain.classList.add('on');
  audio.quiet();
  input.calm();
}

function restart(fromTop = false) {
  const z = fromTop ? startZ : Math.min(startZ, rider.pos.z + 6);
  const x = guideAt(z);
  // Face down the guide line.
  const ahead = guideAt(z - 8);
  const yaw = Math.atan2(ahead - x, 8);
  rider.reset(x, z, yaw);
  head.reset();
  props.reset(rider.pos.z);
  terrain.reset(rider.pos.x, rider.pos.z);
  shownZone = '';
}

function newMountain() {
  const p = new URLSearchParams(location.search);
  p.set('seed', worldSeedCode(randomWorldSeed()));
  location.assign(`${location.pathname}?${p}`);
}

function toggleMute() {
  game.muted = audio.toggleMute();
  const btn = document.querySelector('[data-action="mute"]');
  if (btn) btn.setAttribute('aria-pressed', String(game.muted));
}

function onKey(e) {
  if (game.mode !== 'playing') {
    if (e.code === 'KeyM') { toggleMute(); return; }
    begin();
    return;
  }
  if (e.code === 'Escape') pause();
  else if (e.code === 'KeyR') restart();
  else if (e.code === 'KeyN') newMountain();
  else if (e.code === 'KeyM') toggleMute();
}

const input = createInput(window, { key: onKey });

/* Touch. */
const isTouch = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
if (isTouch) {
  document.body.classList.add('touch');
  game.touch = true;
  const pad = document.querySelector('.pad');
  if (pad) input.bindTouch(pad);
}
curtain.addEventListener('pointerdown', () => {
  if (game.mode !== 'playing') begin();
});
document.querySelector('[data-action="pause"]')?.addEventListener('click', () => {
  if (game.mode === 'playing') pause();
});
document.querySelector('[data-action="mute"]')?.addEventListener('click', toggleMute);

document.addEventListener('visibilitychange', () => {
  if (document.hidden) pause();
});
renderer.domElement.addEventListener('webglcontextlost', (e) => {
  e.preventDefault();
  pause();
});

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

/* ---------------- the loop ---------------- */
const STEP = 1 / 120;
let lastStep = 0;
let last = 0;
let bootReady = false;
const stepFrom = new THREE.Vector3();
const truePos = new THREE.Vector3();
let stepFromYaw = 0;
let trueYaw = 0;

// A small honest governor: when frames run long, render fewer pixels.
let perfAvg = 16;
let perfTimer = 0;

const neutralInput = { turn: 0, pedal: false, brake: false, jump: false };

function frame(now) {
  requestAnimationFrame(frame);
  const frameDt = last ? (now - last) / 1000 : 1 / 60;
  last = now;
  const dt = Math.min(0.05, frameDt);
  const running = game.mode === 'playing';

  if (running) {
    input.update(dt);
    const control = input.state;
    lastStep += dt;
    let steps = 0;
    stepFrom.copy(rider.pos);
    stepFromYaw = rider.yaw;
    while (lastStep >= STEP && steps < 8) {
      stepFrom.copy(rider.pos);
      stepFromYaw = rider.yaw;
      rider.step(STEP, control);
      input.stepped();
      collide();
      lastStep -= STEP;
      steps += 1;
    }
    if (steps >= 8) lastStep = 0;

    game.speed = rider.speed;
    game.distance = Math.max(game.distance, -(rider.pos.z - startZ));
    game.airTime = rider.state === 'air' ? rider.airTime : 0;
    game.charge = rider.charge;
    watchZones(dt);
    audio.ambience(rider.speed, rider.slide, rider.grounded && rider.state === 'ride',
      rider.pedaling, rider.surf, dt);
  }

  /* Draw at the interpolated position — physics never sees this. */
  const alpha = Math.min(1, lastStep / STEP);
  truePos.copy(rider.pos);
  trueYaw = rider.yaw;
  if (running) {
    rider.pos.lerpVectors(stepFrom, truePos, alpha);
    let dy = trueYaw - stepFromYaw;
    while (dy > Math.PI) dy -= Math.PI * 2;
    while (dy < -Math.PI) dy += Math.PI * 2;
    rider.yaw = stepFromYaw + dy * alpha;
  }

  terrain.update(rider.pos.x, rider.pos.z);
  props.update(rider.pos.z);
  sky.update(rider.pos, dt);
  head.update(rider, dt, world);
  bike.update(rider, running ? input.state : neutralInput, dt);

  rider.pos.copy(truePos);
  rider.yaw = trueYaw;

  hud.update(game, dt);

  // The resolution governor.
  perfAvg += (frameDt * 1000 - perfAvg) * 0.05;
  perfTimer -= dt;
  if (perfTimer <= 0) {
    perfTimer = 2;
    if (perfAvg > 26 && renderScale > 0.6) {
      renderScale = Math.max(0.6, renderScale - 0.12);
      renderer.setPixelRatio(basePixelRatio * renderScale);
    } else if (perfAvg < 15 && renderScale < 1) {
      renderScale = Math.min(1, renderScale + 0.1);
      renderer.setPixelRatio(basePixelRatio * renderScale);
    }
  }

  renderer.render(scene, camera);
}

/* ---------------- boot ---------------- */
restart(true);
boot.step('trail');

// Compile once off-screen, then declare ready on the first real frame.
renderer.compile(scene, camera);
Promise.race([
  terrain.surfacesReady,
  new Promise((r) => setTimeout(r, 5000)),
]).then(() => {
  requestAnimationFrame((now) => {
    frame(now);
    document.body.classList.add('ready');
    boot.step('shaders');
    bootReady = true;
  });
});

/* The debug hatch, in Alpen's shape. */
window.__sommer = {
  rider,
  game,
  scene,
  renderer,
  debug() {
    return {
      mode: game.mode,
      pos: { x: rider.pos.x, y: rider.pos.y, z: rider.pos.z },
      vel: { x: rider.vel.x, y: rider.vel.y, z: rider.vel.z },
      speed: rider.speed,
      yaw: rider.yaw,
      state: rider.state,
      grounded: rider.grounded,
      surf: rider.surf,
      distance: game.distance,
      solids: props.solids.length,
    };
  },
};

