async () => {
  await new Promise(r => setTimeout(r, 1500));
  const S = window.__sommer;
  const terrainMesh = S.scene.children.find(c => c.type === 'Mesh' && c.geometry.attributes.aSurf);
  const col = terrainMesh.geometry.attributes.color.array;
  const surf = terrainMesh.geometry.attributes.aSurf.array;
  // sample a few vertices near the middle of the buffer
  const mid = Math.floor(col.length / 6) * 3;
  const samples = [];
  for (let k = 0; k < 4; k++) {
    const i = mid + k * 9000;
    samples.push({
      color: [col[i], col[i+1], col[i+2]].map(v => +v.toFixed(2)),
      surfIdx: [surf[(i/3)*4], surf[(i/3)*4+1], surf[(i/3)*4+2], surf[(i/3)*4+3]].map(v => +v.toFixed(2)),
    });
  }
  return { mode: S.game.mode, samples, fog: !!S.scene.fog };
}

