  const farRidge = ridgeRing(1850, 620, -60, 140, 401, '#9db4cc', 0.72);
  const nearRidge = ridgeRing(1350, 380, -40, 120, 407, '#5f7d94');
  // Tint the near ridge toward conifer green at its base.
  group.add(farRidge);
  group.add(nearRidge);

  /* A haze skirt under everything, exactly the fog colour, hiding the
     mesh's far edge. */
