      const horns = 0.55 + 0.45 * noise2(Math.cos(a) * 7.3, Math.sin(a) * 7.3 + 3, seed + 1);
      const knife = 0.7 + 0.3 * noise2(Math.cos(a) * 21.0, Math.sin(a) * 21.0, seed + 2);
