/* The summer sky, and everything standing at infinity under it.

   One fixed weather: a bright alpine morning. The dome is a three-stop
   gradient with a sun lobe and a drifting cumulus deck — the cheapest
   atmosphere in graphics, borrowed from Alpen — and the horizon hands over
   to the fog colour so the ground can dissolve into it. Around the rider
   stand two rings of distant ridges, the far one snow-capped, both moved
   wholesale with the camera: at their pretended distances the parallax of a
   corridor's worth of wander is under the eye's threshold.

   Lighting is two lamps: a warm directional sun with a texel-snapped shadow
   box, and a blue-green hemisphere fill. */

import { RENDER } from './config.js';
import { noise2, hash2 } from './noise.js';

const SUN_DIR = { x: 0.48, y: 0.62, z: -0.42 };   // morning, high and to the right

export function createSky(THREE, renderer) {
  const group = new THREE.Group();

  /* ---------------- the dome ---------------- */
  const uniforms = {
    uZenith: { value: new THREE.Color('#3e7ad1') },
    uMid: { value: new THREE.Color('#8fbce8') },
    uHorizon: { value: new THREE.Color(RENDER.fogColor) },
    uSunDir: { value: new THREE.Vector3(SUN_DIR.x, SUN_DIR.y, SUN_DIR.z).normalize() },
    uSunColor: { value: new THREE.Color('#fff4d6') },
    uTime: { value: 0 },
  };

  const domeMat = new THREE.ShaderMaterial({
    uniforms,
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vDir = position;
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_Position = projectionMatrix * mv;
      }`,
    fragmentShader: `
      varying vec3 vDir;
      uniform vec3 uZenith, uMid, uHorizon, uSunColor;
      uniform vec3 uSunDir;
      uniform float uTime;

      float hashc(vec2 p) {
        return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
      }
      float vnoise(vec2 p) {
        vec2 i = floor(p);
        vec2 f = fract(p);
        vec2 u = f * f * (3.0 - 2.0 * f);
        float a = hashc(i);
        float b = hashc(i + vec2(1.0, 0.0));
        float c = hashc(i + vec2(0.0, 1.0));
        float d = hashc(i + vec2(1.0, 1.0));
        return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
      }

      void main() {
        vec3 dir = normalize(vDir);
        float t = clamp(dir.y, 0.0, 1.0);
        vec3 sky = mix(uMid, uZenith, smoothstep(0.06, 0.6, t));
        sky = mix(uHorizon, sky, smoothstep(-0.02, 0.16, dir.y));

        // The sun: a hot core and a broad warm lobe.
        float s = max(0.0, dot(dir, uSunDir));
        sky += uSunColor * (pow(s, 900.0) * 1.4 + pow(s, 24.0) * 0.28 + pow(s, 3.0) * 0.10);

        // Cumulus: a ray/plane intersection into a two-octave noise field.
        if (dir.y > 0.02) {
          vec2 hit = dir.xz / (dir.y + 0.12);
          vec2 p = hit * 2.6 + vec2(uTime * 0.006, uTime * 0.0015);
          float n = vnoise(p) * 0.62 + vnoise(p * 2.7 + 11.3) * 0.38;
          float cloud = smoothstep(0.58, 0.78, n);
          // Flat bottoms: thin the deck near the horizon.
          cloud *= smoothstep(0.02, 0.12, dir.y);
          vec3 cloudCol = mix(vec3(0.86, 0.88, 0.92), vec3(1.02, 1.0, 0.98),
            0.5 + 0.5 * dot(dir, uSunDir));
          sky = mix(sky, cloudCol, cloud * 0.85);
        }

        gl_FragColor = vec4(sky, 1.0);
      }`,
  });
  const dome = new THREE.Mesh(new THREE.SphereGeometry(2200, 48, 28), domeMat);
  dome.renderOrder = 1;
  group.add(dome);

  /* ---------------- the distant ridges ---------------- */
  /* Two rings of skyline. Heights are a product of octaves — massifs times
     horns times knife edges — so there are cols with nothing in them and
     corners at the summits, not a sine wave. The far ring wears snow. */
  function ridgeRing(radius, height, baseY, segs, seed, color, snowLine) {
    const positions = [];
    const colors = [];
    const index = [];
    const col = new THREE.Color(color);
    const snow = new THREE.Color('#f2f5f7');
    const rock = new THREE.Color('#7c8894');
    for (let i = 0; i <= segs; i++) {
      const a = (i / segs) * Math.PI * 2;
      const massif = 0.35 + 0.65 * noise2(Math.cos(a) * 2.1 + 5, Math.sin(a) * 2.1, seed);
      const horns = 0.55 + 0.45 * noise2(Math.cos(a) * 7.3, Math.sin(a) * 7.3 + 3, seed + 1);
      const knife = 0.7 + 0.3 * noise2(Math.cos(a) * 21.0, Math.sin(a) * 21.0, seed + 2);
      const h = height * massif * horns * knife;
      const x = Math.cos(a) * radius;
      const z = Math.sin(a) * radius;
      positions.push(x, baseY, z, x, baseY + h, z);
      // Base takes the haze; the peak takes rock or snow.
      const peakCol = (snowLine && h > height * snowLine)
        ? snow : (h > height * 0.55 ? rock : col);
      colors.push(col.r, col.g, col.b, peakCol.r, peakCol.g, peakCol.b);
      if (i < segs) {
        const b = i * 2;
        index.push(b, b + 1, b + 2, b + 1, b + 3, b + 2);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    geo.setIndex(index);
    const mat = new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.DoubleSide, fog: false });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.renderOrder = 2;
    return mesh;
  }

  // Near ring: forested blue-green. Far ring: hazy, snow-capped.
  const farRidge = ridgeRing(1850, 760, -120, 140, 401, '#a8bccf', 0.68);
  const nearRidge = ridgeRing(1350, 470, -100, 120, 407, '#6c8598');
  group.add(farRidge);
  group.add(nearRidge);

  /* A haze skirt under everything, exactly the fog colour, hiding the
     terrain mesh's far edge and the ridges' bases. It reaches well below
     the horizon so no seam ever shows between ground and backdrop. */
  const skirt = new THREE.Mesh(
    new THREE.CylinderGeometry(2100, 2100, 900, 48, 1, true),
    new THREE.MeshBasicMaterial({ color: RENDER.fogColor, side: THREE.BackSide, fog: false }),
  );
  skirt.position.y = -520;
  skirt.renderOrder = 0;
  group.add(skirt);

  /* ---------------- the lamps ---------------- */
  /* Bright summer light that still leaves ACES headroom: at 1.15 the
     sun-facing meadow renders ~0.7, green and readable, instead of rolling
     off to white the way 2.6 did. */
  const sun = new THREE.DirectionalLight('#fff2dc', 1.15);
  sun.position.set(SUN_DIR.x * 300, SUN_DIR.y * 300, SUN_DIR.z * 300);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.near = 40;
  sun.shadow.camera.far = 620;
  const EXT = 78;
  sun.shadow.camera.left = -EXT;
  sun.shadow.camera.right = EXT;
  sun.shadow.camera.top = EXT;
  sun.shadow.camera.bottom = -EXT;
  sun.shadow.bias = -0.0004;
  sun.shadow.normalBias = 2 * (2 * EXT / 2048);
  sun.shadow.radius = 2.5;
  const sunTarget = new THREE.Object3D();
  sun.target = sunTarget;

  const hemi = new THREE.HemisphereLight('#b8d8f2', '#61804a', 0.55);

  /* Snap the shadow box to texel-sized steps along the light's own basis,
     so the map's sampling grid never crawls under a moving rider. */
  const texel = (2 * EXT) / 2048;
  const lightDir = new THREE.Vector3(SUN_DIR.x, SUN_DIR.y, SUN_DIR.z).normalize();
  const lRight = new THREE.Vector3().crossVectors(lightDir, new THREE.Vector3(0, 1, 0)).normalize();
  const lUp = new THREE.Vector3().crossVectors(lRight, lightDir).normalize();
  const snapScratch = new THREE.Vector3();

  function placeShadow(x, y, z) {
    // Project the anchor into the light basis, snap, and rebuild.
    snapScratch.set(x, y, z);
    const r = Math.round(snapScratch.dot(lRight) / texel) * texel;
    const u = Math.round(snapScratch.dot(lUp) / texel) * texel;
    const d = snapScratch.dot(lightDir);
    snapScratch.set(0, 0, 0)
      .addScaledVector(lRight, r)
      .addScaledVector(lUp, u)
      .addScaledVector(lightDir, d);
    sunTarget.position.copy(snapScratch);
    sun.position.copy(snapScratch).addScaledVector(lightDir, 300);
  }

  function update(pos, dt) {
    uniforms.uTime.value += dt;
    /* The whole backdrop rides with the rider — height included. The run
       descends forever, so anything pinned to world y=0 would climb out of
       the frame within a few hundred metres of descent. */
    group.position.set(pos.x, pos.y, pos.z);
    // Keep the shadow box a little ahead of the rider, where the eye is.
    placeShadow(pos.x, pos.y, pos.z - 26);
  }

  return { group, sun, sunTarget, hemi, update };
}

