async () => {
  const S = window.__sommer;
  const THREE_R = S.renderer;
  // Build a raycaster from the camera through several screen points.
  const cam = S.scene.children.find(c => c.isPerspectiveCamera) || S.scene.getObjectByProperty('isCamera', true);
  const results = {};
  const terr = S.scene.children.find(c => c.geometry && c.geometry.attributes && c.geometry.attributes.aSurf);
  // Use the camera from renderer info: find via scene traverse
  let camera = null;
  S.scene.traverse(o => { if (o.isPerspectiveCamera && !camera) camera = o; });
  const Ray = terr.geometry.constructor.name; // dummy
  // three is not global; use the raycaster via importing three from the importmap
  const T = await import('/assets/vendor/three/three.module.min.js');
  const rc = new T.Raycaster();
  for (const [name, ndc] of [['center', [0, 0]], ['down', [0, -0.6]], ['downLeft', [-0.5, -0.7]]]) {
    rc.setFromCamera(new T.Vector2(ndc[0], ndc[1]), camera);
    const hits = rc.intersectObjects(S.scene.children, false);
    results[name] = hits.slice(0, 2).map(h => ({
      type: h.object.type,
      isTerrain: h.object === terr,
      dist: +h.distance.toFixed(1),
      normal: h.face ? [+h.face.normal.x.toFixed(2), +h.face.normal.y.toFixed(2), +h.face.normal.z.toFixed(2)] : null,
    }));
  }
  // Also: is the terrain mesh's position sane vs rider?
  results.meshPos = { x: terr.position.x, z: terr.position.z };
  results.rider = { x: S.rider.pos.x, y: S.rider.pos.y, z: S.rider.pos.z };
  // Sample a vertex near the rider: find min distance vertex in the position attribute
  const pos = terr.geometry.attributes.position.array;
  const nrm = terr.geometry.attributes.normal.array;
  const col = terr.geometry.attributes.color.array;
  let bi = -1, bd = 1e9;
  const rx = S.rider.pos.x - terr.position.x, rz = S.rider.pos.z - terr.position.z;
  for (let i = 0; i < pos.length; i += 3) {
    const dx = pos[i] - rx, dz = pos[i + 2] - rz;
    const d2 = dx * dx + dz * dz;
    if (d2 < bd) { bd = d2; bi = i; }
  }
  results.nearVertex = {
    d: Math.sqrt(bd).toFixed(2),
    y: pos[bi + 1].toFixed(2),
    riderY: S.rider.pos.y.toFixed(2),
    normal: [nrm[bi], nrm[bi + 1], nrm[bi + 2]].map(v => +v.toFixed(2)),
    color: [col[bi], col[bi + 1], col[bi + 2]].map(v => +v.toFixed(2)),
  };
  return results;
}

