input.function:
async () => {
  const S = window.__sommer;
  let camera = null;
  S.scene.traverse(o => { if (o.isPerspectiveCamera && !camera) camera = o; });
  const terr = S.scene.children.find(c => c.geometry && c.geometry.attributes && c.geometry.attributes.aSurf);
  const T = await import('/assets/vendor/three/three.module.min.js');
  const gl = S.renderer.getContext();
  const W = gl.drawingBufferWidth, H = gl.drawingBufferHeight;
  const px = new Uint8Array(4);
  function shot(label) {
    S.renderer.render(S.scene, camera);
    // sample lower-center (near ground) and mid-center
    gl.readPixels(Math.floor(W/2), Math.floor(H*0.25), 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
    const near = [...px.slice(0,3)];
    gl.readPixels(Math.floor(W/2), Math.floor(H*0.45), 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
    const mid = [...px.slice(0,3)];
    return { label, near, mid };
  }
  const out = [];
  const sun = S.scene.children.find(c => c.isDirectionalLight);
  const hemi = S.scene.children.find(c => c.isHemisphereLight);
  out.push(shot('baseline'));
  const h0 = hemi.intensity; hemi.intensity = 0;
  out.push(shot('sun only'));
  hemi.intensity = h0;
  const s0 = sun.intensity; sun.intensity = 0;
  out.push(shot('hemi only'));
  sun.intensity = s0;
  const m0 = terr.material;
  terr.material = new T.MeshBasicMaterial({ vertexColors: true });
  out.push(shot('basic vertexcolor'));
  terr.material = m0;
  out.push(shot('restored'));
  return out;
}

