  terr.geometry.boundingSphere = null;
  terr.geometry.computeBoundingSphere();
  const rc = new T.Raycaster();
  rc.set(new T.Vector3(camera.position.x, camera.position.y, camera.position.z), new T.Vector3(0, -1, 0));
  const hits = rc.intersectObject(terr, false);
  const gl = S.renderer.getContext();
  const W = gl.drawingBufferWidth, H = gl.drawingBufferHeight;
  const px = new Uint8Array(4);
  const read = (x, y) => { gl.readPixels(Math.floor(W*x), Math.floor(H*y), 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px); return [...px.slice(0,3)]; };
  const out = {
    downHit: hits.length ? { y: +hits[0].point.y.toFixed(2), dist: +hits[0].distance.toFixed(2) } : 'MISS',
    camY: +camera.position.y.toFixed(2),
    bs: { r: Math.round(terr.geometry.boundingSphere.radius), cy: Math.round(terr.geometry.boundingSphere.center.y) },
