  terr.geometry.attributes.normal.needsUpdate = true;
  terr.geometry.attributes.color.needsUpdate = true;
  terr.geometry.attributes.aSurf.needsUpdate = true;
  S.renderer.render(S.scene, camera);
  out.afterReupload = read(0.5, 0.2);
  return out;
}');
```

