/* Imported models — Alpen's upgrader idea, summer edition.

   The prop pools boot with procedurally grown geometry and are playable on
   their own. This module then loads the Quaternius glTFs in the background,
   bakes each into ONE non-indexed geometry carrying the same attribute
   contract the growers emit (position / normal / color), normalises it to
   stand on the origin at a family-appropriate height, and hot-swaps it into
   `pool.mesh.geometry`. Instance matrices, casts and counts all live on the
   mesh, so nothing else notices. On error, the grown variant remains. */

import { GLTFLoader } from '../assets/vendor/GLTFLoader.js';

export function createModelUpgrader(THREE) {
  const loader = new GLTFLoader();

  /* Merge a glTF scene into one geometry, material colours baked into a
     color attribute. Returns { geometry, height } or null. */
  function bake(scene) {
    const parts = [];
    let total = 0;
    scene.updateMatrixWorld(true);
    scene.traverse((node) => {
      if (!node.isMesh || !node.geometry) return;
      let g = node.geometry.clone();
      if (g.index) g = g.toNonIndexed();
      g.applyMatrix4(node.matrixWorld);
      const n = g.attributes.position.count;
      const color = node.material && node.material.color
        ? node.material.color : { r: 0.6, g: 0.6, b: 0.6 };
      parts.push({ g, n, color });
      total += n;
    });
    if (!total) return null;

    const position = new Float32Array(total * 3);
    const normal = new Float32Array(total * 3);
    const color = new Float32Array(total * 3);
    let o = 0;
    for (const { g, n, color: c } of parts) {
      position.set(g.attributes.position.array, o * 3);
      if (g.attributes.normal) normal.set(g.attributes.normal.array, o * 3);
      for (let i = 0; i < n; i++) {
        color[(o + i) * 3] = c.r;
        color[(o + i) * 3 + 1] = c.g;
        color[(o + i) * 3 + 2] = c.b;
      }
      o += n;
      g.dispose();
    }
    const out = new THREE.BufferGeometry();
    out.setAttribute('position', new THREE.BufferAttribute(position, 3));
    out.setAttribute('normal', new THREE.BufferAttribute(normal, 3));
    out.setAttribute('color', new THREE.BufferAttribute(color, 3));

    // Ground it: feet on y = 0 (a whisper below, so nothing hovers),
    // centred in x/z.
    out.computeBoundingBox();
    const bb = out.boundingBox;
    const height = bb.max.y - bb.min.y;
    const cx = (bb.min.x + bb.max.x) / 2;
    const cz = (bb.min.z + bb.max.z) / 2;
    out.translate(-cx, -bb.min.y - height * 0.015, -cz);
    out.computeBoundingSphere();
    return { geometry: out, height };
  }

  /* Load `file` and swap it into `pool`, scaled so the model stands
     `targetHeight` tall at instance scale 1. */
  function upgrade(pool, file, targetHeight) {
    const url = new URL(`../assets/models/${file}.gltf`, import.meta.url).href;
    loader.load(url, (gltf) => {
      const baked = bake(gltf.scene);
      if (!baked) return;
      const s = targetHeight / Math.max(0.001, baked.height);
      baked.geometry.scale(s, s, s);
      pool.mesh.geometry.dispose();
      pool.mesh.geometry = baked.geometry;
    }, undefined, () => { /* the grown variant simply remains */ });
  }

  return { upgrade };
}

