input.content:
/* The mountain, in summer.

   There is no terrain data. `heightAt` is a pure function of a coordinate —
   the same architecture as Alpen next door — and everything reads the hill
   through it: the rider stands on it, trees are planted on it, and the mesh
   below is only ever a picture of it.

   The run is a narrow carved singletrack snaking inside a wider corridor,
   and the land changes character in blended ZONES: pine forest pressing in
   on the trail, mixed woods, wide flat flower meadows where the corridor
   opens right out, rocky ridge with real exposure, and bike-park windows
   whose bed grows rollers, tabletops and banked berms. The bed banks into
   its own turns everywhere — the berm tilt is the guide line's second
   derivative.

   THE ROUTE FORKS, Alpen's trick: every few hundred metres the line has a
   chance of splitting in two around an island and closing again below — a
   crossroads on the way in, a merge on the way out. The bed, corridor,
   dish and materials are all measured to the NEAREST branch, so the split
   costs one extra distance test and the geometry does the rest.

   The grade breathes past zero: short honest uphills a rider has to pedal,
   between chapters that fall away hard. Containment is Alpen's: past the
   corridor the valley sides rise, monotonically, forever. */

import { snoise2, noise2, hash2 } from './noise.js';
import { TERRAIN } from './config.js';

const { grade: GRADE, wander, trail, corridor, valley, route,
  ridges, rolls, bumps, chatter, warp, zones, park } = TERRAIN;

const TAU = Math.PI * 2;

const smoothstep = (a, b, t) => {
  const u = Math.min(1, Math.max(0, (t - a) / (b - a)));
  return u * u * (3 - 2 * u);
};
const smooth01 = (u) => u * u * (3 - 2 * u);

/* Value noise along a line — the zone dials vary down the run only. */
function noise1(u, seed) {
  const i = Math.floor(u);
  const f = u - i;
  const a = hash2(i, 0, seed);
  const b = hash2(i + 1, 0, seed);
  return a + (b - a) * smooth01(f);
}

/* ==========================================================================
   The route
   ========================================================================== */

export function wanderAt(z) {
  let x = 0;
  for (let i = 0; i < wander.length; i++) x += Math.sin(z * wander[i].freq) * wander[i].amp;
  return x;
}

/* Half the separation between the two branches; zero where the run is one
   trail. A fork opens and closes over the first and last third of its
   window, so from the saddle it is a crossroads that becomes an island. */
export function forkSplit(z) {
  const b = Math.floor(-z / route.period);
  if (b < 1) return 0;
  if (hash2(b, 7717, 41) > route.chance) return 0;
  const top = -(b * route.period) - (route.period - route.span) * hash2(b, 991, 42);
  const t = (top - z) / route.span;
  if (t <= 0 || t >= 1) return 0;
  const edge = 0.3;
  const k = t < edge ? t / edge : t > 1 - edge ? (1 - t) / edge : 1;
  return route.split * smooth01(k);
}

/* The swing every branch rides on — short-wave curves inside the valley. */
function swingAt(z) {
  return trail.swing.amp * snoise2(z * trail.swing.freq, 0, 71)
    + trail.swing.amp * 0.6 * Math.sin(z * trail.swing.freq * 2.7 + 1.3);
}

/* The main line — branch centre when whole, the LEFT branch when forked
   (restart and spawn always have a real trail under them). */
export function guideAt(z) {
  const s = forkSplit(z);
  return wanderAt(z) + swingAt(z) - s;
}

/* Both branch centres. out = [c0, c1]; c0 === c1 when the run is whole. */
export function branchesAt(z, out = [0, 0]) {
  const mid = wanderAt(z) + swingAt(z);
  const s = forkSplit(z);
  out[0] = mid - s;
  out[1] = mid + s;
  return out;
}

const bedScratch = [0, 0];

/* Distance to the nearest trail bed line. */
export function bedDistanceAt(x, z) {
  const c = branchesAt(z, bedScratch);
  const d0 = Math.abs(x - c[0]);
  const d1 = Math.abs(x - c[1]);
  return d0 < d1 ? d0 : d1;
}

/* The groomed corridor half-width — breathing on a sine, and thrown wide
   open across the meadows and parks, drawn in tight through the forest. */
export function corridorHalfAt(z) {
  const zn = zoneAt(z, corridorZoneScratch);
  const openness = 0.72 + 0.75 * (zn.meadow + zn.park * 0.7);
  return (corridor.half + corridor.vary * Math.sin(z * corridor.freq)) * openness;
}
const corridorZoneScratch = {};

/* The berm bank: the swing's curvature, clamped to a dug berm's slope. */
export function bermTiltAt(z) {
  const e = 4;
  const c = (swingAt(z - e) - 2 * swingAt(z) + swingAt(z + e)) / (e * e)
    + (wanderAt(z - e) - 2 * wanderAt(z) + wanderAt(z + e)) / (e * e);
  const t = c * trail.bermGain;
  return t < -trail.bermMax ? -trail.bermMax : t > trail.bermMax ? trail.bermMax : t;
}

export function gradeAt(z) {
  let g = GRADE.base;
  for (let i = 0; i < GRADE.waves.length; i++) {
    const w = GRADE.waves[i];
    g += w.amp * Math.sin(w.freq * z + w.phase);
  }
  return g;
}

/* ==========================================================================
   The zones
   ========================================================================== */

export function zoneAt(z, out = {}) {
  const forest = smoothstep(0.33, 0.60, noise1(z * zones.forestFreq, zones.seed));
  const stone = smoothstep(0.52, 0.78, noise1(z * zones.stoneFreq, zones.seed + 9));
  const mixDial = smoothstep(0.34, 0.66, noise1(z * zones.mixFreq, zones.seed + 17));

  let parkF = 0;
  const P = zones.park;
  const b = Math.floor(-z / P.period);
  if (b >= 1 && hash2(b, 701, 91) < P.chance) {
    const top = -(b * P.period) - (P.period - P.span) * hash2(b, 911, 92);
    const t = (top - z) / P.span;
    if (t > 0 && t < 1) {
      const edge = 0.2;
      const k = t < edge ? t / edge : t > 1 - edge ? (1 - t) / edge : 1;
      parkF = smooth01(k);
    }
  }

  const parkW = parkF * (1 - stone);
  const rocky = stone * (1 - parkF);
  const open = Math.max(0, 1 - parkW - rocky);
  const woods = forest * open;
  out.park = parkW;
  out.rocky = rocky;
  out.meadow = open - woods;
  out.pine = woods * (1 - mixDial);
  out.mixed = woods * mixDial;
  out.expSide = hash2(Math.floor(-z / 600), 313, 93) < 0.5 ? -1 : 1;
  return out;
}

/* ==========================================================================
   The bed's own profile along the run.
   ========================================================================== */

function bedBumpAt(z, parkF, rocky) {
  const s = -z;
  let h = 0.11 * Math.sin(s * (TAU / 19)) * (1 - rocky * 0.8);
  if (parkF > 0.01) {
    h += park.rollerAmp * parkF * (0.5 - 0.5 * Math.cos(s * (TAU / park.rollerWave)));
    const u = s % park.kickerEvery;
    const L = park.kickerLength;
    if (u < L) h += park.kickerHeight * parkF * smooth01(u / L);
    else if (u < L + 2) h += park.kickerHeight * parkF;
    else if (u < L + 2 + 7) h += park.kickerHeight * parkF * (1 - smooth01((u - L - 2) / 7));
  }
  return h;
}

/* ==========================================================================
   The height, as a row and a point on it
   ========================================================================== */

function makeContext() {
  return {
    z: NaN,
    base: 0, c0: 0, c1: 0, half: 0, tilt: 0, bedBump: 0,
    pine: 0, mixed: 0, meadow: 1, rocky: 0, park: 0, expSide: 1,
    ridgeAmp: 0, rollAmp: 0, bumpAmp: 0,
  };
}

const zoneScratch = {};
const rowBranchScratch = [0, 0];

function rowContext(z, ctx) {
  if (ctx.z === z) return ctx;
  ctx.z = z;

  let base = GRADE.base * z;
  for (let i = 0; i < GRADE.waves.length; i++) {
    const w = GRADE.waves[i];
    base -= (w.amp / w.freq) * (Math.cos(w.freq * z + w.phase) - Math.cos(w.phase));
  }
  ctx.base = base;

  const c = branchesAt(z, rowBranchScratch);
  ctx.c0 = c[0];
  ctx.c1 = c[1];
  ctx.half = corridorHalfAt(z);
  ctx.tilt = bermTiltAt(z);

  const zn = zoneAt(z, zoneScratch);
  ctx.pine = zn.pine;
  ctx.mixed = zn.mixed;
  ctx.meadow = zn.meadow;
  ctx.rocky = zn.rocky;
  ctx.park = zn.park;
  ctx.expSide = zn.expSide;

  ctx.bedBump = bedBumpAt(z, zn.park, zn.rocky);

  // What this chapter's ground is made of. Meadows lie flat; forests carry
  // roots and hummocks; ridges stand their bones up.
  ctx.ridgeAmp = ridges.amp * (0.55 + 1.15 * zn.rocky) * (1 - 0.5 * zn.meadow);
  ctx.rollAmp = rolls.amp * (1 - 0.55 * zn.meadow - 0.3 * zn.park);
  ctx.bumpAmp = bumps.amp * (0.6 + 1.0 * (zn.pine + zn.mixed) + 1.2 * zn.rocky
    - 0.45 * zn.meadow - 0.5 * zn.park);
  return ctx;
}

function heightIn(ctx, x, detail = 1) {
  const z = ctx.z;
  let h = ctx.base;

  // Nearest branch: the whole cross-section is measured from it.
  const d0 = Math.abs(x - ctx.c0);
  const d1 = Math.abs(x - ctx.c1);
  const nearFirst = d0 < d1;
  const cNear = nearFirst ? ctx.c0 : ctx.c1;
  const dxg = x - cNear;
  const adg = nearFirst ? d0 : d1;
  const trailF = 1 - smoothstep(trail.bed, trail.bed + trail.shoulder, adg);
  const off = 1 - trailF;

  if (off > 0.001) {
    const wx = x + snoise2(x * warp.freq, z * warp.freq, warp.seed) * warp.amp;
    const wz = z + snoise2(x * warp.freq, z * warp.freq, warp.seed + 1) * warp.amp;
    const ridgeX = x * 0.966 - z * 0.259;
    const ridgeZ = x * 0.259 + z * 0.966;
    const rollX = wx * 0.819 + wz * 0.574;
    const rollZ = -wx * 0.574 + wz * 0.819;
    h += snoise2(ridgeX * ridges.freq, ridgeZ * ridges.freq, ridges.seed) * ctx.ridgeAmp * off;
    h += snoise2(rollX * rolls.freq, rollZ * rolls.freq, rolls.seed) * ctx.rollAmp * off;
    if (detail > 0.001) {
      h += snoise2(wx * bumps.freq, wz * bumps.freq, bumps.seed) * ctx.bumpAmp * off * detail;
      h += snoise2(x * chatter.freq, z * chatter.freq, chatter.seed) * chatter.amp * off * detail;
      if (ctx.rocky > 0.02) {
        h += Math.abs(snoise2(x * 0.06, z * 0.045, 57)) * 1.9 * ctx.rocky * off;
      }
    }
  }

  // The corridor dish, measured to the nearest branch — between two open
  // branches this is what raises the island.
  const u = Math.min(1, adg / Math.max(1, ctx.half));
  h += corridor.bowl * u * u;

  // A shallower gather centred on the bed itself.
  const gd = Math.min(1, adg / 20);
  h += 1.2 * gd * gd * (1 - smoothstep(ctx.half - 2, ctx.half, adg));

  // The carved bed.
  if (trailF > 0.001) {
    const bedH = ctx.base + trail.crown + ctx.tilt * dxg + ctx.bedBump;
    h = h * off + bedH * trailF;
  }

  // Beyond the corridor: shoulder rise, then the flanks, forever upward.
  const past = adg - ctx.half;
  if (past > 0) {
    h += valley.rise * smooth01(Math.min(1, past / valley.band));
    const w = past - valley.band;
    if (w > 0) {
      const uu = w / valley.scale;
      h += valley.height * (1 - Math.exp(-uu * uu));
      h += valley.creep * (w - valley.creepEase * (1 - Math.exp(-w / valley.creepEase)));
      const arrive = smoothstep(4, 30, w);
      h += (Math.abs(snoise2(w * 0.035, z * 0.022, x < cNear ? 101 : 203)) * 11
        + snoise2(w * 0.08, z * 0.05, x < cNear ? 307 : 409) * 4.5) * arrive;
    }
  }

  // Rocky exposure: one side falls away into a ravine beside the trail.
  if (ctx.rocky > 0.03) {
    const dxe = dxg * ctx.expSide;
    if (dxe > trail.bed + trail.shoulder) {
      const E = zones.exposure;
      const e = smooth01(Math.min(1, (dxe - trail.bed - trail.shoulder) / E.reach));
      h -= E.drop * e * ctx.rocky;
    }
  }

  return h;
}

const scratch = makeContext();

export function heightAt(x, z) {
  return heightIn(rowContext(z, scratch), x);
}

const EPS = 0.35;

export function normalFrom(fn, x, z, out) {
  const dx = (fn(x + EPS, z) - fn(x - EPS, z)) / (2 * EPS);
  const dz = (fn(x, z + EPS) - fn(x, z - EPS)) / (2 * EPS);
  return out.set(-dx, 1, -dz).normalize();
}

/* ==========================================================================
   What the ground is made of — {grass, dirt, gravel, rock}, summing to one.
   ========================================================================== */

const surfMaterial = { grass: 0, dirt: 1, gravel: 0, rock: 0 };

export function surfaceAt(x, z) {
  const ctx = rowContext(z, scratch);
  const d0 = Math.abs(x - ctx.c0);
  const d1 = Math.abs(x - ctx.c1);
  const adg = d0 < d1 ? d0 : d1;
  const trailF = 1 - smoothstep(trail.bed, trail.bed + trail.shoulder, adg);

  const bedDirt = ctx.park * 1.0 + (ctx.pine + ctx.mixed) * 0.85 + ctx.meadow * 0.6 + ctx.rocky * 0.15;
  const bedGravel = ctx.rocky * 0.62 + (ctx.pine + ctx.mixed) * 0.15 + ctx.meadow * 0.12;
  const bedRock = ctx.rocky * 0.23;
  const bedGrass = Math.max(0, 1 - bedDirt - bedGravel - bedRock);

  const offGrass = ctx.meadow * 0.92 + ctx.mixed * 0.5 + ctx.pine * 0.25 + ctx.park * 0.75;
  const offDirt = ctx.pine * 0.6 + ctx.mixed * 0.4 + ctx.meadow * 0.08 + ctx.park * 0.25;
  const offGravel = ctx.rocky * 0.3;
  const offRock = Math.max(0, 1 - Math.min(1, offGrass + offDirt + offGravel));

  const g = trailF;
  surfMaterial.grass = bedGrass * g + offGrass * (1 - g);
  surfMaterial.dirt = bedDirt * g + offDirt * (1 - g);
  surfMaterial.gravel = bedGravel * g + offGravel * (1 - g);
  surfMaterial.rock = bedRock * g + offRock * (1 - g);
  return surfMaterial;
}

/* ==========================================================================
   The grid
   ========================================================================== */

function graded(step, growth, reach, uniformReach = 0) {
  const out = [0];
  let d = 0;
  let s = step;
  while (d < reach) {
    d += s;
    out.push(d);
    if (d >= uniformReach) s *= growth;
  }
  return out;
}

const half = graded(TERRAIN.spacing, TERRAIN.sideGrowth, TERRAIN.side, TERRAIN.uniformNear);
const xs = [];
for (let i = half.length - 1; i >= 1; i--) xs.push(-half[i]);
for (let i = 0; i < half.length; i++) xs.push(half[i]);

const bwd = graded(TERRAIN.spacing, TERRAIN.behindGrowth, TERRAIN.behind, TERRAIN.uniformNear);
const fwd = graded(TERRAIN.spacing, TERRAIN.aheadGrowth, TERRAIN.ahead, TERRAIN.uniformNear);
const zs = [];
for (let i = bwd.length - 1; i >= 1; i--) zs.push(bwd[i]);
for (let i = 0; i < fwd.length; i++) zs.push(-fwd[i]);

const vertsX = xs.length;
const vertsZ = zs.length;

const PALETTE = {
  grass: [0.60, 0.71, 0.37],
  meadowDry: [0.73, 0.70, 0.41],
  forestFloor: [0.50, 0.42, 0.31],
  dirt: [0.63, 0.53, 0.39],
  gravel: [0.66, 0.64, 0.58],
  rock: [0.55, 0.54, 0.52],
  rockWarm: [0.61, 0.56, 0.47],
  parkClay: [0.60, 0.45, 0.32],
};

export function createTerrain(THREE, maxAnisotropy = 1) {
  const spacing = TERRAIN.spacing;
  const cols = vertsX - 1;
  const rows = vertsZ - 1;
  const count = vertsX * vertsZ;

  const positions = new Float32Array(count * 3);
  const normals = new Float32Array(count * 3);
  const colors = new Float32Array(count * 3);
  const surface = new Float32Array(count * 4);

  const buildPositions = new Float32Array(count * 3);
  const buildNormals = new Float32Array(count * 3);
  const buildColors = new Float32Array(count * 3);
  const buildSurface = new Float32Array(count * 4);

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute('normal', new THREE.BufferAttribute(normals, 3));
  geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geometry.setAttribute('aSurf', new THREE.BufferAttribute(surface, 4));

  const index = new Uint32Array(cols * rows * 6);
  let o = 0;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const a = r * vertsX + c;
      const b = a + 1;
      const cIx = a + vertsX;
      const dIx = cIx + 1;
      /* Alternate the diagonal so the lattice has no drift direction.
         MIND THE WINDING: rows run in DECREASING z, so the usual
         increasing-z order would wind every face downward — a ground that
         backface culling deletes the moment you look at it. */
      if ((r + c) & 1) {
        index[o++] = a; index[o++] = b; index[o++] = cIx;
        index[o++] = b; index[o++] = dIx; index[o++] = cIx;
      } else {
        index[o++] = a; index[o++] = dIx; index[o++] = cIx;
        index[o++] = a; index[o++] = b; index[o++] = dIx;
      }
    }
  }
  geometry.setIndex(new THREE.BufferAttribute(index, 1));

  const texLoader = new THREE.TextureLoader();
  const neutral = new THREE.DataTexture(new Uint8Array([150, 150, 150, 255]), 1, 1, THREE.RGBAFormat);
  neutral.needsUpdate = true;

  /* Cloud shadows: three octaves of periodic value noise, baked once into
     a small texture every lit metre of the world shares. */
  const CLOUD_N = 128;
  const cloudData = new Uint8Array(CLOUD_N * CLOUD_N);
  for (let y = 0; y < CLOUD_N; y++) {
    for (let x = 0; x < CLOUD_N; x++) {
      let v = 0;
      let amp = 0.6;
      for (let oct = 1; oct <= 3; oct++) {
        const f = oct * 3;
        // Sample on a torus so the tile wraps seamlessly.
        const a = (x / CLOUD_N) * TAU;
        const b = (y / CLOUD_N) * TAU;
        v += noise2(Math.cos(a) * f + 7 * oct, Math.sin(b) * f + 13 * oct, 211 + oct) * amp;
        amp *= 0.55;
      }
      const shade = 1 - 0.30 * smoothstep(0.52, 0.78, v);
      cloudData[y * CLOUD_N + x] = Math.round(shade * 255);
    }
  }
  const cloudTex = new THREE.DataTexture(cloudData, CLOUD_N, CLOUD_N, THREE.RedFormat);
  cloudTex.wrapS = cloudTex.wrapT = THREE.RepeatWrapping;
  cloudTex.magFilter = THREE.LinearFilter;
  cloudTex.minFilter = THREE.LinearFilter;
  cloudTex.needsUpdate = true;

  const texUniforms = {
    tGrass: { value: neutral },
    tFloor: { value: neutral },
    tDirt: { value: neutral },
    tGravel: { value: neutral },
    tCloud: { value: cloudTex },
    uCloudOff: { value: new THREE.Vector2(0, 0) },
    uAnchor: { value: new THREE.Vector2(0, 0) },
  };
  let surfacesLoaded = 0;
  let settle = () => {};
  const surfacesReady = new Promise((resolve) => { settle = resolve; });
  function loadSurface(file, uniform) {
    texLoader.load(
      new URL(`../assets/textures/ground/${file}`, import.meta.url).href,
      (t) => {
        t.wrapS = t.wrapT = THREE.RepeatWrapping;
        t.colorSpace = THREE.SRGBColorSpace;
        t.anisotropy = maxAnisotropy;
        uniform.value = t;
        if (++surfacesLoaded >= 4) settle();
      },
      undefined,
      () => { if (++surfacesLoaded >= 4) settle(); },
    );
  }
  loadSurface('meadow-grass.jpg', texUniforms.tGrass);
  loadSurface('forest-floor.jpg', texUniforms.tFloor);
  loadSurface('dirt-road.jpg', texUniforms.tDirt);
  loadSurface('gravel.jpg', texUniforms.tGravel);

  const material = new THREE.MeshLambertMaterial({ vertexColors: true });
  material.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, texUniforms);
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>
        attribute vec4 aSurf;
        varying vec4 vSurf;
        varying vec2 vWorldXZ;
        uniform vec2 uAnchor;`)
      .replace('#include <begin_vertex>', `#include <begin_vertex>
        vSurf = aSurf;
        vWorldXZ = position.xz + uAnchor;`);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>
        varying vec4 vSurf;
        varying vec2 vWorldXZ;
        uniform sampler2D tGrass, tFloor, tDirt, tGravel, tCloud;
        uniform vec2 uCloudOff;`)
      .replace('#include <color_fragment>', `#include <color_fragment>
        {
          vec2 uvA = vWorldXZ / 3.1;
          vec2 uvB = vWorldXZ / 13.7;
          vec3 g = mix(texture2D(tGrass, uvA).rgb, texture2D(tGrass, uvB).rgb, 0.42);
          vec3 d = mix(texture2D(tDirt, uvA).rgb, texture2D(tDirt, uvB).rgb, 0.42);
          vec3 v = mix(texture2D(tGravel, uvA).rgb, texture2D(tGravel, uvB).rgb, 0.42);
          vec3 f = mix(texture2D(tFloor, uvA).rgb, texture2D(tFloor, uvB).rgb, 0.42);
          float wSum = max(0.001, vSurf.x + vSurf.y + vSurf.z + vSurf.w);
          vec3 tex = (g * vSurf.x + d * vSurf.y + v * vSurf.z + f * vSurf.w) / wSum;
          diffuseColor.rgb *= tex * 2.05;
          // Cloud shadows drifting over the open ground.
          float cs = texture2D(tCloud, vWorldXZ * 0.0011 + uCloudOff).r;
          diffuseColor.rgb *= cs;
        }`);
  };
  material.customProgramCacheKey = () => 'sommer-terrain';

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  mesh.receiveShadow = true;

  let anchorX = 0;
  let anchorZ = 0;
  const ctx = makeContext();
  const STRIDE = 8 * spacing;

  function fillRows(ax, az, rowFrom, rowTo, P, N, C, S) {
    for (let r = rowFrom; r < rowTo; r++) {
      const wz = az + zs[r];
      rowContext(wz, ctx);
      const farRow = Math.abs(zs[r]) > 220;
      const detail = farRow ? 0 : 1;
      const prevRow = r > 0 ? (r - 1) * vertsX : -1;
      const dzRow = r > 0 ? zs[r] - zs[r - 1] : -1;
      for (let c = 0; c < vertsX; c++) {
        const wx = ax + xs[c];
        const i = r * vertsX + c;
        const h = heightIn(ctx, wx, detail);
        P[i * 3] = xs[c];
        P[i * 3 + 1] = h;
        P[i * 3 + 2] = zs[r];

        const dhx = (heightIn(ctx, wx + EPS, detail) - heightIn(ctx, wx - EPS, detail)) / (2 * EPS);
        const dhz = prevRow >= 0
          ? (h - P[(prevRow + c) * 3 + 1]) / dzRow
          : gradeAt(wz);
        let nx = -dhx;
        let nz = -dhz;
        const nl = 1 / Math.hypot(nx, 1, nz);
        N[i * 3] = nx * nl;
        N[i * 3 + 1] = nl;
        N[i * 3 + 2] = nz * nl;

        const m = surfaceAt(wx, wz);
        const slope = Math.hypot(dhx, dhz);
        const steepRock = smoothstep(0.55, 1.1, slope);
        const canopy = ctx.pine + ctx.mixed;
        const dg0 = Math.abs(wx - ctx.c0);
        const dg1 = Math.abs(wx - ctx.c1);
        const adg = dg0 < dg1 ? dg0 : dg1;
        const trailF = 1 - smoothstep(trail.bed, trail.bed + trail.shoulder, adg);
        const floorW = m.dirt * (1 - trailF) * Math.min(1, canopy * 1.5);
        let grass = m.grass * (1 - steepRock);
        let dirt = (m.dirt - floorW) * (1 - steepRock * 0.7);
        let gravelRock = m.gravel + m.rock + steepRock * (m.grass + m.dirt * 0.7);
        S[i * 4] = grass;
        S[i * 4 + 1] = dirt;
        S[i * 4 + 2] = gravelRock;
        S[i * 4 + 3] = floorW;

        const dry = noise2(wx * 0.012, wz * 0.012, 131);
        let r0 = PALETTE.grass[0] + (PALETTE.meadowDry[0] - PALETTE.grass[0]) * dry;
        let g0 = PALETTE.grass[1] + (PALETTE.meadowDry[1] - PALETTE.grass[1]) * dry;
        let b0 = PALETTE.grass[2] + (PALETTE.meadowDry[2] - PALETTE.grass[2]) * dry;
        const rockT = (ctx.rocky > 0.4 || steepRock > 0.5) ? PALETTE.rock : PALETTE.rockWarm;
        const wSum = Math.max(0.001, grass + dirt + gravelRock + floorW);
        let cr = (r0 * grass + PALETTE.dirt[0] * dirt + rockT[0] * gravelRock + PALETTE.forestFloor[0] * floorW) / wSum;
        let cg = (g0 * grass + PALETTE.dirt[1] * dirt + rockT[1] * gravelRock + PALETTE.forestFloor[1] * floorW) / wSum;
        let cb = (b0 * grass + PALETTE.dirt[2] * dirt + rockT[2] * gravelRock + PALETTE.forestFloor[2] * floorW) / wSum;
        if (ctx.park > 0.02 && trailF > 0.3) {
          const p = ctx.park * trailF * 0.7;
          cr = cr * (1 - p) + PALETTE.parkClay[0] * p;
          cg = cg * (1 - p) + PALETTE.parkClay[1] * p;
          cb = cb * (1 - p) + PALETTE.parkClay[2] * p;
        }
        /* Trail wear: two wheel ruts and a darker rim where the bed meets
           the verge — the small print that makes a track read as ridden. */
        let wear = 1;
        if (trailF > 0.05) {
          const rut = Math.abs(adg - 0.55);
          wear -= 0.10 * trailF * (1 - smoothstep(0.10, 0.42, rut));
          wear -= 0.08 * smoothstep(trail.bed - 0.7, trail.bed, adg) * trailF;
        }
        const vary = (0.90 + 0.18 * noise2(wx * 0.11, wz * 0.11, 137)) * wear;
        C[i * 3] = cr * vary;
        C[i * 3 + 1] = cg * vary;
        C[i * 3 + 2] = cb * vary;
      }
    }
  }

  function markUpdated() {
    geometry.attributes.position.needsUpdate = true;
    geometry.attributes.normal.needsUpdate = true;
    geometry.attributes.color.needsUpdate = true;
    geometry.attributes.aSurf.needsUpdate = true;
  }

  let build = null;
  const ROWS_PER_FRAME = 22;

  function beginBuild(ax, az) {
    build = { ax, az, row: 0 };
  }

  function advanceBuild() {
    if (!build) return;
    const rowTo = Math.min(vertsZ, build.row + ROWS_PER_FRAME);
    fillRows(build.ax, build.az, build.row, rowTo,
      buildPositions, buildNormals, buildColors, buildSurface);
    build.row = rowTo;
    if (build.row >= vertsZ) {
      anchorX = build.ax;
      anchorZ = build.az;
      positions.set(buildPositions);
      normals.set(buildNormals);
      colors.set(buildColors);
      surface.set(buildSurface);
      markUpdated();
      mesh.position.set(anchorX, 0, anchorZ);
      texUniforms.uAnchor.value.set(anchorX, anchorZ);
      build = null;
    }
  }

  function update(x, z, dt = 1 / 60) {
    // The cloud deck drifts on the same wind the dome's clouds ride.
    texUniforms.uCloudOff.value.x += dt * 0.0022;
    texUniforms.uCloudOff.value.y += dt * 0.0006;
    if (build) {
      advanceBuild();
      return;
    }
    const ax = Math.round(x / STRIDE) * STRIDE;
    const az = Math.round(z / STRIDE) * STRIDE;
    if (ax !== anchorX || az !== anchorZ) beginBuild(ax, az);
  }

  function reset(x, z) {
    build = null;
    anchorX = Math.round(x / STRIDE) * STRIDE;
    anchorZ = Math.round(z / STRIDE) * STRIDE;
    fillRows(anchorX, anchorZ, 0, vertsZ, positions, normals, colors, surface);
    markUpdated();
    geometry.computeBoundingSphere();
    mesh.position.set(anchorX, 0, anchorZ);
    texUniforms.uAnchor.value.set(anchorX, anchorZ);
  }

  return { mesh, update, reset, surfacesReady };
}

