const branchScratch = [0, 0];
const BED_EDGE = TERRAIN.trail.bed + TERRAIN.trail.shoulder * 0.6;

function placeBand(b) {
  const bandZ = -(b * BAND);   // top edge (least negative z) of the band
  const rnd = stream(Math.imul(b, 2654435761) | 0);
  const zn = zoneAt(bandZ - BAND * 0.5, zoneScratch);
  const forestness = zn.pine + zn.mixed;

  /* Trees. In the woods they crowd right up to the shoulder — the trail
     becomes a tunnel — while the meadow keeps a scatter of far ones.
     Everything measures from a randomly chosen branch, so a forked run
     grows trees on its island too; the bed check keeps every trunk off
     both lines. */
  const woodDensity = (zn.pine * 1.0 + zn.mixed * 0.95 + zn.meadow * 0.13
    + zn.rocky * 0.22 + zn.park * 0.1) * (1 + 0.6 * forestness);
  for (let i = 0; i < PROPS.treesPerBand; i++) {
    const z = bandZ - rnd() * BAND;
    const roll = rnd();
    const side = rnd() < 0.5 ? -1 : 1;
    const spread = rnd();
    const stand = noise2(z * 0.005, side * 7.7, 61);   // clumps
    if (roll > woodDensity * (0.45 + 0.8 * stand)) continue;

    const c = branchesAt(z, branchScratch);
    const cx = c[rnd() < 0.5 ? 0 : 1];
    const half = corridorHalfAt(z);
    // Forest hugs the trail; open country stands back.
    const verge = 0.7 + (1 - forestness) * 3.2;
    const hug = 1.15 + forestness * 0.9;
    const off = BED_EDGE + verge + Math.pow(spread, hug) * (half + 24 - BED_EDGE);
    const x = cx + side * off;
    if (bedDistanceAt(x, z) < BED_EDGE + 0.6) continue;
    const y = heightAt(x, z);
    normalFrom(heightAt, x, z, nScratch);
    if (nScratch.y < 0.72) continue;   // too steep even for a stubborn spruce

    // Species by chapter.
    const pick = rnd();
    let pool;
    if (zn.rocky > 0.5) pool = krummPools[Math.floor(rnd() * krummPools.length)];
    else if (zn.mixed > zn.pine && pick < 0.5) pool = birchPools[Math.floor(rnd() * birchPools.length)];
    else if (pick < 0.28) pool = pinePools[Math.floor(rnd() * pinePools.length)];
    else pool = sprucePools[Math.floor(rnd() * sprucePools.length)];

    const s = 0.75 + Math.pow(rnd(), 1.3) * 0.9;
    pool.add(x, y - 0.15, z, rnd() * Math.PI * 2, s, s * (0.9 + rnd() * 0.25), s, 0.85 + rnd() * 0.3);
    const r = pool.meta.trunkR * s + 0.12;
    solids.push({ x, z, r, hard: true });
  }

  /* Bushes — thickest where forest meets meadow. */
  const bushDensity = zn.mixed * 0.8 + zn.meadow * 0.55 + zn.pine * 0.4 + zn.park * 0.25;
  for (let i = 0; i < PROPS.bushesPerBand; i++) {
    const z = bandZ - rnd() * BAND;
    if (rnd() > bushDensity) continue;
    const c = branchesAt(z, branchScratch);
    const cx = c[rnd() < 0.5 ? 0 : 1];
    const half = corridorHalfAt(z);
    const side = rnd() < 0.5 ? -1 : 1;
    const x = cx + side * (BED_EDGE + 0.4 + Math.pow(rnd(), 1.3) * (half - BED_EDGE));
    if (bedDistanceAt(x, z) < BED_EDGE) continue;
    const y = heightAt(x, z);
    const pool = bushPools[Math.floor(rnd() * bushPools.length)];
    const s = 0.6 + rnd() * 0.9;
    pool.add(x, y - 0.05, z, rnd() * Math.PI * 2, s, s, s, 0.85 + rnd() * 0.3);
    solids.push({ x, z, r: pool.meta.trunkR * s, hard: false });
  }

  /* Boulders — the ridge's furniture, everyone else's accent. */
  const rockDensity = zn.rocky * 1.0 + zn.pine * 0.2 + zn.mixed * 0.17 + zn.meadow * 0.12;
  for (let i = 0; i < PROPS.rocksPerBand; i++) {
    const z = bandZ - rnd() * BAND;
    if (rnd() > rockDensity) continue;
    const c = branchesAt(z, branchScratch);
    const cx = c[rnd() < 0.5 ? 0 : 1];
    const half = corridorHalfAt(z);
    const side = rnd() < 0.5 ? -1 : 1;
    const x = cx + side * (BED_EDGE + VERGE + rnd() * (half + 12 - BED_EDGE));
    if (bedDistanceAt(x, z) < BED_EDGE + 0.4) continue;
    const y = heightAt(x, z);
    const pool = boulderPools[Math.floor(rnd() * boulderPools.length)];
    const s = 0.5 + Math.pow(rnd(), 1.6) * 2.4;
    pool.add(x, y - s * 0.18, z, rnd() * Math.PI * 2, s, s, s, 0.9 + rnd() * 0.25);
    solids.push({ x, z, r: 0.85 * s, hard: true });
  }

  /* Logs and stumps, in the woods. */
  if (forestness > 0.4) {
    const n = 1 + Math.floor(rnd() * 2);
    for (let i = 0; i < n; i++) {
      const z = bandZ - rnd() * BAND;
      const c = branchesAt(z, branchScratch);
      const cx = c[rnd() < 0.5 ? 0 : 1];
      const side = rnd() < 0.5 ? -1 : 1;
      const x = cx + side * (BED_EDGE + 1.2 + rnd() * 12);
      if (bedDistanceAt(x, z) < BED_EDGE) continue;
      const y = heightAt(x, z);
      const pool = logPools[Math.floor(rnd() * logPools.length)];
      const s = 0.8 + rnd() * 0.6;
      pool.add(x, y - 0.03, z, rnd() * Math.PI * 2, s, s, s, 0.9 + rnd() * 0.2);
      solids.push({ x, z, r: pool.meta.trunkR * s, hard: false });
    }
  }

  /* Grass tufts everywhere green; flower drifts owning the meadows. */
  const floraDensity = zn.meadow * 1.0 + zn.mixed * 0.7 + zn.park * 0.7 + zn.pine * 0.3;
  const floraReach = 4 + zn.meadow * 22 + zn.park * 8;
  for (let i = 0; i < PROPS.tuftsPerBand; i++) {
    const z = bandZ - rnd() * BAND;
    if (rnd() > floraDensity) continue;
    const c = branchesAt(z, branchScratch);
    const cx = c[rnd() < 0.5 ? 0 : 1];
    const side = rnd() < 0.5 ? -1 : 1;
    const x = cx + side * (TERRAIN.trail.bed + 0.3 + Math.pow(rnd(), 1.6) * floraReach);
    const y = heightAt(x, z);
    const pool = tuftPools[Math.floor(rnd() * tuftPools.length)];
    const s = 0.7 + rnd() * 0.8;
    pool.add(x, y, z, rnd() * Math.PI * 2, s, s, s, 0.8 + rnd() * 0.45);
  }
  const flowerDensity = Math.min(1, zn.meadow * 1.25 + zn.mixed * 0.4);
  for (let i = 0; i < PROPS.flowersPerBand; i++) {
    const z = bandZ - rnd() * BAND;
    if (rnd() > flowerDensity) continue;
    const c = branchesAt(z, branchScratch);
    const cx = c[rnd() < 0.5 ? 0 : 1];
    const side = rnd() < 0.5 ? -1 : 1;
    // Drifts: flowers clump on their own noise, not uniformly.
    const drift = noise2(z * 0.02, side * 3.3, 67);
    if (rnd() > 0.3 + drift * 0.9) continue;
    const x = cx + side * (TERRAIN.trail.bed + 0.5 + Math.pow(rnd(), 1.3) * floraReach);
    const y = heightAt(x, z);
    const pool = flowerPools[Math.floor(rnd() * flowerPools.length)];
    const tint = [1.0, 0.95, 0.7, 0.85][Math.floor(rnd() * 4)];
    const s = 0.8 + rnd() * 0.6;
    pool.add(x, y, z, rnd() * Math.PI * 2, s, s, s, tint);
  }

  /* Puddles on the dirt through the woods and parks. */
  if (forestness + zn.park > 0.5) {
    const n = Math.floor(rnd() * 3);
    for (let i = 0; i < n; i++) {
      const z = bandZ - rnd() * BAND;
      const c = branchesAt(z, branchScratch);
      const cx = c[rnd() < 0.5 ? 0 : 1];
      const x = cx + (rnd() - 0.5) * TERRAIN.trail.bed * 1.3;
      const y = heightAt(x, z);
      puddlePool.add(x, y + 0.03, z, rnd() * Math.PI,
        0.5 + rnd() * 1.1, 1, 0.3 + rnd() * 0.6, 0.9 + rnd() * 0.2);
    }
  }

  /* A trail marker at the top of each band, alternating sides. */
  if (b % 2 === 0) {
    const z = bandZ - 2;
    const gx = guideAt(z);
    const side = (b % 4 === 0) ? 1 : -1;
    const x = gx + side * (TERRAIN.trail.bed + 1.2);
    markerPool.add(x, heightAt(x, z), z, side > 0 ? -0.4 : 0.4 + Math.PI, 1, 1, 1, 1);
  }
}

