/* The mountain, in summer.

   There is no terrain data. `heightAt` is a pure function of a coordinate —
   Alpen's architecture next door — and everything reads the hill through
   it: the rider stands on it, trees are planted on it, and the mesh below
   is only ever a picture of it.

   THE TRAIL NETWORK. This mountain is not one line down a corridor, it is
   three: a singletrack that snakes and berms, a braided second trail that
   drifts across the valley and crosses or merges with the first, and a
   wide gravel service road that comes and goes on its own windows. Each is
   a pure function of z with its own bed width and surface, each is live
   only inside its own hashed windows, and the cross-section is measured to
   whichever is NEAREST — so junctions, crossings, parallel runs and
   islands all fall out of the geometry instead of being authored. Where
   two beds overlap, the ground is simply flat over both: a plaza.

   THE ENVIRONMENTS. Six blended weights change what the ground is made of
   and what stands on it: pine forest pressing right up to the bars, mixed
   birch woods, wide flat flower meadows where the corridor opens out,
   rocky ridge with a real drop on one side, open alpine highland above the
   treeline, and bike-park windows whose bed grows rollers and tabletops.

   Ponds sit in hollows the height field itself digs. The grade breathes
   past zero, so there are honest uphills to pedal. And containment is
   Alpen's: past the corridor the valley sides rise, monotonically, for
   ever — gravity always points home. */

import { snoise2, noise2, hash2 } from './noise.js';
import { TERRAIN } from './config.js';

const { grade: GRADE, wander, trail, corridor, valley, braid, road,
  ridges, rolls, bumps, chatter, warp, zones, park, ponds } = TERRAIN;

const TAU = Math.PI * 2;

const smoothstep = (a, b, t) => {
  const u = Math.min(1, Math.max(0, (t - a) / (b - a)));
  return u * u * (3 - 2 * u);
};
const smooth01 = (u) => u * u * (3 - 2 * u);

function noise1(u, seed) {
  const i = Math.floor(u);
  const f = u - i;
  const a = hash2(i, 0, seed);
  const b = hash2(i + 1, 0, seed);
  return a + (b - a) * smooth01(f);
}

/* A hashed window system: every `period` metres of hill, a `chance` of a
   feature `span` long, opening and closing over its first and last fifth.
   Everything episodic on this mountain — forks, parks, ponds, the road —
   is one of these, so nothing ever snaps into existence. */
function windowAt(z, period, chance, span, salt, edge = 0.2) {
  const b = Math.floor(-z / period);
  if (b < 1) return 0;
  if (hash2(b, salt, 41) > chance) return 0;
  const top = -(b * period) - (period - span) * hash2(b, salt + 7, 42);
  const t = (top - z) / span;
  if (t <= 0 || t >= 1) return 0;
  const k = t < edge ? t / edge : t > 1 - edge ? (1 - t) / edge : 1;
  return smooth01(k);
}

/* ==========================================================================
   The route
   ========================================================================== */

/* The valley's own line — the long geography everything else hangs off. */
export function wanderAt(z) {
  let x = 0;
  for (let i = 0; i < wander.length; i++) x += Math.sin(z * wander[i].freq) * wander[i].amp;
  return x;
}

/* The singletrack's own swing inside that valley: this is most of the
   steering the mountain asks for, and the berms are dug where it turns. */
function swingAt(z) {
  return trail.swing.amp * snoise2(z * trail.swing.freq, 0, 71)
    + trail.swing.amp * 0.6 * Math.sin(z * trail.swing.freq * 2.7 + 1.3);
}

/* The base grade's analytic integral — metres of height at this z. Pulled
   out because the ponds need to know the ground plane at a coordinate they
   are not standing on, and calling `heightAt` there would recurse. */
export function baseAt(z) {
  let base = GRADE.base * z;
  for (let i = 0; i < GRADE.waves.length; i++) {
    const w = GRADE.waves[i];
    base -= (w.amp / w.freq) * (Math.cos(w.freq * z + w.phase) - Math.cos(w.phase));
  }
  return base;
}

export function gradeAt(z) {
  let g = GRADE.base;
  for (let i = 0; i < GRADE.waves.length; i++) {
    const w = GRADE.waves[i];
    g += w.amp * Math.sin(w.freq * z + w.phase);
  }
  return g;
}

/* ==========================================================================
   The trails
   ========================================================================== */

export const KIND_TRAIL = 0;
export const KIND_BRAID = 1;
export const KIND_ROAD = 2;

/* Every live trail line at this z. Fills `out` with {x, bed, shoulder,
   kind, live} records and returns how many are live.

   The braid is the interesting one: its offset from the main line is a
   slow noise that changes sign, so within one window the second trail
   swings out across the meadow, comes back, CROSSES the main line, and
   leaves again. Crossings and merges are not authored anywhere — they are
   what a sign change of that offset looks like on the ground. */
const trailScratch = [
  { x: 0, bed: 0, shoulder: 0, kind: 0, live: 0 },
  { x: 0, bed: 0, shoulder: 0, kind: 0, live: 0 },
  { x: 0, bed: 0, shoulder: 0, kind: 0, live: 0 },
];

export function trailsAt(z, out = trailScratch) {
  const mainX = wanderAt(z) + swingAt(z);

  out[0].x = mainX;
  out[0].bed = trail.bed;
  out[0].shoulder = trail.shoulder;
  out[0].kind = KIND_TRAIL;
  out[0].live = 1;
  let n = 1;

  // The braided second trail.
  const braidLive = windowAt(z, braid.period, braid.chance, braid.span, 7717, 0.28);
  if (braidLive > 0.001) {
    const off = braid.spread * snoise2(z * braid.freq, 3.1, 311)
      + braid.spread * 0.55 * Math.sin(z * braid.freq * 2.3 + 0.7);
    out[n].x = mainX + off * braidLive;
    out[n].bed = trail.bed * 0.82;
    out[n].shoulder = trail.shoulder * 0.9;
    out[n].kind = KIND_BRAID;
    out[n].live = braidLive;
    n += 1;
  }

  // The gravel service road: wider, straighter, no berms.
  const roadLive = windowAt(z, road.period, road.chance, road.span, 5501, 0.25);
  if (roadLive > 0.001) {
    const side = hash2(Math.floor(-z / road.period), 2287, 43) < 0.5 ? -1 : 1;
    const off = side * (road.offset + road.sway * Math.sin(z * road.freq));
    out[n].x = mainX + off;
    out[n].bed = road.bed;
    out[n].shoulder = road.shoulder;
    out[n].kind = KIND_ROAD;
    out[n].live = roadLive;
    n += 1;
  }

  return n;
}

/* The line the game spawns and steers on: always the main singletrack. */
export function guideAt(z) {
  return wanderAt(z) + swingAt(z);
}

/* Distance to the nearest bed centre of any live trail. */
const bedScratch = [
  { x: 0, bed: 0, shoulder: 0, kind: 0, live: 0 },
  { x: 0, bed: 0, shoulder: 0, kind: 0, live: 0 },
  { x: 0, bed: 0, shoulder: 0, kind: 0, live: 0 },
];

export function bedDistanceAt(x, z) {
  const n = trailsAt(z, bedScratch);
  let best = Infinity;
  for (let i = 0; i < n; i++) {
    const d = Math.abs(x - bedScratch[i].x) - (bedScratch[i].bed - trail.bed);
    if (d < best) best = d;
  }
  return best;
}

/* The corridor: wide open across meadow and highland, drawn in tight
   through the forest, and always wide enough to hold every live trail. */
const corridorZoneScratch = {};
const corridorTrailScratch = [
  { x: 0, bed: 0, shoulder: 0, kind: 0, live: 0 },
  { x: 0, bed: 0, shoulder: 0, kind: 0, live: 0 },
  { x: 0, bed: 0, shoulder: 0, kind: 0, live: 0 },
];

export function corridorHalfAt(z) {
  const zn = zoneAt(z, corridorZoneScratch);
  const openness = 0.70 + 0.85 * (zn.meadow + zn.alpine * 0.9 + zn.park * 0.7);
  let half = (corridor.half + corridor.vary * Math.sin(z * corridor.freq)) * openness;
  // Never fence a trail out of its own corridor.
  const n = trailsAt(z, corridorTrailScratch);
  const mainX = corridorTrailScratch[0].x;
  for (let i = 1; i < n; i++) {
    const need = Math.abs(corridorTrailScratch[i].x - mainX)
      + corridorTrailScratch[i].bed + corridorTrailScratch[i].shoulder + 6;
    if (need > half) half = need;
  }
  return half;
}

/* The berm bank: the main line's curvature, clamped to a dug berm. */
export function bermTiltAt(z) {
  const e = 4;
  const c = (guideAt(z - e) - 2 * guideAt(z) + guideAt(z + e)) / (e * e);
  const t = c * trail.bermGain;
  return t < -trail.bermMax ? -trail.bermMax : t > trail.bermMax ? trail.bermMax : t;
}

/* ==========================================================================
   The environments
   ========================================================================== */

export function zoneAt(z, out = {}) {
  const forest = smoothstep(0.33, 0.60, noise1(z * zones.forestFreq, zones.seed));
  const stone = smoothstep(0.52, 0.78, noise1(z * zones.stoneFreq, zones.seed + 9));
  const high = smoothstep(0.58, 0.82, noise1(z * zones.alpineFreq, zones.seed + 23));
  const mixDial = smoothstep(0.34, 0.66, noise1(z * zones.mixFreq, zones.seed + 17));

  const P = zones.park;
  const parkF = windowAt(z, P.period, P.chance, P.span, 701);

  const parkW = parkF * (1 - stone);
  const alpine = high * (1 - parkW) * (1 - stone * 0.6);
  const rocky = stone * (1 - parkF) * (1 - alpine * 0.5);
  const open = Math.max(0, 1 - parkW - rocky - alpine);
  const woods = forest * open;
  out.park = parkW;
  out.rocky = rocky;
  out.alpine = alpine;
  out.meadow = open - woods;
  out.pine = woods * (1 - mixDial);
  out.mixed = woods * mixDial;
  out.expSide = hash2(Math.floor(-z / 600), 313, 93) < 0.5 ? -1 : 1;
  return out;
}

/* ==========================================================================
   Ponds — a basin the height field digs, and a water level to fill it to.
   ========================================================================== */

/* The pond in range of this z, if any: {live, cz, cx, radius, depth}. */
const pondScratch = { live: 0, cz: 0, cx: 0, radius: 0, depth: 0, level: 0 };

export function pondAt(z) {
  pondScratch.live = 0;
  const b = Math.floor(-z / ponds.period);
  for (let k = 0; k <= 1; k++) {
    const bb = b - k;
    if (bb < 1) continue;
    if (hash2(bb, 4441, 71) > ponds.chance) continue;
    const cz = -(bb * ponds.period) - ponds.period * 0.5 * hash2(bb, 173, 72);
    const radius = ponds.radius[0] + (ponds.radius[1] - ponds.radius[0]) * hash2(bb, 907, 73);
    if (Math.abs(z - cz) > radius * 1.6) continue;
    const side = hash2(bb, 311, 74) < 0.5 ? -1 : 1;
    const cx = guideAt(cz) + side * (radius + trail.bed + 6 + 14 * hash2(bb, 613, 75));
    pondScratch.live = 1;
    pondScratch.cz = cz;
    pondScratch.cx = cx;
    pondScratch.radius = radius;
    pondScratch.depth = ponds.depth;
    // Water sits a little under the plane the grade says this z is on.
    pondScratch.level = baseAt(cz) - ponds.depth * 0.45;
    return pondScratch;
  }
  return pondScratch;
}

/* ==========================================================================
   The height, as a row and a point on it
   ========================================================================== */

function makeContext() {
  return {
    z: NaN,
    base: 0, half: 0, tilt: 0, bedBump: 0, roadBump: 0,
    nTrails: 0,
    trails: [
      { x: 0, bed: 0, shoulder: 0, kind: 0, live: 0 },
      { x: 0, bed: 0, shoulder: 0, kind: 0, live: 0 },
      { x: 0, bed: 0, shoulder: 0, kind: 0, live: 0 },
    ],
    pine: 0, mixed: 0, meadow: 1, rocky: 0, park: 0, alpine: 0, expSide: 1,
    ridgeAmp: 0, rollAmp: 0, bumpAmp: 0,
    pondLive: 0, pondCx: 0, pondCz: 0, pondR: 0, pondDepth: 0, pondLevel: 0,
  };
}

const zoneScratch = {};

/* The bed's along-run profile: a quiet pump wave everywhere, and in the
   parks rollers and tabletop kickers. */
function bedBumpAt(z, parkF, rocky) {
  const s = -z;
  let h = 0.11 * Math.sin(s * (TAU / 19)) * (1 - rocky * 0.8);
  if (parkF > 0.01) {
    h += park.rollerAmp * parkF * (0.5 - 0.5 * Math.cos(s * (TAU / park.rollerWave)));
    const u = s % park.kickerEvery;
    const L = park.kickerLength;
    if (u < L) h += park.kickerHeight * parkF * smooth01(u / L);
    else if (u < L + 2) h += park.kickerHeight * parkF;
    else if (u < L + 2 + 7) h += park.kickerHeight * parkF * (1 - smooth01((u - L - 2) / 7));
  }
  return h;
}

function rowContext(z, ctx) {
  if (ctx.z === z) return ctx;
  ctx.z = z;
  ctx.base = baseAt(z);
  ctx.nTrails = trailsAt(z, ctx.trails);
  ctx.half = corridorHalfAt(z);
  ctx.tilt = bermTiltAt(z);

  const zn = zoneAt(z, zoneScratch);
  ctx.pine = zn.pine;
  ctx.mixed = zn.mixed;
  ctx.meadow = zn.meadow;
  ctx.rocky = zn.rocky;
  ctx.park = zn.park;
  ctx.alpine = zn.alpine;
  ctx.expSide = zn.expSide;

  ctx.bedBump = bedBumpAt(z, zn.park, zn.rocky);
  // The road is graded flat: washboard only, no rollers.
  ctx.roadBump = 0.05 * Math.sin(-z * (TAU / 7));

  const p = pondAt(z);
  ctx.pondLive = p.live;
  ctx.pondCx = p.cx;
  ctx.pondCz = p.cz;
  ctx.pondR = p.radius;
  ctx.pondDepth = p.depth;
  ctx.pondLevel = p.level;

  // What this chapter's ground is made of.
  ctx.ridgeAmp = ridges.amp * (0.55 + 1.15 * zn.rocky + 0.7 * zn.alpine) * (1 - 0.55 * zn.meadow);
  ctx.rollAmp = rolls.amp * (1 - 0.6 * zn.meadow - 0.3 * zn.park + 0.4 * zn.alpine);
  ctx.bumpAmp = bumps.amp * (0.6 + 1.0 * (zn.pine + zn.mixed) + 1.2 * zn.rocky
    + 0.9 * zn.alpine - 0.5 * zn.meadow - 0.5 * zn.park);
  return ctx;
}

function heightIn(ctx, x, detail = 1) {
  const z = ctx.z;
  let h = ctx.base;

  /* Which trail owns this point. `trailF` is the strongest bed mask of any
     live line, so two beds crossing make one flat plaza rather than two
     ridges fighting; `own` is the nearest line, which supplies the bed's
     tilt and profile. */
  let trailF = 0;
  let own = ctx.trails[0];
  let ownDx = x - own.x;
  let bestD = Infinity;
  for (let i = 0; i < ctx.nTrails; i++) {
    const t = ctx.trails[i];
    const dx = x - t.x;
    const ad = Math.abs(dx);
    const f = (1 - smoothstep(t.bed, t.bed + t.shoulder, ad)) * t.live;
    if (f > trailF) trailF = f;
    if (ad < bestD) {
      bestD = ad;
      own = t;
      ownDx = dx;
    }
  }
  const off = 1 - trailF;

  // Distance from the valley's own centre, for the dish and the walls.
  const dMid = Math.abs(x - ctx.trails[0].x);

  if (off > 0.001) {
    const wx = x + snoise2(x * warp.freq, z * warp.freq, warp.seed) * warp.amp;
    const wz = z + snoise2(x * warp.freq, z * warp.freq, warp.seed + 1) * warp.amp;
    const ridgeX = x * 0.966 - z * 0.259;
    const ridgeZ = x * 0.259 + z * 0.966;
    const rollX = wx * 0.819 + wz * 0.574;
    const rollZ = -wx * 0.574 + wz * 0.819;
    h += snoise2(ridgeX * ridges.freq, ridgeZ * ridges.freq, ridges.seed) * ctx.ridgeAmp * off;
    h += snoise2(rollX * rolls.freq, rollZ * rolls.freq, rolls.seed) * ctx.rollAmp * off;
    if (detail > 0.001) {
      h += snoise2(wx * bumps.freq, wz * bumps.freq, bumps.seed) * ctx.bumpAmp * off * detail;
      h += snoise2(x * chatter.freq, z * chatter.freq, chatter.seed) * chatter.amp * off * detail;
      if (ctx.rocky + ctx.alpine > 0.02) {
        h += Math.abs(snoise2(x * 0.06, z * 0.045, 57)) * 1.9 * (ctx.rocky + ctx.alpine * 0.7) * off;
      }
    }
  }

  // The corridor dish, and a shallower gather onto the main line.
  const u = Math.min(1, dMid / Math.max(1, ctx.half));
  h += corridor.bowl * u * u;
  const gd = Math.min(1, dMid / 22);
  h += 1.1 * gd * gd * (1 - smoothstep(ctx.half - 2, ctx.half, dMid));

  // The pond's basin — dug before the beds are laid, so a trail that
  // passes a pond runs along its shore rather than through the water.
  if (ctx.pondLive) {
    const px = (x - ctx.pondCx) / ctx.pondR;
    const pz = (z - ctx.pondCz) / ctx.pondR;
    const r2 = px * px + pz * pz;
    if (r2 < 1) {
      const f = 1 - r2;
      h -= ctx.pondDepth * f * f;
    }
  }

  // The beds themselves.
  if (trailF > 0.001) {
    const isRoad = own.kind === KIND_ROAD;
    const bedH = ctx.base
      + (isRoad ? road.crown : trail.crown)
      + (isRoad ? 0 : ctx.tilt * ownDx)
      + (isRoad ? ctx.roadBump : ctx.bedBump);
    h = h * off + bedH * trailF;
  }

  // Beyond the corridor: shoulder rise, then flanks, forever upward.
  const past = dMid - ctx.half;
  if (past > 0) {
    h += valley.rise * smooth01(Math.min(1, past / valley.band));
    const w = past - valley.band;
    if (w > 0) {
      const uu = w / valley.scale;
      h += valley.height * (1 - Math.exp(-uu * uu));
      h += valley.creep * (w - valley.creepEase * (1 - Math.exp(-w / valley.creepEase)));
      const arrive = smoothstep(4, 30, w);
      const left = x < ctx.trails[0].x;
      h += (Math.abs(snoise2(w * 0.035, z * 0.022, left ? 101 : 203)) * 11
        + snoise2(w * 0.08, z * 0.05, left ? 307 : 409) * 4.5) * arrive;
    }
  }

  // Rocky exposure: one side falls away into a ravine beside the trail.
  if (ctx.rocky > 0.03) {
    const dxe = (x - ctx.trails[0].x) * ctx.expSide;
    if (dxe > trail.bed + trail.shoulder) {
      const E = zones.exposure;
      const e = smooth01(Math.min(1, (dxe - trail.bed - trail.shoulder) / E.reach));
      h -= E.drop * e * ctx.rocky;
    }
  }

  return h;
}

const scratch = makeContext();

export function heightAt(x, z) {
  return heightIn(rowContext(z, scratch), x);
}

const EPS = 0.35;

export function normalFrom(fn, x, z, out) {
  const dx = (fn(x + EPS, z) - fn(x - EPS, z)) / (2 * EPS);
  const dz = (fn(x, z + EPS) - fn(x, z - EPS)) / (2 * EPS);
  return out.set(-dx, 1, -dz).normalize();
}

/* ==========================================================================
   What the ground is made of — {grass, dirt, gravel, rock}, summing to one.
   ========================================================================== */

const surfMaterial = { grass: 0, dirt: 1, gravel: 0, rock: 0 };

export function surfaceAt(x, z) {
  const ctx = rowContext(z, scratch);
  let trailF = 0;
  let ownKind = KIND_TRAIL;
  let bestD = Infinity;
  for (let i = 0; i < ctx.nTrails; i++) {
    const t = ctx.trails[i];
    const ad = Math.abs(x - t.x);
    const f = (1 - smoothstep(t.bed, t.bed + t.shoulder, ad)) * t.live;
    if (f > trailF) trailF = f;
    if (ad < bestD) { bestD = ad; ownKind = t.kind; }
  }

  let bedDirt;
  let bedGravel;
  let bedRock;
  if (ownKind === KIND_ROAD) {
    bedDirt = 0.45;
    bedGravel = 0.5;
    bedRock = 0.05;
  } else {
    bedDirt = ctx.park * 1.0 + (ctx.pine + ctx.mixed) * 0.85 + ctx.meadow * 0.6
      + ctx.rocky * 0.15 + ctx.alpine * 0.3;
    bedGravel = ctx.rocky * 0.62 + ctx.alpine * 0.5 + (ctx.pine + ctx.mixed) * 0.15
      + ctx.meadow * 0.12;
    bedRock = ctx.rocky * 0.23 + ctx.alpine * 0.15;
  }
  const bedGrass = Math.max(0, 1 - bedDirt - bedGravel - bedRock);

  const offGrass = ctx.meadow * 0.92 + ctx.mixed * 0.5 + ctx.pine * 0.25
    + ctx.park * 0.75 + ctx.alpine * 0.4;
  const offDirt = ctx.pine * 0.6 + ctx.mixed * 0.4 + ctx.meadow * 0.08 + ctx.park * 0.25;
  const offGravel = ctx.rocky * 0.3 + ctx.alpine * 0.35;
  const offRock = Math.max(0, 1 - Math.min(1, offGrass + offDirt + offGravel));

  const g = trailF;
  surfMaterial.grass = bedGrass * g + offGrass * (1 - g);
  surfMaterial.dirt = bedDirt * g + offDirt * (1 - g);
  surfMaterial.gravel = bedGravel * g + offGravel * (1 - g);
  surfMaterial.rock = bedRock * g + offRock * (1 - g);
  return surfMaterial;
}

/* ==========================================================================
   The grid
   ========================================================================== */

function graded(step, growth, reach, uniformReach = 0) {
  const out = [0];
  let d = 0;
  let s = step;
  while (d < reach) {
    d += s;
    out.push(d);
    if (d >= uniformReach) s *= growth;
  }
  return out;
}

const half = graded(TERRAIN.spacing, TERRAIN.sideGrowth, TERRAIN.side, TERRAIN.uniformNear);
const xs = [];
for (let i = half.length - 1; i >= 1; i--) xs.push(-half[i]);
for (let i = 0; i < half.length; i++) xs.push(half[i]);

const bwd = graded(TERRAIN.spacing, TERRAIN.behindGrowth, TERRAIN.behind, TERRAIN.uniformNear);
const fwd = graded(TERRAIN.spacing, TERRAIN.aheadGrowth, TERRAIN.ahead, TERRAIN.uniformNear);
const zs = [];
for (let i = bwd.length - 1; i >= 1; i--) zs.push(bwd[i]);
for (let i = 0; i < fwd.length; i++) zs.push(-fwd[i]);

const vertsX = xs.length;
const vertsZ = zs.length;

const PALETTE = {
  grass: [0.58, 0.70, 0.34],
  meadowDry: [0.74, 0.71, 0.40],
  forestFloor: [0.44, 0.38, 0.27],
  dirt: [0.63, 0.53, 0.39],
  gravel: [0.66, 0.64, 0.58],
  rock: [0.55, 0.54, 0.52],
  rockWarm: [0.61, 0.56, 0.47],
  parkClay: [0.60, 0.45, 0.32],
  heath: [0.50, 0.55, 0.36],   // alpine highland: heather and old grass
};

export function createTerrain(THREE, maxAnisotropy = 1) {
  const spacing = TERRAIN.spacing;
  const cols = vertsX - 1;
  const rows = vertsZ - 1;
  const count = vertsX * vertsZ;

  const positions = new Float32Array(count * 3);
  const normals = new Float32Array(count * 3);
  const colors = new Float32Array(count * 3);
  const surface = new Float32Array(count * 4);

  const buildPositions = new Float32Array(count * 3);
  const buildNormals = new Float32Array(count * 3);
  const buildColors = new Float32Array(count * 3);
  const buildSurface = new Float32Array(count * 4);

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute('normal', new THREE.BufferAttribute(normals, 3));
  geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  geometry.setAttribute('aSurf', new THREE.BufferAttribute(surface, 4));

  const index = new Uint32Array(cols * rows * 6);
  let o = 0;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const a = r * vertsX + c;
      const b = a + 1;
      const cIx = a + vertsX;
      const dIx = cIx + 1;
      /* Alternate the diagonal so the lattice has no drift direction.
         MIND THE WINDING: rows run in DECREASING z, so the usual
         increasing-z order winds every face downward — a ground backface
         culling deletes the moment you look at it. */
      if ((r + c) & 1) {
        index[o++] = a; index[o++] = b; index[o++] = cIx;
        index[o++] = b; index[o++] = dIx; index[o++] = cIx;
      } else {
        index[o++] = a; index[o++] = dIx; index[o++] = cIx;
        index[o++] = a; index[o++] = b; index[o++] = dIx;
      }
    }
  }
  geometry.setIndex(new THREE.BufferAttribute(index, 1));

  const texLoader = new THREE.TextureLoader();
  const neutral = new THREE.DataTexture(new Uint8Array([150, 150, 150, 255]), 1, 1, THREE.RGBAFormat);
  neutral.needsUpdate = true;

  /* Cloud shadows: three octaves of periodic value noise baked once into a
     small texture that every lit metre of ground shares. */
  const CLOUD_N = 128;
  const cloudData = new Uint8Array(CLOUD_N * CLOUD_N);
  for (let y = 0; y < CLOUD_N; y++) {
    for (let x = 0; x < CLOUD_N; x++) {
      let v = 0;
      let amp = 0.6;
      for (let oct = 1; oct <= 3; oct++) {
        const f = oct * 3;
        const a = (x / CLOUD_N) * TAU;
        const b = (y / CLOUD_N) * TAU;
        v += noise2(Math.cos(a) * f + 7 * oct, Math.sin(b) * f + 13 * oct, 211 + oct) * amp;
        amp *= 0.55;
      }
      cloudData[y * CLOUD_N + x] = Math.round((1 - 0.26 * smoothstep(0.52, 0.78, v)) * 255);
    }
  }
  const cloudTex = new THREE.DataTexture(cloudData, CLOUD_N, CLOUD_N, THREE.RedFormat);
  cloudTex.wrapS = cloudTex.wrapT = THREE.RepeatWrapping;
  cloudTex.magFilter = THREE.LinearFilter;
  cloudTex.minFilter = THREE.LinearFilter;
  cloudTex.needsUpdate = true;

  const texUniforms = {
    tGrass: { value: neutral },
    tFloor: { value: neutral },
    tDirt: { value: neutral },
    tGravel: { value: neutral },
    tCloud: { value: cloudTex },
    uCloudOff: { value: new THREE.Vector2(0, 0) },
    uAnchor: { value: new THREE.Vector2(0, 0) },
  };
  let surfacesLoaded = 0;
  let settle = () => {};
  const surfacesReady = new Promise((resolve) => { settle = resolve; });
  function loadSurface(file, uniform) {
    texLoader.load(
      new URL(`../assets/textures/ground/${file}`, import.meta.url).href,
      (t) => {
        t.wrapS = t.wrapT = THREE.RepeatWrapping;
        t.colorSpace = THREE.SRGBColorSpace;
        t.anisotropy = maxAnisotropy;
        uniform.value = t;
        if (++surfacesLoaded >= 4) settle();
      },
      undefined,
      () => { if (++surfacesLoaded >= 4) settle(); },
    );
  }
  loadSurface('meadow-grass.jpg', texUniforms.tGrass);
  loadSurface('forest-floor.jpg', texUniforms.tFloor);
  loadSurface('dirt-road.jpg', texUniforms.tDirt);
  loadSurface('gravel.jpg', texUniforms.tGravel);

  const material = new THREE.MeshLambertMaterial({ vertexColors: true });
  material.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, texUniforms);
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', `#include <common>
        attribute vec4 aSurf;
        varying vec4 vSurf;
        varying vec2 vWorldXZ;
        uniform vec2 uAnchor;`)
      .replace('#include <begin_vertex>', `#include <begin_vertex>
        vSurf = aSurf;
        vWorldXZ = position.xz + uAnchor;`);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>
        varying vec4 vSurf;
        varying vec2 vWorldXZ;
        uniform sampler2D tGrass, tFloor, tDirt, tGravel, tCloud;
        uniform vec2 uCloudOff;`)
      .replace('#include <color_fragment>', `#include <color_fragment>
        {
          vec2 uvA = vWorldXZ / 3.1;
          vec2 uvB = vWorldXZ / 13.7;
          vec3 g = mix(texture2D(tGrass, uvA).rgb, texture2D(tGrass, uvB).rgb, 0.42);
          vec3 d = mix(texture2D(tDirt, uvA).rgb, texture2D(tDirt, uvB).rgb, 0.42);
          vec3 v = mix(texture2D(tGravel, uvA).rgb, texture2D(tGravel, uvB).rgb, 0.42);
          vec3 f = mix(texture2D(tFloor, uvA).rgb, texture2D(tFloor, uvB).rgb, 0.42);
          float wSum = max(0.001, vSurf.x + vSurf.y + vSurf.z + vSurf.w);
          vec3 tex = (g * vSurf.x + d * vSurf.y + v * vSurf.z + f * vSurf.w) / wSum;
          diffuseColor.rgb *= tex * 2.05;
          diffuseColor.rgb *= texture2D(tCloud, vWorldXZ * 0.0011 + uCloudOff).r;
        }`);
  };
  material.customProgramCacheKey = () => 'sommer-terrain';

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  mesh.receiveShadow = true;

  let anchorX = 0;
  let anchorZ = 0;
  const ctx = makeContext();
  const STRIDE = 8 * spacing;

  function fillRows(ax, az, rowFrom, rowTo, P, N, C, S) {
    for (let r = rowFrom; r < rowTo; r++) {
      const wz = az + zs[r];
      rowContext(wz, ctx);
      const detail = Math.abs(zs[r]) > 220 ? 0 : 1;
      const prevRow = r > 0 ? (r - 1) * vertsX : -1;
      const dzRow = r > 0 ? zs[r] - zs[r - 1] : -1;
      for (let c = 0; c < vertsX; c++) {
        const wx = ax + xs[c];
        const i = r * vertsX + c;
        const h = heightIn(ctx, wx, detail);
        P[i * 3] = xs[c];
        P[i * 3 + 1] = h;
        P[i * 3 + 2] = zs[r];

        const dhx = (heightIn(ctx, wx + EPS, detail) - heightIn(ctx, wx - EPS, detail)) / (2 * EPS);
        const dhz = prevRow >= 0
          ? (h - P[(prevRow + c) * 3 + 1]) / dzRow
          : gradeAt(wz);
        const nl = 1 / Math.hypot(dhx, 1, dhz);
        N[i * 3] = -dhx * nl;
        N[i * 3 + 1] = nl;
        N[i * 3 + 2] = -dhz * nl;

        const m = surfaceAt(wx, wz);
        const slope = Math.hypot(dhx, dhz);
        const steepRock = smoothstep(0.55, 1.1, slope);
        const canopy = ctx.pine + ctx.mixed;
        // Nearest bed, for the wear marks and the duff mask.
        let adg = Infinity;
        for (let t = 0; t < ctx.nTrails; t++) {
          const ad = Math.abs(wx - ctx.trails[t].x);
          if (ad < adg) adg = ad;
        }
        const trailF = 1 - smoothstep(trail.bed, trail.bed + trail.shoulder, adg);
        const floorW = m.dirt * (1 - trailF) * Math.min(1, canopy * 1.5);
        const grass = m.grass * (1 - steepRock);
        const dirt = (m.dirt - floorW) * (1 - steepRock * 0.7);
        const gravelRock = m.gravel + m.rock + steepRock * (m.grass + m.dirt * 0.7);
        S[i * 4] = grass;
        S[i * 4 + 1] = dirt;
        S[i * 4 + 2] = gravelRock;
        S[i * 4 + 3] = floorW;

        const dry = noise2(wx * 0.012, wz * 0.012, 131);
        let r0 = PALETTE.grass[0] + (PALETTE.meadowDry[0] - PALETTE.grass[0]) * dry;
        let g0 = PALETTE.grass[1] + (PALETTE.meadowDry[1] - PALETTE.grass[1]) * dry;
        let b0 = PALETTE.grass[2] + (PALETTE.meadowDry[2] - PALETTE.grass[2]) * dry;
        // Highland turns the grass to heather.
        if (ctx.alpine > 0.02) {
          r0 = r0 * (1 - ctx.alpine) + PALETTE.heath[0] * ctx.alpine;
          g0 = g0 * (1 - ctx.alpine) + PALETTE.heath[1] * ctx.alpine;
          b0 = b0 * (1 - ctx.alpine) + PALETTE.heath[2] * ctx.alpine;
        }
        const rockT = (ctx.rocky > 0.4 || steepRock > 0.5) ? PALETTE.rock : PALETTE.rockWarm;
        const wSum = Math.max(0.001, grass + dirt + gravelRock + floorW);
        let cr = (r0 * grass + PALETTE.dirt[0] * dirt + rockT[0] * gravelRock + PALETTE.forestFloor[0] * floorW) / wSum;
        let cg = (g0 * grass + PALETTE.dirt[1] * dirt + rockT[1] * gravelRock + PALETTE.forestFloor[1] * floorW) / wSum;
        let cb = (b0 * grass + PALETTE.dirt[2] * dirt + rockT[2] * gravelRock + PALETTE.forestFloor[2] * floorW) / wSum;
        if (ctx.park > 0.02 && trailF > 0.3) {
          const p = ctx.park * trailF * 0.7;
          cr = cr * (1 - p) + PALETTE.parkClay[0] * p;
          cg = cg * (1 - p) + PALETTE.parkClay[1] * p;
          cb = cb * (1 - p) + PALETTE.parkClay[2] * p;
        }
        /* Trail wear: two wheel ruts and a darker rim at the verge — the
           small print that makes a track read as ridden rather than drawn. */
        let wear = 1;
        if (trailF > 0.05) {
          const rut = Math.abs(adg - 0.55);
          wear -= 0.10 * trailF * (1 - smoothstep(0.10, 0.42, rut));
          wear -= 0.08 * smoothstep(trail.bed - 0.7, trail.bed, adg) * trailF;
        }
        // Damp ground darkens around a pond.
        if (ctx.pondLive) {
          const pd = Math.hypot(wx - ctx.pondCx, wz - ctx.pondCz) / ctx.pondR;
          if (pd < 1.35) wear *= 1 - 0.22 * (1 - smoothstep(0.9, 1.35, pd));
        }
        const vary = (0.90 + 0.18 * noise2(wx * 0.11, wz * 0.11, 137)) * wear;
        C[i * 3] = cr * vary;
        C[i * 3 + 1] = cg * vary;
        C[i * 3 + 2] = cb * vary;
      }
    }
  }

  function markUpdated() {
    geometry.attributes.position.needsUpdate = true;
    geometry.attributes.normal.needsUpdate = true;
    geometry.attributes.color.needsUpdate = true;
    geometry.attributes.aSurf.needsUpdate = true;
  }

  let build = null;
  const ROWS_PER_FRAME = 22;

  function advanceBuild() {
    if (!build) return;
    const rowTo = Math.min(vertsZ, build.row + ROWS_PER_FRAME);
    fillRows(build.ax, build.az, build.row, rowTo,
      buildPositions, buildNormals, buildColors, buildSurface);
    build.row = rowTo;
    if (build.row >= vertsZ) {
      anchorX = build.ax;
      anchorZ = build.az;
      positions.set(buildPositions);
      normals.set(buildNormals);
      colors.set(buildColors);
      surface.set(buildSurface);
      markUpdated();
      mesh.position.set(anchorX, 0, anchorZ);
      texUniforms.uAnchor.value.set(anchorX, anchorZ);
      build = null;
    }
  }

  function update(x, z, dt = 1 / 60) {
    texUniforms.uCloudOff.value.x += dt * 0.0022;
    texUniforms.uCloudOff.value.y += dt * 0.0006;
    if (build) {
      advanceBuild();
      return;
    }
    const ax = Math.round(x / STRIDE) * STRIDE;
    const az = Math.round(z / STRIDE) * STRIDE;
    if (ax !== anchorX || az !== anchorZ) build = { ax, az, row: 0 };
  }

  function reset(x, z) {
    build = null;
    anchorX = Math.round(x / STRIDE) * STRIDE;
    anchorZ = Math.round(z / STRIDE) * STRIDE;
    fillRows(anchorX, anchorZ, 0, vertsZ, positions, normals, colors, surface);
    markUpdated();
    geometry.computeBoundingSphere();
    mesh.position.set(anchorX, 0, anchorZ);
    texUniforms.uAnchor.value.set(anchorX, anchorZ);
  }

  return { mesh, update, reset, surfacesReady };
}

