input.new_string:
/* The singletrack's own swing inside that valley — this is most of the
   steering the mountain asks for, and the berms are dug where it turns.
   Two scales: long sweeping bends, and tight snaking inside them. */
function swingAt(z) {
  return trail.sweep.amp * snoise2(z * trail.sweep.freq, 0, 73)
    + trail.swing.amp * snoise2(z * trail.swing.freq, 0, 71)
    + trail.swing.amp * 0.45 * Math.sin(z * trail.swing.freq * 2.7 + 1.3);
}

/* The bed's own vertical roll: smooth undulation a rider pumps, never
   chatter. A pure function of z, so the whole width of the bed rises and
   falls together and the surface stays flat across. */
function bedRollAt(z) {
  let h = 0;
  for (let i = 0; i < trail.roll.length; i++) {
    const r = trail.roll[i];
    h += r.amp * Math.sin(-z * (TAU / r.wave) + i * 2.1);
  }
  return h;
}

