1	/* Everything standing on the hill: conifers, birches, bushes, boulders,
2	   grass tufts, wildflowers, fallen logs and trail markers.
3	
4	   Alpen's scheme, whole: every prop is composed primitives baked into one
5	   geometry (geom.js), drawn as InstancedMesh pools, and placed per 40 m
6	   band purely from hashes of the band index — nothing is stored, bands
7	   behind are simply overwritten by bands ahead, and the same band always
8	   grows the same forest. Species and density follow the terrain's own zone
9	   weights, so the pine chapter is the dense dark one, the meadow keeps a
10	   scatter of bushes and a sea of flowers, and the ridge grows krummholz
11	   out of cracks. Nothing stands on the trail bed.
12	
13	   Solids (trunks, boulders, logs) are published per rebuild for the
14	   collision pass. */
15	
16	import { compose } from './geom.js';
17	import { stream, hash2, noise2 } from './noise.js';
18	import { PROPS, TERRAIN } from './config.js';
19	import {
20	  heightAt, guideAt, corridorHalfAt, zoneAt, normalFrom,
21	  trailsAt, bedDistanceAt, pondAt,
22	} from './terrain.js';
23	import { createModelUpgrader } from './importedModels.js';
24	
25	const { band: BAND, ahead: AHEAD, behind: BEHIND, verge: VERGE } = PROPS;
26	const BED = TERRAIN.trail.bed + TERRAIN.trail.shoulder;
27	
28	/* ==========================================================================
29	   Growers
30	   ========================================================================== */
31	
32	function growConifer(THREE, geos, rnd, kind) {
33	  // kind 0: spruce (narrow, dark), 1: pine (broader, warmer), 2: krummholz
34	  const parts = [];
35	  const height = kind === 2 ? 1.6 + rnd() * 1.4 : 5.5 + rnd() * 7.5;
36	  const trunkR = height * 0.022 + 0.05;
37	  const bark = kind === 1 ? 0x6b4f37 : 0x54402e;
38	  parts.push({
39	    geo: geos.cyl, color: bark,
40	    pos: [0, height * 0.28, 0], scale: [trunkR, height * 0.6, trunkR],
41	  });
42	  const tiers = kind === 2 ? 3 : 5 + Math.floor(rnd() * 3);
43	  const spread = kind === 1 ? 0.34 : 0.26;
44	  const g0 = kind === 1 ? [0.38, 0.54, 0.26] : [0.24, 0.46, 0.23];
45	  for (let t = 0; t < tiers; t++) {
46	    const f = t / tiers;
47	    const y = height * (0.22 + 0.78 * f);
48	    const r = height * spread * (1 - f * 0.78) * (0.9 + rnd() * 0.25);
49	    const tall = height * (0.30 - f * 0.10);
50	    const shade = 0.82 + rnd() * 0.4 - f * 0.1;
51	    const c = new THREE.Color(g0[0] * shade, g0[1] * shade, g0[2] * shade);
52	    parts.push({
53	      geo: geos.cone, color: c.getHex(),
54	      pos: [(rnd() - 0.5) * 0.2, y, (rnd() - 0.5) * 0.2],
55	      rot: [(rnd() - 0.5) * (kind === 2 ? 0.5 : 0.1), rnd() * Math.PI, 0],
56	      scale: [r, tall, r],
57	    });
58	  }
59	  return { geo: compose(THREE, parts), height, trunkR: trunkR * 1.6 };
60	}
61	
62	function growBirch(THREE, geos, rnd) {
63	  const parts = [];
64	  const height = 5 + rnd() * 4.5;
65	  const trunkR = height * 0.016 + 0.04;
66	  parts.push({
67	    geo: geos.cyl, color: 0xdcd8ce,
68	    pos: [0, height * 0.35, 0], rot: [0, 0, (rnd() - 0.5) * 0.08],
69	    scale: [trunkR, height * 0.72, trunkR],
70	  });
71	  // Bark scores.
72	  for (let i = 0; i < 3; i++) {
73	    parts.push({
74	      geo: geos.box, color: 0x2e2c28,
75	      pos: [(rnd() - 0.5) * trunkR * 1.6, height * (0.15 + rnd() * 0.4), trunkR * 0.9],
76	      scale: [trunkR * 1.3, 0.05 + rnd() * 0.05, 0.02],
77	    });
78	  }
79	  const crowns = 3 + Math.floor(rnd() * 3);
80	  for (let i = 0; i < crowns; i++) {
81	    const s = 0.9 + rnd() * 0.8;
82	    const g = 0.75 + rnd() * 0.4;
83	    const c = new THREE.Color(0.42 * g, 0.55 * g, 0.24 * g);
84	    parts.push({
85	      geo: geos.sph, color: c.getHex(),
86	      pos: [(rnd() - 0.5) * height * 0.22, height * (0.62 + rnd() * 0.3), (rnd() - 0.5) * height * 0.22],
87	      scale: [height * 0.16 * s, height * 0.14 * s, height * 0.16 * s],
88	    });
89	  }
90	  return { geo: compose(THREE, parts), height, trunkR: trunkR * 1.6 };
91	}
92	
93	function growBush(THREE, geos, rnd) {
94	  const parts = [];
95	  const size = 0.6 + rnd() * 0.9;
96	  const lobes = 2 + Math.floor(rnd() * 3);
97	  for (let i = 0; i < lobes; i++) {
98	    const g = 0.7 + rnd() * 0.5;
99	    const c = new THREE.Color(0.30 * g, 0.44 * g, 0.20 * g);
100	    parts.push({
101	      geo: geos.sph, color: c.getHex(),
102	      pos: [(rnd() - 0.5) * size, size * (0.3 + rnd() * 0.2), (rnd() - 0.5) * size],
103	      scale: [size * (0.6 + rnd() * 0.4), size * (0.45 + rnd() * 0.3), size * (0.6 + rnd() * 0.4)],
104	    });
105	  }
106	  return { geo: compose(THREE, parts), height: size, trunkR: size * 0.7 };
107	}
108	
109	function growBoulder(THREE, geos, rnd) {
110	  const parts = [];
111	  const size = 1;
112	  const g = 0.8 + rnd() * 0.35;
113	  parts.push({
114	    geo: geos.rock, color: new THREE.Color(0.52 * g, 0.51 * g, 0.49 * g).getHex(),
115	    pos: [0, size * 0.32, 0],
116	    rot: [rnd() * 0.6, rnd() * Math.PI, rnd() * 0.6],
117	    scale: [size, size * (0.6 + rnd() * 0.5), size * (0.75 + rnd() * 0.4)],
118	  });
119	  if (rnd() < 0.7) {
120	    const g2 = g * 0.9;
121	    parts.push({
122	      geo: geos.rock, color: new THREE.Color(0.5 * g2, 0.5 * g2, 0.47 * g2).getHex(),
123	      pos: [size * (0.5 + rnd() * 0.3), size * 0.18, (rnd() - 0.5) * size * 0.5],
124	      rot: [rnd(), rnd() * Math.PI, rnd()],
125	      scale: [size * 0.45, size * 0.35, size * 0.4],
126	    });
127	  }
128	  return { geo: compose(THREE, parts), height: 1, trunkR: 0.9 };
129	}
130	
131	function growLog(THREE, geos, rnd) {
132	  const len = 2.5 + rnd() * 2.5;
133	  const r = 0.14 + rnd() * 0.1;
134	  const parts = [{
135	    geo: geos.cyl, color: 0x5a4634,
136	    pos: [0, r * 0.9, 0], rot: [0, 0, Math.PI / 2],
137	    scale: [r, len, r],
138	  }, {
139	    geo: geos.cyl, color: 0x8a7a5c,   // cut face
140	    pos: [len * 0.5 + 0.01, r * 0.9, 0], rot: [0, 0, Math.PI / 2],
141	    scale: [r * 0.98, 0.03, r * 0.98],
142	  }];
143	  return { geo: compose(THREE, parts), height: r * 2, trunkR: len * 0.4 };
144	}
145	
146	function growTuft(THREE, geos, rnd) {
147	  const parts = [];
148	  const blades = 7 + Math.floor(rnd() * 4);
149	  for (let i = 0; i < blades; i++) {
150	    const g = 0.8 + rnd() * 0.5;
151	    const c = new THREE.Color(0.38 * g, 0.52 * g, 0.20 * g);
152	    const h = 0.13 + rnd() * 0.16;
153	    parts.push({
154	      geo: geos.blade, color: c.getHex(),
155	      pos: [(rnd() - 0.5) * 0.3, h * 0.5, (rnd() - 0.5) * 0.3],
156	      rot: [(rnd() - 0.5) * 0.8, rnd() * Math.PI, (rnd() - 0.5) * 0.8],
157	      scale: [0.022, h, 0.022],
158	    });
159	  }
160	  return { geo: compose(THREE, parts) };
161	}
162	
163	function growFlower(THREE, geos, rnd) {
164	  const h = 0.13 + rnd() * 0.1;
165	  const parts = [
166	    { geo: geos.cyl, color: 0x3f5a2a, pos: [0, h * 0.5, 0], scale: [0.007, h, 0.007] },
167	    { geo: geos.sph, color: 0xffffff, pos: [0, h, 0], scale: [0.03, 0.024, 0.03] },
168	  ];
169	  return { geo: compose(THREE, parts) };
170	}
171	
172	function growMarker(THREE, geos) {
173	  const parts = [
174	    { geo: geos.cyl, color: 0x6b5844, pos: [0, 0.55, 0], scale: [0.045, 1.1, 0.045] },
175	    { geo: geos.box, color: 0xd8352a, pos: [0, 1.02, 0], scale: [0.11, 0.11, 0.06] },
176	    { geo: geos.box, color: 0xf5f0e6, pos: [0, 1.02, 0.005], scale: [0.11, 0.035, 0.062] },
177	  ];
178	  return { geo: compose(THREE, parts) };
179	}
180	
181	/* ==========================================================================
182	   Pools
183	   ========================================================================== */
184	
